-- ==============================================================================
-- V17: SEED EXAM DATA FOR KHTN GRADES 6 TO 9 (SEMESTERS 1 & 2)
-- Tổng hợp dữ liệu đề thi, câu hỏi trắc nghiệm, đáp án và ảnh minh họa
-- Áp dụng tự động thông qua Flyway Migration hoặc import trực tiếp vào PostgreSQL
-- ==============================================================================

-- ==============================================================================
-- 0. NÂNG CẤP KIỂU DỮ LIỆU CỘT CHO BẢNG QUESTION, ANSWER, EXAM (VARCHAR(255) -> TEXT)
-- Đảm bảo không bị lỗi "value too long for type character varying(255)"
-- ==============================================================================
ALTER TABLE question ALTER COLUMN explanation TYPE TEXT;
ALTER TABLE question ALTER COLUMN description TYPE TEXT;
ALTER TABLE answer ALTER COLUMN explanation TYPE TEXT;
ALTER TABLE answer ALTER COLUMN description TYPE TEXT;
ALTER TABLE exam ALTER COLUMN description TYPE TEXT;
ALTER TABLE question_image ALTER COLUMN url TYPE TEXT;
ALTER TABLE answer_image ALTER COLUMN url TYPE TEXT;

-- ==============================================================================
-- PHẦN 1. LỚP 6 - GIỮA HỌC KỲ 1 (Nguồn: insert code lớp 6 giữa kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point DOUBLE PRECISION := 0.25; -- Đề 40 câu, thang điểm 10.0
BEGIN
    -- 1. ĐẢM BẢO DANH MỤC: KHỐI LỚP 6
    SELECT id INTO v_class_id FROM grades WHERE grade = 6;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 6', 6, 'Chương trình Khoa học tự nhiên THCS Lớp 6', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. ĐẢM BẢO DANH MỤC: HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 6', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. ĐẢM BẢO DANH MỤC: MÔN KHTN 6
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN6_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 6', 'KHTN6_HK1', 'Môn Khoa học Tự nhiên Lớp 6 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- 4. TẠO ĐỀ THI: ĐỀ SỐ 1
VALUES (
    v_subject_id,
    'DE_GK1_KHTN6_01',
    'Đề thi giữa kì 1 KHTN 6 Kết nối tri thức - Đề số 1',
    'DEFAULT',
    'Khoa học Tự nhiên',
    'Đề kiểm tra giữa học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức.',
    NOW(),
    NOW()
) RETURNING id INTO v_exam_id;

    ----------------------------------------------------------------------
    -- CÂU 1
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Khoa học tự nhiên nghiên cứu về lĩnh vực nào dưới đây?',
        'Khoa học tự nhiên nghiên cứu về: các sự vật, hiện tượng tự nhiên; các quy luật tự nhiên; những ảnh hưởng của tự nhiên đến con người và môi trường sống.',
        'KHTN 6 - Bài mở đầu',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 1, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 2
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Con gà đẻ trứng là thể hiện dấu hiệu nào của vật sống?',
        'Con gà đẻ trứng là thể hiện dấu hiệu sinh sản của vật sống nhằm duy trì nòi giống.',
        'KHTN 6 - Vật sống và vật không sống',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 2, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 3
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Hoạt động nào sau đây của con người không phải là hoạt động nghiên cứu khoa học?',
        'Sản xuất phân bón hóa học là hoạt động sản xuất, ứng dụng; ba hoạt động còn lại là hoạt động nghiên cứu khoa học nhằm tìm tòi, khám phá tri thức mới.',
        'KHTN 6 - Nghiên cứu khoa học',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 3, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 4
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Các bước đo thể tích một hòn đá:' || chr(10) ||
        '(1) Buộc hòn đá vào một sợi dây.' || chr(10) ||
        '(2) Cầm sợi dây, nhúng hòn đá ngập trong nước ở cốc đong, mực nước trong cốc dâng lên.' || chr(10) ||
        '(3) Đặt cốc đong trên mặt phẳng, đổ một lượng nước bằng khoảng thể tích cốc, đọc và ghi lại thể tích nước.' || chr(10) ||
        '(4) Đọc và ghi lại thể tích nước. Lấy thể tích này trừ đi thể tích nước ban đầu ta tính được thể tích hòn đá.' || chr(10) ||
        'Thứ tự thực hiện đúng các bước là:',
        'Thứ tự đúng khi đo thể tích hòn đá bằng cốc đong là: Đặt cốc đong và ghi thể tích nước ban đầu (3) -> Buộc hòn đá vào dây (1) -> Nhúng chìm hòn đá vào nước (2) -> Đọc thể tích dâng lên và tính hiệu số thể tích (4).',
        'KHTN 6 - Kỹ năng đo lường',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 4, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 5
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Hành động nào sau đây không thực hiện đúng quy tắc an toàn trong phòng thực hành:',
        'Không được tự ý đổ hóa chất vào cống thoát nước vì có thể gây ô nhiễm môi trường và hư hại hệ thống đường ống. Hóa chất thải phải được thu gom đúng nơi quy định.',
        'KHTN 6 - Quy tắc an toàn',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 5, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 6 (Có ảnh minh họa)
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Hình ảnh một tế bào (màu xanh) bị nhiễm nặng các hạt virus SARS-CoV-2 (màu vàng), được phân lập từ bệnh nhân COVID-19 và chụp tại NIAID, Fort Detrick, Maryland, Mỹ. (Ảnh: NIAID/AFP). Hình ảnh bên được quan sát qua dụng cụ nào dưới đây?',
        'Tế bào và virus có kích thước siêu nhỏ mà mắt thường hay kính lúp không thể quan sát được, bắt buộc phải quan sát qua kính hiển vi.',
        'KHTN 6 - Kính hiển vi quang học',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 6, v_point, NOW(), NOW());

    VALUES (v_q_id, 'Hình ảnh tế bào nhiễm virus SARS-CoV-2', 'https://img.loigiaihay.com/picture/2022/1101/11.png', 1, NOW());


    ----------------------------------------------------------------------
    -- CÂU 7 (Có ảnh minh họa)
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Chiều dài của chiếc bút chì ở hình vẽ bằng:',
        'Từ vạch số 0 đến vạch số 1 của thước được chia làm 5 khoảng bằng nhau nên độ chia nhỏ nhất (ĐCNN) là 0,2 cm. Đặt mắt nhìn vuông góc với vạch chia gần nhất ở đầu bút chì ta đọc được kết quả là 6,6 cm.',
        'KHTN 6 - Đo chiều dài',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 7, v_point, NOW(), NOW());

    VALUES (v_q_id, 'Hình vẽ đo chiều dài bút chì', 'https://img.loigiaihay.com/picture/2022/1101/12.png', 1, NOW());


    ----------------------------------------------------------------------
    -- CÂU 8
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Dụng cụ dùng để đo khối lượng của một vật là',
        'Cân là dụng cụ tiêu chuẩn dùng để đo khối lượng của vật.',
        'KHTN 6 - Đo khối lượng',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 8, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 9 (Có ảnh minh họa)
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Trước một chiếc cầu có một biển báo giao thông ghi 10T (hình vẽ), con số 10T này có ý nghĩa gì?',
        'Biển báo giao thông giới hạn tải trọng 10T quy định cấm các loại xe có khối lượng toàn bộ (cả xe và hàng hóa) vượt quá 10 tấn đi qua cầu.',
        'KHTN 6 - Đo khối lượng',
        NOW(), NOW()
