    VALUES (v_exam_id, v_q_id, 9, v_point, NOW(), NOW());

    VALUES (v_q_id, 'Biển báo giao thông 10T', 'https://img.loigiaihay.com/picture/2022/1101/13.png', 1, NOW());


    ----------------------------------------------------------------------
    -- CÂU 10
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Nhiệt độ màu đỏ trên nhiệt kế y tế là:',
        'Nhiệt kế y tế dùng để đo thân nhiệt người. Thân nhiệt người bình thường ở mức 37 °C nên mức này thường được đánh dấu bằng màu đỏ.',
        'KHTN 6 - Đo nhiệt độ',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 10, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
    -- CÂU 11 (Có ảnh minh họa)
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Bảng dưới đây ghi tên các loại nhiệt kế và nhiệt độ ghi trên thang đo của chúng. Phải dùng nhiệt kế nào để đo nhiệt độ của bàn là, cơ thể người, nước đang sôi, không khí trong phòng?',
        'Bàn là có nhiệt độ cao: dùng nhiệt kế kim loại (giới hạn đo lớn).' || chr(10) ||
        'Cơ thể người (khoảng 35 °C - 42 °C): dùng nhiệt kế y tế.' || chr(10) ||
        'Nước đang sôi (100 °C): dùng nhiệt kế thủy ngân.' || chr(10) ||
        'Không khí trong phòng: dùng nhiệt kế rượu.',
        'KHTN 6 - Thang nhiệt độ và nhiệt kế',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 11, v_point, NOW(), NOW());

    VALUES (v_q_id, 'Bảng thang đo các loại nhiệt kế', 'https://img.loigiaihay.com/picture/2022/1101/14.png', 1, NOW());


    ----------------------------------------------------------------------
    -- CÂU 12
    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Giá trị nhiệt độ đo được theo thang nhiệt độ Kenvin là 293K. Hỏi theo thang nhiệt độ Farenhai, nhiệt độ đó có giá trị là bao nhiêu? Biết rằng mỗi độ trong thang nhiệt độ Kenvin bằng độ trong thang nhiệt độ Xenxiut và ứng với 273K.',
        'Đổi sang thang Celsius: T(°C) = 293 - 273 = 20 °C.' || chr(10) ||
        'Đổi sang thang Fahrenheit: T(°F) = (20 × 1,8) + 32 = 68 °F.',
        'KHTN 6 - Thang đo nhiệt độ',
        NOW(), NOW()
    ) RETURNING id INTO v_q_id;

    VALUES (v_exam_id, v_q_id, 12, v_point, NOW(), NOW());


    ----------------------------------------------------------------------
