    ----------------------------------------------------------------------
    VALUES (
        'SINGLE_CHOICE',
        'Khi đo thời gian của một hoạt động, ta cần thực hiện các bước:' || chr(10) ||
        '(1) Hiệu chỉnh đồng hồ đúng cách trước khi đo.' || chr(10) ||
        '(2) Đọc và ghi kết quả mỗi lần đo.' || chr(10) ||
