DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point DOUBLE PRECISION := 0.25; -- Đề 40 câu, thang điểm 10.0
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 6
    SELECT id INTO v_class_id FROM grades WHERE grade = 6;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 6', 6, 'Chương trình Khoa học tự nhiên THCS Lớp 6', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 6', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 6
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN6_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 6', 'KHTN6_HK1', 'Môn Khoa học Tự nhiên Lớp 6 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA KÌ 1 KHTN 6 - ĐỀ SỐ 2
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN6_02',
        'Đề thi giữa kì 1 KHTN 6 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khoa học tự nhiên không bao gồm lĩnh vực nào sau đây?', 'Vật lí, hóa học, sinh học, thiên văn học và khoa học Trái Đất là những lĩnh vực chủ yếu của khoa học tự nhiên. Lịch sử loài người không thuộc các lĩnh vực chủ yếu của khoa học tự nhiên.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cần đặt mắt nhìn vào bộ phận nào của kính hiển vi để quan sát ảnh của vật?', 'Cần đặt mắt nhìn vào thị kính để quan sát ảnh của vật qua kính hiển vi.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Kí hiệu cảnh báo dưới đây cho biết điều gì?', 'Kí hiệu ngọn lửa cảnh báo chất dễ cháy.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dùng nhiệt kế rượu không thể đo được nhiệt độ của:', 'Rượu sôi ở khoảng 80°C, thấp hơn nhiệt độ sôi của nước (100°C) nên không thể dùng nhiệt kế rượu để đo nhiệt độ của nước sôi.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trên vỏ túi bột giặt có ghi số chỉ khối lượng, số đó cho ta biết gì?', 'Khối lượng ghi trên bao bì cho biết lượng chất (khối lượng của bột giặt) chứa bên trong túi.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Đo chiều dài của chiếc bút chì theo cách nào sau đây là hợp lí nhất?', 'Cách đo ở hình B đặt một đầu bút chì trùng với vạch số 0 của thước và thước đặt dọc theo chiều dài bút chì là đúng quy tắc.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hành động nào sau đây đảm bảo an toàn trong phòng thực hành:', 'Các hành động A và D sử dụng đầy đủ đồ bảo hộ thí nghiệm; B không đeo bảo hộ và đùa nghịch; C tự ý đổ hóa chất vào bồn cống gây nguy hiểm.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi dùng nhiệt kế để đo nhiệt độ của chính cơ thể mình, người ta phải thực hiện các thao tác sau (chưa được sắp xếp theo đúng thứ tự):' || chr(10) || 'a) Đặt nhiệt kế vào nách trái, rồi kẹp cánh tay lại để giữ nhiệt kế.' || chr(10) || 'b) Lấy nhiệt kế ra khỏi nách để đọc nhiệt độ.' || chr(10) || 'c) Dùng bông lau sạch thân và bầu nhiệt kế.' || chr(10) || 'd) Kiểm tra xem thủy ngân đã tụt hết xuống bầu nhiệt kế chưa, nếu chưa thì vẩy nhiệt kế cho thủy ngân tụt xuống.' || chr(10) || 'Hãy sắp xếp các thao tác trên theo thứ tự hợp lí nhất.', 'Thứ tự đúng: Lau sạch thân và bầu nhiệt kế (c) → Vẩy nhiệt kế cho thủy ngân tụt xuống (d) → Đặt nhiệt kế vào nách (a) → Đọc kết quả sau thời gian quy định (b).', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một xe chở gạo khi lên trạm cân số chỉ là 4,3 tấn và sau khi đổ gạo khỏi xe và cân lại thì xe có khối lượng là 680 kg. Hỏi khối lượng của gạo là bao nhiêu kilogam?', 'Đổi 4,3 tấn = 4300 kg. Khối lượng gạo là: 4300 - 680 = 3620 kg.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho hình vẽ sau, GHĐ và ĐCNN của thước là:', 'Giới hạn đo là độ dài lớn nhất ghi trên thước (20 cm), khoảng cách giữa 2 vạch chia liên tiếp là 1 cm = 10 mm.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi đo thời gian của một hoạt động, ta cần thực hiện các bước:' || chr(10) || '(1) Hiệu chỉnh đồng hồ đúng cách trước khi đo.' || chr(10) || '(2) Đọc và ghi kết quả mỗi lần đo.' || chr(10) || '(3) Ước lượng khoảng thời gian cần đo.' || chr(10) || '(4) Thực hiện đo thời gian bằng đồng hồ.' || chr(10) || '(5) Chọn đồng hồ phù hợp.' || chr(10) || 'Thứ tự đúng là:', 'Các bước chuẩn xác gồm: Ước lượng thời gian (3) → Chọn đồng hồ (5) → Hiệu chỉnh đồng hồ (1) → Thực hiện phép đo (4) → Đọc và ghi kết quả (2).', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ được sử dụng để lấy hóa chất dưới đây được gọi là:', 'Dụng cụ thủy tinh/nhựa có gắn núm cao su dùng để hút và nhỏ giọt dung dịch là ống nhỏ giọt.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Đồng hồ dưới đây chỉ:', 'Kim giờ chỉ qua vạch số 10, kim phút chỉ ở số 2 (10 phút) và kim giây chỉ ở số 7 (35 giây).', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ dùng để đo thân nhiệt trong hình dưới đây là:', 'Thiết bị đo hiển thị nhiệt độ dưới dạng các con số điện tử trên màn hình LCD là nhiệt kế điện tử.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một chú robot có thể cười, nói và hành động như một con người. Vậy robot là vật sống hay vật không sống? Tại sao?', 'Robot là vật không sống vì nó không có các đặc điểm sống cốt lõi như trao đổi chất, hô hấp, lớn lên và sinh sản.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vật thể nào dưới đây vừa là vật thể tự nhiên, vừa là vật không sống?', 'Ngọn núi hình thành tự nhiên (vật thể tự nhiên) và không có các đặc tính sống (vật không sống).', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dấu hiệu chính để phân biệt tính chất vật lí và tính chất hóa học là', 'Tính chất hóa học luôn gắn liền với sự biến đổi hóa học, tức là có chất mới được sinh ra.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tính chất nào sau đây không phải của oxygen?', 'Oxygen là chất khí rất ít tan trong nước.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các câu sau (với cụm từ in nghiêng là vật thể hoặc chất):' || chr(10) || '(1) Máu người chứa một lượng nhỏ glucose với nồng độ hầu như không đổi khoảng 0,1%.' || chr(10) || '(2) Trong sữa chua có chứa lactic acid rất tốt cho hệ tiêu hóa.' || chr(10) || '(3) Vàng là vật liệu phổ biến để chế tạo đồ trang sức.' || chr(10) || '(4) Salicylic acid là thành phần phổ biến trong các loại thuốc trị mụn.' || chr(10) || 'Các vật thể trong câu trên lần lượt là:', 'Vật thể là: máu người, sữa chua, đồ trang sức, thuốc trị mụn. Các từ còn lại (glucose, lactic acid, vàng, salicylic acid) là chất.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một ô tô khi chạy một quãng đường dài 100 km tiêu thụ hết 6 L xăng. Biết khi đốt cháy 1 L xăng, cần 1950 L oxygen. Nếu ta cung cấp 14,04 m³ khí oxygen thì ô tô đó chạy được quãng đường tối đa là', 'Đổi 14,04 m³ = 14040 L khí oxygen. Để đi 100 km cần: 6 × 1950 = 11700 L oxygen. Quãng đường tối đa đi được: (14040 × 100) / 11700 = 120 km.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho các hình vẽ sau: Số hình vẽ thể hiện tính chất hóa học là', 'Trong các hình minh họa: Hình (2) và (5) có sự tạo thành chất mới (tính chất hóa học); các hình (1), (3), (4), (6) là biến đổi trạng thái vật lí.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các phát biểu sau về sự bay hơi:' || chr(10) || '(1) Sự bay hơi chỉ diễn ra trên bề mặt của chất lỏng.' || chr(10) || '(2) Quá trình bay hơi diễn ra nhanh hơn khi diện tích mặt thoáng càng rộng.' || chr(10) || '(3) Nhiệt độ càng cao thì quá trình bay hơi diễn ra càng chậm.' || chr(10) || '(4) Sự bay hơi là một trường hợp đặc biệt của sự sôi.' || chr(10) || '(5) Sự bay hơi diễn ra ở nhiệt độ xác định.' || chr(10) || 'Số phát biểu sai là:', 'Có 3 phát biểu sai: (3) sai vì nhiệt độ càng cao bay hơi càng nhanh; (4) sai vì sự sôi mới là trường hợp đặc biệt của sự bay hơi; (5) sai vì bay hơi diễn ra ở mọi nhiệt độ.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tại sao khi bơm hơi vào lốp xe xong ta phải khóa van lại?', 'Khí có tính chất lan tỏa đều theo mọi hướng trong không gian nên nếu không khóa van thì không khí bị nén bên trong sẽ tràn ra ngoài.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các hiện tượng thực tế sau:' || chr(10) || '(1) Để tạo ra các đồ vật thủy tinh có hình dạng khác nhau người ta đem đun nóng chảy thủy tinh rồi sau đó tạo hình; để nguội ta sẽ thu được các đồ vật.' || chr(10) || '(2) Đổ nước vào khay sau đó để vào tủ lạnh, một thời gian ta sẽ thu được các viên nước đá.' || chr(10) || '(3) Trên các vùng cao, vào lúc sáng sớm thường xuất hiện hiện tượng sương mù.' || chr(10) || '(4) Để sản xuất muối từ nước biển, người ta dẫn nước biển vào các ruộng làm muối. Sau một thời gian, sẽ thu được muối hạt.' || chr(10) || '(5) Trong quá trình làm rượu, người ta đun bỗng rượu ở nhiệt độ khoảng 78°C sau đó dẫn hơi rượu qua ống làm lạnh thu được dung dịch rượu.' || chr(10) || 'Số hiện tượng xảy ra sự đông đặc là:', 'Có 2 hiện tượng xảy ra sự đông đặc (lỏng → rắn): (1) Thủy tinh lỏng để nguội đông cứng lại và (2) Nước lỏng hóa thành đá lạnh.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hiệu ứng nhà kính giúp giữ cho Trái Đất không quá lạnh. Tuy nhiên, ngày nay nhiều hoạt động của con người đã làm gia tăng một lượng lớn chất khí X trong khí quyển, gây ra hiện tượng nóng lên toàn cầu và biến đổi khí hậu. Hàng loạt các biểu hiện của sự nóng lên toàn cầu như: mực nước biển dâng, hạn hán, sa mạc hóa, … Em hãy cho biết chất khí X là chất khí nào sau đây?', 'Khí carbon dioxide (CO2) là khí nhà kính chủ yếu sinh ra từ quá trình đốt nhiên liệu hóa thạch, gây nên hiện tượng ấm lên toàn cầu.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Nối các tế bào ở hàng A với tên tế bào ở hàng B sao cho phù hợp', 'Tổ hợp nối chuẩn: 1 (tế bào hồng cầu) - c; 2 (tế bào cơ) - a; 3 (tế bào thần kinh) - d; 4 (tế bào biểu bì lá) - b.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nhận định nào đúng khi nói về hình dạng và kích thước tế bào?', 'Mỗi loại tế bào đảm nhận chức năng riêng biệt nên thường có hình dạng và kích thước đặc trưng khác nhau.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thành phần chủ yếu của tế bào thực vật gồm:', '4 thành phần cơ bản và chủ yếu bao bọc bảo vệ tế bào thực vật là: Vách tế bào (thành tế bào), màng sinh chất, chất tế bào và nhân.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thành phần nào sau đây có ở cả tế bào động vật và tế bào thực vật', 'Tế bào chất là cấu trúc nền tảng có mặt ở cả tế bào động vật và tế bào thực vật.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tế bào thực vật có kiểu dinh dưỡng là tự dưỡng còn tế bào động vật là dị dưỡng, điểm khác nhau này là do:', 'Tế bào thực vật có chứa bào quan lục lạp chứa chất diệp lục giúp hấp thụ ánh sáng để quang hợp tạo chất hữu cơ.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nếu các tế bào phân chia nhiều lần và cơ thể không kiểm soát được có thể dẫn tới', 'Sự phân chia vô tổ chức, mất kiểm soát của tế bào trong cơ thể sẽ dẫn đến hình thành các khối u (nguy cơ ung thư).', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi nói về thời gian phân chia của các tế bào, phát biểu nào sau đây đúng?', 'Chu kỳ phân chia của tế bào da người thường diễn ra định kỳ trong khoảng từ 10 đến 30 ngày.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình vẽ bên thể hiện quá trình nào của tế bào:', 'Hình vẽ mô tả sự nhân đôi của nhân và hình thành vách ngăn để tách thành 2 tế bào con, tức là quá trình phân chia của tế bào.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm chỉ có ở cơ thể đơn bào là', 'Cơ thể sinh vật nhân sơ luôn luôn là cơ thể đơn bào (như vi khuẩn), sinh vật đa bào chỉ được cấu tạo từ các tế bào nhân thực.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cơ thể đơn bào là cơ thể', 'Sinh vật đơn bào là cơ thể sống chỉ được cấu tạo từ một tế bào duy nhất đảm nhận mọi chức năng sống.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sự phân chia tế bào ở thực vật khác gì so với sự phân chia tế bào ở động vật', 'Do tế bào thực vật có thành cellulose cứng bao quanh nên khi phân chia tế bào chất sẽ hình thành một vách ngăn ở giữa chứ không co thắt màng như ở tế bào động vật.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đâu là một mô', 'Mô là tập hợp các tế bào có cùng cấu trúc và chức năng; tập hợp các tế bào cơ liên kết tại một bắp cơ tạo thành mô cơ.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi cơ thể ngừng lớn, các tế bào', 'Dù cơ thể đã trưởng thành và ngừng lớn, các tế bào vẫn tiếp tục phân chia/sinh sản để tái tạo, sửa chữa tổn thương và thay thế các tế bào già cỗi bị đào thải.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cách đặt lamen đúng là', 'Đặt một cạnh của lamen tiếp xúc nghiêng một góc với giọt nước rồi dùng kim mũi mác hạ từ từ xuống để tránh bọt khí tích tụ bên trong.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đâu là một cơ quan', 'Dạ dày là một cơ quan riêng biệt trong hệ tiêu hóa; hệ tiêu hóa và hệ bài tiết là cấp độ hệ cơ quan.', 'KHTN 6 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI GIỮA KÌ 1 KHTN 6 - ĐỀ SỐ 3
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN6_03',
        'Đề thi giữa kì 1 KHTN 6 Kết nối tri thức - Đề số 3',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 3.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Lĩnh vực chuyên nghiên cứu về thực vật và động vật là', 'Sinh học là lĩnh vực chuyên nghiên cứu về sự sống, cấu tạo và các quy luật hoạt động của sinh vật (bao gồm cả thực vật và động vật).', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Vật nào dưới đây là vật sống?', 'Cây nấm rơm có đầy đủ các dấu hiệu đặc trưng của sự sống như trao đổi chất, lớn lên, sinh sản và cảm ứng.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Kí hiệu cảnh báo hình tam giác viền đen, nền vàng, bên trong có hình ngọn lửa bốc cháy là cảnh báo gì?', 'Biển cảnh báo hình tam giác màu vàng có ngọn lửa biểu thị cảnh báo chất hoặc khu vực dễ gây cháy.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ nào dưới đây thường dùng để đo thể tích chất lỏng trong phòng thực hành?', 'Ống đong (bình chia độ) là dụng cụ chuyên dụng để xác định thể tích của các chất lỏng.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Độ chia nhỏ nhất (ĐCNN) của thước là', 'Độ chia nhỏ nhất của một dụng cụ đo (như thước) là độ dài giữa hai vạch chia liên tiếp nhau trên thang đo.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi đọc kết quả đo độ dài bằng thước, ta cần đặt mắt như thế nào?', 'Đặt mắt theo hướng vuông góc với cạnh thước tại vạch chia tương ứng với đầu kia của vật để tránh sai số do góc nhìn.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đơn vị đo khối lượng hợp pháp trong hệ thống đo lường của nước ta là', 'Đơn vị đo khối lượng chính thức trong hệ SI được Việt Nam áp dụng hợp pháp là kilôgam (kg).', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ nào dưới đây dùng để đo thời gian?', 'Đồng hồ bấm giây là dụng cụ dùng để đo khoảng thời gian diễn ra một sự kiện hoặc hoạt động.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Thang nhiệt độ thường dùng ở Việt Nam là thang nhiệt độ nào?', 'Thang nhiệt độ Xen-xi-út (Celsius, đơn vị kí hiệu là °C) là thang nhiệt độ chuẩn được sử dụng phổ biến tại Việt Nam.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nhiệt kế thủy ngân hoạt động dựa trên hiện tượng nào?', 'Nhiệt kế chất lỏng (như nhiệt kế thủy ngân, nhiệt kế rượu) hoạt động dựa vào nguyên lí sự co dãn nở vì nhiệt của chất lỏng khi thay đổi nhiệt độ.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Để quan sát cấu tạo của các tế bào biểu bì vảy hành, ta cần sử dụng dụng cụ nào?', 'Tế bào biểu bì có kích thước hiển vi, mắt thường và kính lúp không thể nhìn rõ chi tiết cấu trúc nên bắt buộc dùng kính hiển vi quang học.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi quan sát mẫu vật bằng kính hiển vi quang học, bộ phận nào giúp điều chỉnh lượng ánh sáng chiếu vào mẫu vật?', 'Gương phản chiếu cùng bộ phận chắn sáng (màng chắn) điều tiết cường độ chùm sáng hội tụ chiếu vào mẫu vật trên bàn kính.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây thể hiện tính chất vật lí của chất?', 'Băng phiến thăng hoa (từ rắn sang hơi) không sinh ra chất mới nên là biến đổi thể/tính chất vật lí. Các trường hợp còn lại đều tạo thành chất mới nên thuộc tính chất hóa học.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quá trình chuyển từ thể lỏng sang thể rắn của một chất được gọi là', 'Quá trình một chất từ trạng thái lỏng biến đổi thành trạng thái rắn gọi là sự đông đặc.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Sự sôi là quá trình', 'Sôi là hiện tượng chất lỏng chuyển hóa thành hơi diễn ra đồng thời ở cả trên mặt thoáng lẫn bên trong lòng khối chất lỏng tại nhiệt độ sôi xác định.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khí nào duy trì sự sống (hô hấp) và sự cháy?', 'Oxygen (O₂) là dưỡng khí duy nhất duy trì sự hô hấp của sinh vật và duy trì sự cháy.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Thành phần chính của không khí sạch gồm có:', 'Không khí khô gồm xấp xỉ 78% thể tích là khí nitrogen, 21% là khí oxygen, 1% còn lại là hơi nước, carbon dioxide và khí hiếm.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng nào sau đây không phải là tác nhân gây ô nhiễm môi trường không khí?', 'Quá trình quang hợp của cây xanh hấp thụ bớt CO₂ và nhả ra khí oxygen giúp làm sạch và trong lành bầu không khí.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Để dập tắt ngọn lửa do xăng dầu cháy, ta không được dùng chất nào dưới đây?', 'Xăng dầu nhẹ hơn nước và không tan trong nước, dội nước vào sẽ làm xăng dầu nổi lên bề mặt và tràn rộng ra, khiến đám cháy bùng phát dữ dội hơn.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Vật liệu nào sau đây có tính đàn hồi cao, không dẫn điện và dẫn nhiệt kém?', 'Cao su có khả năng đàn hồi tốt, cách điện, cách nhiệt và không thấm nước.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Để sản xuất xi măng, người ta sử dụng nguồn nguyên liệu tự nhiên nào là chính?', 'Đá vôi (CaCO₃) cùng với đất sét là các nguồn nguyên liệu chính trong công nghiệp sản xuất vôi và xi măng.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nhiên liệu nào sau đây là nhiên liệu hóa thạch?', 'Dầu mỏ, than đá và khí thiên nhiên là các nhiên liệu hóa thạch được hình thành từ xác sinh vật qua hàng triệu năm dưới lòng đất.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Việc sử dụng than đá, dầu mỏ làm nhiên liệu giải phóng nhiều khí CO₂ vào khí quyển gây nên tác hại:', 'Khí carbon dioxide (CO₂) tích tụ nhiều giữ lại nhiệt bức xạ của bề mặt đất, dẫn đến hiệu ứng nhà kính và làm khí hậu toàn cầu nóng dần lên.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nhóm thực phẩm nào giàu protein (chất đạm) nhất?', 'Thịt, cá, trứng, sữa và các hạt họ đậu là nguồn cung cấp dồi dào hàm lượng chất đạm (protein) thiết yếu cho cơ thể.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Đơn vị cấu trúc cơ bản của mọi cơ thể sống là', 'Mọi sinh vật sống dù đơn giản hay phức tạp đều được cấu tạo từ các viên gạch nền móng cơ bản là tế bào.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Thành phần nào kiểm soát sự di chuyển của các chất đi vào và đi ra khỏi tế bào?', 'Màng sinh chất là lớp màng bán thấm bao bọc bên ngoài khối tế bào chất, có vai trò bảo vệ và chọn lọc trao đổi chất giữa tế bào với môi trường ngoài.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Bào quan nào là "trung tâm điều khiển" mọi hoạt động sống của tế bào?', 'Nhân chứa vật chất di truyền (ADN), chỉ đạo và kiểm soát mọi hoạt động sống, sinh trưởng và phân chia của tế bào.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Điểm khác biệt cơ bản giữa tế bào nhân sơ và tế bào nhân thực là:', 'Tế bào nhân sơ chưa có nhân hoàn chỉnh (chỉ có vùng nhân chứa ADN trần, không có màng nhân), còn tế bào nhân thực đã có màng nhân phân tách với tế bào chất.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Bào quan chỉ có ở tế bào thực vật mà không có ở tế bào động vật là:', 'Lục lạp (chứa chất diệp lục giúp quang hợp) và thành tế bào cellulose là các cấu trúc đặc trưng có ở tế bào thực vật nhưng vắng mặt ở tế bào động vật.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Tế bào thực hiện quá trình lớn lên và phân chia giúp cơ thể', 'Sự tăng kích thước và gia tăng số lượng tế bào qua phân chia là cơ sở giúp sinh vật sinh trưởng, lớn lên và tái tạo các mô bị thương/già cỗi.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Sinh vật nào sau đây là cơ thể đơn bào?', 'Trùng roi là sinh vật chỉ được cấu tạo từ một tế bào duy nhất hoạt động như một cơ thể độc lập (cơ thể đơn bào).', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cơ thể đa bào được cấu tạo từ:', 'Cơ thể đa bào gồm nhiều tế bào phân hóa, cấu tạo thành các mô, cơ quan để cùng thực hiện nhịp nhàng các hoạt động sống.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cấp độ tổ chức liền kề phía sau cấp độ "Tế bào" ở cơ thể đa bào là', 'Cấp độ tăng dần: Tế bào → Mô → Cơ quan → Hệ cơ quan → Cơ thể. Do đó cấp độ sau tế bào là mô.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Tập hợp các tế bào có cùng hình dạng, cấu tạo và cùng thực hiện một chức năng nhất định được gọi là', 'Theo định nghĩa, mô là tập hợp các tế bào có cấu trúc và chức năng tương tự nhau.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Ở cơ thể thực vật, lá cây, hoa, quả, rễ được xếp vào cấp độ tổ chức nào?', 'Rễ, thân, lá, hoa, quả, hạt ở thực vật đều là các cơ quan chuyên biệt đảm nhiệm những chức năng sinh dưỡng và sinh sản.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cơ quan nào sau đây thuộc hệ tuần hoàn ở người?', 'Tim và mạng lưới mạch máu cấu tạo nên hệ tuần hoàn đảm nhận chức năng co bóp lưu thông máu nuôi cơ thể.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào sau đây là ví dụ về phối hợp hoạt động giữa các hệ cơ quan khi con người chạy bộ?', 'Khi cơ bắp vận động mạnh (hệ vận động), nhu cầu năng lượng và oxy tăng lên, kích thích tim đập nhanh (hệ tuần hoàn) và thở gấp, thở sâu (hệ hô hấp) để phối hợp đáp ứng.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi làm tiêu bản tế bào biểu bì vảy hành, ta sử dụng hóa chất nào để nhuộm màu giúp quan sát nhân tế bào rõ hơn dưới kính hiển vi?', 'Dung dịch thuốc nhuộm tế bào (iodine hoặc xanh methylen) bám mạnh vào cấu trúc nhân và chất nguyên sinh, giúp tương phản rõ rệt dưới kính hiển vi.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Để chuẩn bị mẫu nước ngâm quan sát sinh vật đơn bào (trùng roi, trùng giày), người ta thường lấy nguồn nước từ đâu?', 'Nước ngâm rơm cỏ rạ hoặc nước tù đọng ở ao hồ giàu chất hữu cơ phân hủy, là môi trường sinh sản phong phú của các vi sinh vật đơn bào như trùng giày, trùng roi.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hành động nào sau đây thể hiện việc bảo vệ sức khỏe hệ tiêu hóa ở người?', 'Ăn chín uống sôi phòng ngừa giun sán, vi khuẩn; nhai kĩ và ăn đủ chất xơ hỗ trợ dạ dày, ruột tiêu hóa và nhu động ruột hoạt động trơn tru.', 'KHTN 6 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN III: ĐỀ THI GIỮA KÌ 1 KHTN 6 - ĐỀ SỐ 4
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN6_04',
        'Đề thi giữa kì 1 KHTN 6 Kết nối tri thức - Đề số 4',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 4.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đối tượng nghiên cứu của lĩnh vực Hóa học là gì?', 'Đối tượng nghiên cứu của lĩnh vực Hóa học là chất và sự biến đổi của các chất.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Con hổ đang săn mồi là thể hiện dấu hiệu nào của vật sống?', 'Hoạt động săn mồi, chạy đuổi con mồi của hổ thể hiện dấu hiệu vận động của vật sống.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào dưới đây là biểu hiện sự sinh sản ở cây cam?', 'Ra hoa, tạo quả và hạt là giai đoạn sinh sản tạo ra thế hệ mới ở thực vật có hoa. Các phương án còn lại là biểu hiện của sự lớn lên (sinh trưởng).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Kí hiệu trong hình vẽ bên thể hiện điều gì?', 'Kí hiệu hình chất lỏng đổ ăn mòn bề mặt kim loại và bàn tay là biểu tượng cảnh báo chất ăn mòn.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Để đảm bảo an toàn trong phòng thực hành cần thực hiện nguyên tắc nào dưới đây?', 'Học sinh cần đọc kĩ nội quy và tuyệt đối tuân thủ theo các quy tắc trong phòng thực hành để đảm bảo an toàn.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hành động nào sau đây không thực hiện đúng quy tắc an toàn trong phòng thực hành?', 'Tự ý làm theo các thí nghiệm xem trên mạng khi chưa được kiểm chứng, chưa có sự đồng ý và hướng dẫn của giáo viên tiềm ẩn nguy cơ cháy nổ, mất an toàn.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hãy cho biết tên của các dụng cụ trong hình bên và công dụng của chúng?', 'Dụng cụ trong hình là đồng hồ bấm giây điện tử, dùng để đo thời gian chuyển động hoặc diễn ra của sự vật, hiện tượng.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Đo nhiệt độ cơ thể của một người bằng nhiệt kế y tế, kết quả được thể hiện ở hình ảnh dưới. Hãy đọc số đo nhiệt độ và cho biết nhiệt độ của người này có bình thường không?', 'Cột thủy ngân chỉ mức 38,5°C. Nhiệt độ cơ thể người bình thường dao động quanh mức 36,5°C – 37°C; ở mức 38,5°C người này đang bị sốt.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Để quan sát tế bào cơ thể người bị tổn thương do virus corona, người ta sử dụng', 'Tế bào có kích thước hiển vi (vài đến vài chục micromet), mắt thường hoặc kính lúp không thể nhìn rõ, cần sử dụng kính hiển vi quang học hoặc điện tử.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Kính lúp được sử dụng trong trường hợp nào dưới đây?', 'Kính lúp phóng đại các vật nhỏ ở cự li gần từ 3 đến 20 lần, thích hợp để quan sát gân lá, côn trùng nhỏ.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Để đo thể tích một viên sỏi, người ta thực hiện thí nghiệm như hình vẽ bên. Xác định thể tích của viên sỏi.', 'Mực nước ban đầu là V₁ = 70 ml. Khi thả viên sỏi chìm hoàn toàn trong nước, mực nước dâng lên V₂ = 86 ml. Thể tích của viên sỏi là: V = V₂ - V₁ = 86 - 70 = 16 ml.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Xác định GHĐ và ĐCNN của thước dưới đây:', 'Số lớn nhất ghi trên thước là 20 cm (GHĐ = 20 cm). Khoảng cách giữa 2 vạch chia liên tiếp là 1 mm (ĐCNN = 1 mm).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Năm vận động viên Tuấn, Tú, Kiệt, An và Hợp chạy thi. Kết quả không có hai bạn nào về đích cùng một lúc. Tuấn về đích trước Tú nhưng sau Hợp. Hợp và Kiệt không về đích liền kề nhau, An không về đích liền kề với Hợp, Tuấn và Kiệt. Hãy xác định thứ tự về đích của năm vận động viên nói trên.', 'Tuấn về đích trước Tú nhưng sau Hợp → thứ tự: Hợp, ..., Tuấn, ..., Tú. An không về đích liền kề với Hợp, Tuấn, Kiệt → An phải đứng cạnh Tú ở cuối hàng (vị trí số 5). Hợp và Kiệt không liền kề nhau → vị trí số 2 phải là Tuấn, tiếp đến Kiệt rồi đến Tú: Hợp (1) – Tuấn (2) – Kiệt (3) – Tú (4) – An (5).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Trong các hình bên, hình nào vẽ đúng vị trí đặt thước để đo chiều dài bút chì?', 'Đặt thước dọc theo chiều dài của vật, một đầu của vật trùng với vạch số 0 của thước hoặc trùng với một vạch chia rõ ràng (hình b và hình c đều đặt dọc đúng mép, hình a đặt chéo sai quy cách).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cân một túi kẹo, kết quả là 140,3 g. ĐCNN của cân đã dùng là', 'Kết quả đo có phần thập phân đến 1 chữ số sau dấu phẩy (0,3 g), do đó ĐCNN của chiếc cân này là 0,1 g.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vật thể nào dưới đây vừa là vật thể tự nhiên, vừa là vật sống?', 'Ngựa vằn có nguồn gốc tự nhiên và có các đặc tính của sự sống (trao đổi chất, sinh trưởng, sinh sản,...). Dãy núi và biển là vật không sống; thước kẻ là vật thể nhân tạo.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Quá trình nào sau đây thể hiện tính chất hóa học?', 'Đun nóng đường chuyển sang màu đen (cháy thành than) có sự tạo thành chất mới nên đây là hiện tượng/tính chất hóa học. Các hiện tượng còn lại chỉ là sự biến đổi vật lí về trạng thái.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây về oxygen là không đúng?', 'Oxygen tan ít trong nước chứ không phải hoàn toàn không tan. Nhờ lượng oxygen tan này mà các loài thủy sinh có thể hô hấp và sống được.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các câu sau (với cụm từ in nghiêng là vật thể hoặc chất):' || chr(10) || '(1) Đồng thường được sử dụng làm dây dẫn điện.' || chr(10) || '(2) Trong không khí có chứa khoảng 21% oxygen về thể tích.' || chr(10) || '(3) Lọ đựng hoa được làm từ thủy tinh.' || chr(10) || '(4) Paracetamol là thành phần chính của thuốc điều trị cảm cúm.' || chr(10) || 'Các chất trong câu trên lần lượt là', 'Các chất cấu tạo nên vật thể gồm có: đồng, oxygen, thủy tinh, paracetamol. Dây dẫn điện, không khí, lọ hoa, viên thuốc là vật thể.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Khi đun bếp củi nếu lửa sắp tàn, ta thêm củi và thổi hoặc quạt lửa vào bếp thì ngọn lửa sẽ cháy bùng lên. Vậy trong quá trình trên ta đã tác động lên yếu tố nào của sự cháy?', 'Thêm củi là bổ sung thêm chất cháy; thổi hoặc quạt là bổ sung thêm khí oxygen giúp duy trì và tăng cường sự cháy.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Quá trình nào dưới đây không làm giảm oxygen trong không khí?', 'Quá trình quang hợp hấp thụ khí carbon dioxide (CO₂) và giải phóng khí oxygen (O₂) vào khí quyển.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các quá trình sau:' || chr(10) || '(a) Lưu huỳnh cháy trong không khí tạo thành chất khí mùi hắc (khí sulfur dioxide).' || chr(10) || '(b) Thủy tinh nóng chảy được thổi thành hình cầu.' || chr(10) || '(c) Trong lò nung đá vôi, calcium carbonate chuyển dần thành vôi sống (calcium oxide) và khí carbon dioxide thoát ra ngoài.' || chr(10) || '(d) Cồn để trong lọ không kín bị bay hơi.' || chr(10) || 'Số quá trình thể hiện tính chất vật lí là', 'Quá trình thể hiện tính chất vật lí gồm có (b) thủy tinh nóng chảy đổi hình dạng và (d) cồn bay hơi (chỉ chuyển trạng thái thể, không tạo chất mới). Các quá trình (a) và (c) là phản ứng hóa học tạo chất mới.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong tiết Khoa học tự nhiên, khi thảo luận về nghề làm muối thì hai bạn An và Hải đã đưa ra các nhận định sau:' || chr(10) || 'An: Mình nghĩ khi làm muối đã xảy ra hiện tượng bay hơi nước, chỉ còn lại các hạt muối.' || chr(10) || 'Hải: Còn mình nghĩ là khi làm muối đã xảy ra hiện tượng đông đặc vì chất đã chuyển từ thể lỏng (nước muối) sang thể rắn (muối).' || chr(10) || 'Vậy theo em bạn nào đã có nhận định đúng?', 'Khi phơi nước biển dưới nắng, nhiệt độ làm nước bay hơi đi, chất tan là muối kết tinh lắng lại thành hạt. Đây là hiện tượng bay hơi, không phải đông đặc do nhiệt độ giảm.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các tính chất sau: hình dạng xác định (1); khó bị nén (2); thể tích xác định (3); dễ lan tỏa theo mọi hướng (4). Số tính chất của chất khí là', 'Chất khí không có hình dạng và thể tích xác định, dễ bị nén và có tính chất dễ lan tỏa theo mọi hướng (chỉ có ý (4) là tính chất của chất khí).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các hiện tượng thực tế sau:' || chr(10) || '(1) Trong quá trình làm rượu, người ta đun bỗng rượu (hỗn hợp cái rượu và nước) ở nhiệt độ khoảng 78°C sau đó dẫn hơi rượu qua ống làm lạnh thu được dung dịch rượu.' || chr(10) || '(2) Nắng nóng gay gắt khiến cho nhựa đường bị chảy ra, có thể gây biến dạng con đường.' || chr(10) || '(3) Vào mùa đông, một số vùng núi cao ở Việt Nam xuất hiện tuyết rơi.' || chr(10) || '(4) Để tạo ra các cây nến có kích thước khác nhau người ta đem đun nóng chảy sáp nến rồi đổ vào khuôn có kích thước tương ứng và để nguội.' || chr(10) || 'Số hiện tượng xảy ra sự đông đặc là', 'Hiện tượng đông đặc (chuyển từ thể lỏng sang thể rắn) gồm có: (3) Nước hóa rắn thành tuyết; (4) Sáp nến lỏng để nguội đông đặc thành cây nến rắn.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Điều khiển mọi hoạt động sống của tế bào là chức năng của :', 'Nhân tế bào chứa vật chất di truyền, có chức năng điều khiển mọi hoạt động sống của tế bào.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Bằng mắt thường ta có thể quan sát được tế bào', 'Tép bưởi thực chất là một tế bào đơn lẻ chứa nhiều dịch bào có kích thước lớn, hoàn toàn có thể quan sát trực tiếp bằng mắt thường.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Các hoạt động sống cơ bản của tế bào diễn ra ở đâu?', 'Chất tế bào là nơi chứa các bào quan và là nơi diễn ra hầu hết các hoạt động sống cơ bản của tế bào.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát tế bào bên và cho biết mũi tên đang chỉ vào thành phần nào của tế bào.', 'Mũi tên chỉ vào cấu trúc nằm ở trung tâm tế bào có màng bao bọc, đó là nhân tế bào.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vật nào sau đây được cấu tạo từ tế bào', 'Tế bào là đơn vị cơ bản cấu tạo nên cơ thể sống. Cây ngô là cơ thể sống nên được cấu tạo từ các tế bào.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây đúng?', 'Phần lớn các tế bào có kích thước hiển vi, kích thước trung bình dao động từ 0,5 đến 100 µm.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Một tế bào sinh dưỡng phân chia 5 lần số tế bào con được tạo ra là', 'Số tế bào con tạo ra sau n lần phân chia được tính bằng công thức: 2^n = 2^5 = 32 tế bào con.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tế bào có thể tăng lên về kích thước là đặc điểm của quá trình', 'Sinh trưởng của tế bào là sự gia tăng về kích thước và khối lượng của tế bào nhờ quá trình trao đổi chất.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào xảy ra đầu tiên trong quá trình phân chia của tế bào?', 'Trong quá trình phân chia tế bào, đầu tiên là sự phân chia của nhân tạo thành 2 nhân mới, sau đó mới đến phân chia tế bào chất và hình thành vách ngăn.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Dựa vào đâu mà người ta chia ra cơ thể đơn bào và cơ thể đa bào', 'Sinh vật cấu tạo từ một tế bào gọi là cơ thể đơn bào; sinh vật cấu tạo từ nhiều tế bào gọi là cơ thể đa bào.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cơ thể là', 'Cơ thể là một cá thể sinh vật hoàn chỉnh, có khả năng tự thực hiện các quá trình sống cơ bản (trao đổi chất, cảm ứng, sinh trưởng, sinh sản).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tập hợp nhiều mô cùng thực hiện chức năng nhất định, ở vị trí nhất định trong cơ thể được gọi là', 'Cấp độ tổ chức: Tế bào → Mô → Cơ quan → Hệ cơ quan → Cơ thể. Nhiều mô cùng phối hợp tạo thành cơ quan.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Có bao nhiêu phát biểu sau đây sai?' || chr(10) || '(1) Cơ thể đơn bào có tổ chức đơn giản, cơ thể chỉ là một tế bào.' || chr(10) || '(2) Vi khuẩn, nấm men,... là cơ thể đơn bào.' || chr(10) || '(3) Cơ thể đa bào có cấu tạo gồm nhiều hơn một tế bào. Mỗi loại tế bào thường thực hiện một chức năng sống riêng biệt nhưng phối hợp với nhau thực hiện các quá trình sống của cơ thể.' || chr(10) || '(4) Trùng roi, cây bưởi, cây lim, con gà, con chó,... là cơ thể đơn bào.' || chr(10) || 'Số lượng phát biểu sai là:', 'Có 1 phát biểu sai là (4), vì cây bưởi, cây lim, con gà, con chó là các cơ thể đa bào (chỉ có trùng roi là đơn bào).', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong quy trình quan sát tế bào trứng cá không có bước nào sau đây', 'Trứng cá có kích thước lớn, chỉ cần quan sát trong đĩa petri bằng mắt thường hoặc kính lúp cầm tay, không cần làm tiêu bản lên lam kính và đậy lamen như tế bào hiển vi.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong cơ thể, các hệ cơ quan hoạt động', 'Các hệ cơ quan trong cơ thể có mối quan hệ mật thiết, hoạt động phối hợp nhịp nhàng, thống nhất nhằm duy trì sự sống cho cơ thể.', 'KHTN 6 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công toàn bộ 120 câu hỏi cùng đáp án và ảnh minh họa cho Đề 2, Đề 3, Đề 4!';
END $$;


-- ==============================================================================
-- PHẦN 2. LỚP 6 - CUỐI HỌC KỲ 1 (Nguồn: insert code lớp 6 kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point DOUBLE PRECISION := 0.25; -- Đề 40 câu, thang điểm 10.0
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 6
    SELECT id INTO v_class_id FROM grades WHERE grade = 6;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 6', 6, 'Chương trình Khoa học tự nhiên THCS Lớp 6', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 6', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 6 HỌC KỲ 1
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN6_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 6', 'KHTN6_HK1', 'Môn Khoa học Tự nhiên Lớp 6 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI HỌC KÌ 1 KHTN 6 - ĐỀ SỐ 1
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN6_01',
        'Đề thi học kì 1 KHTN 6 - Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Lực là:', 'Lực là tác dụng đẩy hoặc kéo của vật này lên vật khác.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trên vỏ một hộp thịt có ghi 500g. Số liệu đó chỉ', 'Con số 500g ghi trên vỏ hộp thịt chỉ khối lượng tịnh của phần thịt chứa bên trong hộp.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một chú robot có thể cười, nói và hành động như một con người. Vậy robot là vật sống hay vật không sống? Tại sao?', 'Robot là sản phẩm nhân tạo, không có các đặc trưng cơ bản của sự sống như: trao đổi chất và chuyển hóa năng lượng với môi trường, lớn lên (sinh trưởng) và sinh sản.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đặt vật trên một mặt bàn nằm ngang, móc lực kế vào vật và kéo sao cho lực kế luôn song song với mặt bàn và vật trượt nhanh dần. Số chỉ của lực kế khi đó', 'Vật chuyển động trượt nhanh dần đều chứng tỏ lực kéo tác dụng lên vật có độ lớn lớn hơn lực ma sát trượt cản trở chuyển động (Fkéo > Fmst). Do đó số chỉ của lực kế lớn hơn độ lớn lực ma sát trượt.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây vật không bị biến dạng khi chịu tác dụng của lực?', 'Viên bi sắt bị búng chỉ bị biến đổi chuyển động (từ đứng yên chuyển sang lăn về phía trước), cấu trúc hình dạng của viên bi không bị biến dạng.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây liên quan đến lực không tiếp xúc?', 'Giọt mưa rơi xuống mặt đất là do tác dụng của trọng lực (lực hút của Trái Đất) – đây là loại lực không tiếp xúc.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hãy biểu diễn lực sau: Lực kéo vật có phương nằm ngang, chiều từ trái sang phải và có độ lớn 2000 N (1 cm ứng với 500N)', 'Độ lớn 2000 N tương ứng với độ dài mũi tên biểu diễn là 2000 : 500 = 4 cm. Mũi tên có gốc đặt tại vật, phương nằm ngang, chiều hướng từ trái sang phải gồm 4 đoạn bằng nhau tương ứng với Hình C.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một bạn học sinh nặng 17kg. Trọng lượng bạn học sinh đó là:', 'Trọng lượng của vật liên hệ với khối lượng theo hệ thức gần đúng: P = 10 × m = 10 × 17 = 170 N.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho hình vẽ sau, GHĐ và ĐCNN của thước là:', 'Vạch số lớn nhất trên thước là 20 cm (GHĐ = 20 cm). Khoảng cách giữa 2 vạch chia liên tiếp là 1 cm = 10 mm (ĐCNN = 10 mm).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Người ta đổ một lượng nước vào một bình chia độ như hình vẽ bên. Thể tích của nước trong bình là:', 'Bình chia độ có GHĐ 500 ml và ĐCNN là 20 ml. Mực nước trong bình chỉ ngang vạch 240 ml, do đó thể tích nước là 240 ml.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phép đổi đơn vị thời gian nào sau đây là đúng?', '1 ngày = 24 giờ → 30 ngày = 30 × 24 = 720 giờ.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Trước một chiếc cầu có một biển báo giao thông ghi 10T (hình vẽ), con số 10T này có ý nghĩa gì?', 'Biển báo 10T quy định tải trọng tối đa cho phép của phương tiện: Khối lượng toàn bộ (gồm cả khối lượng xe và hàng hóa) vượt quá 10 tấn không được phép qua cầu.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi treo một vật theo phương thẳng đứng vào lực kế, ta thấy số chỉ của lực kế là 200N. Khối lượng của vật đó là:', 'Khi treo cân bằng, trọng lượng của vật bằng số chỉ lực kế: P = 200 N. Khối lượng của vật là: m = P / 10 = 200 / 10 = 20 kg.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Mặt đế giày dép thường xẻ các rãnh nhỏ có tác dụng gì:', 'Các rãnh khía dưới mặt đế giày dép làm tăng độ gồ ghề của bề mặt tiếp xúc, từ đó làm tăng lực ma sát giúp chống trơn trượt khi di chuyển.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Giá trị nhiệt độ đo được theo thang nhiệt độ Kenvin là 293K. Hỏi theo thang nhiệt độ Farenhai, nhiệt độ đó có giá trị là bao nhiêu? Biết rằng mỗi độ trong thang nhiệt độ Kenvin bằng độ trong thang nhiệt độ Xenxiut và ứng với 273K.', 'Đổi từ Kelvin sang độ Celsius: t (°C) = T (K) - 273 = 293 - 273 = 20 °C.' || chr(10) || 'Đổi từ độ Celsius sang độ Fahrenheit: t (°F) = (t (°C) × 1,8) + 32 = (20 × 1,8) + 32 = 68 °F.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vật nào dưới đây là vật sống?', 'Con chó có các dấu hiệu sống như hô hấp, dinh dưỡng, lớn lên và sinh sản, do đó là vật sống. Các vật thể còn lại là vật vô sinh (vật không sống).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Quá trình nào sau đây không thể hiện tính chất hóa học của chất?', 'Nước để lâu bị biến mất là hiện tượng nước bay hơi từ thể lỏng sang thể hơi (biến đổi vật lí, không tạo chất mới). Các quá trình khác đều tạo chất mới nên thể hiện tính chất hóa học.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho các hình ảnh sau. Hình ảnh thể hiện sự sôi là:', 'Sự sôi là quá trình bay hơi đặc biệt diễn ra cả ở bề mặt thoáng lẫn từ sâu trong lòng chất lỏng (tạo thành các bọt khí nổi lên và vỡ ra ở mặt thoáng), ứng với Hình 4.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phát biểu đúng khi nói về không khí là', 'Không khí là một hỗn hợp khí gồm nhiều thành phần, trong đó chủ yếu là khí nitrogen (khoảng 78%) và khí oxygen (khoảng 21%).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vật liệu nào dưới đây dẫn điện?', 'Kim loại có các electron tự do nên dẫn điện tốt; nhựa, cao su, gốm sứ là những vật liệu cách điện.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các chất sau đây, chất nào không phải là nhiên liệu?', 'Nhiên liệu là những chất cháy được và tỏa nhiệt khi cháy (như than, dầu, củi, khí gas). Đất không cháy được nên không phải là nhiên liệu.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu dưới đây, có bao nhiêu phát biểu đúng?' || chr(10) || '(1) Xăng, dầu dễ bắt cháy nhưng xăng dễ bay hơi và dễ cháy hơn dầu.' || chr(10) || '(2) Mọi nhiên liệu đều có thể tái tạo trong thời gian ngắn.' || chr(10) || '(3) Than đá là nhiên liệu hóa thạch.' || chr(10) || '(4) Nhiên liệu sinh học được hình thành từ các hợp chất có nguồn gốc sinh học.', 'Có 3 phát biểu đúng là (1), (3) và (4). Phát biểu (2) sai vì nhiên liệu hóa thạch (than đá, dầu mỏ, khí thiên nhiên) cần hàng triệu năm mới hình thành nên không thể tái tạo trong thời gian ngắn.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho các phát biểu sau:' || chr(10) || '(1) Các loại vitamin là không cần thiết đối với cơ thể.' || chr(10) || '(2) Cà rốt là loại thực phẩm giàu vitamin A.' || chr(10) || '(3) Lương thực – thực phẩm là các chất đã qua chế biến.' || chr(10) || '(4) Lương thực như gạo, ngô, khoai, sắn, … có chứa tinh bột.' || chr(10) || '(5) Lương thực – thực phẩm không có hạn sử dụng và có thể sử dụng mãi mãi.' || chr(10) || 'Số phát biểu đúng là', 'Có 2 phát biểu đúng là (2) và (4). Các phát biểu (1), (3), (5) đều sai (vitamin rất cần thiết dù lượng nhỏ; lương thực thực phẩm có thể ở dạng tươi sống chưa chế biến; lương thực thực phẩm đều có hạn sử dụng).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Oxygen có tính chất nào sau đây?', 'Ở điều kiện thường, oxygen là chất khí không màu, không mùi, không vị, ít tan trong nước, nặng hơn không khí (d ≈ 32/29 ≈ 1,1), có vai trò duy trì sự cháy và sự sống.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các cây thép dùng trong xây dựng nhà cửa, cầu, cống được sản suất từ loại nguyên liệu nào sau đây?', 'Thép là hợp kim của sắt với carbon và một số nguyên tố khác, được sản xuất chủ yếu từ quặng sắt.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho các diễn biến sau:' || chr(10) || '(1) Hình thành vách ngăn giữa các tế bào con' || chr(10) || '(2) Phân chia chất tế bào' || chr(10) || '(3) Phân chia nhân' || chr(10) || 'Sự phân chia tế bào thực vật diễn ra theo trình tự sớm muộn như thế nào?', 'Trình tự phân chia ở tế bào thực vật: Phân chia nhân đầu tiên (3), tiếp đến là phân chia tế bào chất (2), và cuối cùng hình thành vách ngăn tế bào để tạo 2 tế bào con riêng biệt (1).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Bào quan là', 'Bào quan là các cấu trúc vi thể nằm trong tế bào chất, mỗi bào quan đảm nhiệm một hoặc một số chức năng chuyên biệt trong tế bào.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho các đối tượng sau: miếng thịt lợn, chiếc bút, con gà, chiếc lá khô, cây rau ngót, chiếc kéo, mật ong, chai nước, chiếc bàn (các cây và con vật đưa ra đều đang sống). Nhóm đối tượng gồm toàn vật sống là', 'Con gà và cây rau ngót là các cá thể sinh vật sống. Miếng thịt, lá khô, chiếc kéo, chai nước, chiếc bàn,... là vật không sống.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Điểm giống nhau của cơ thể đơn bào và cơ thể đa bào là', 'Tế bào là đơn vị cơ bản cấu tạo nên mọi cơ thể sống, dù là cơ thể đơn bào hay cơ thể đa bào.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thành phần nào không có ở cả tế bào động vật và thực vật', 'Cả tế bào động vật và tế bào thực vật đều là tế bào nhân thực (có nhân hoàn chỉnh với màng nhân bao bọc). "Vùng nhân" là đặc điểm chỉ có ở tế bào nhân sơ (như vi khuẩn).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát các cơ quan dưới đây: Hệ tiêu hoá gồm các cơ quan nào?', 'Trong các cơ quan được biểu diễn, cơ quan (3) dạ dày và cơ quan (6) ruột non thuộc hệ tiêu hóa.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Từ một tế bào ban đầu, trải qua k lần phân chia tạo 128 tế bào con, k có giá trị là', 'Số tế bào con tạo thành qua k lần phân chia là 2^k = 128 = 2^7 ⇒ k = 7.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vì sao cần phải phân loại thế giới sống?', 'Việc phân loại giúp sắp xếp sinh vật vào các bậc phân loại theo một trật tự nhất định, qua đó dễ dàng xác định tên gọi, vị trí phân loại và nghiên cứu các nhóm sinh vật.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Công cụ nào không hữu ích trong việc xác định các đặc điểm của sinh vật khi xây dựng khoá lưỡng phân?', 'Kính viễn vọng dùng để quan sát các thiên thể ở rất xa ngoài vũ trụ, không dùng để quan sát hay xác định đặc điểm hình thái của sinh vật.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dưới đây là khóa lưỡng phân phân loại 4 sinh vật: cá, thằn lằn, hổ và khỉ đột. Có mấy cặp đặc điểm được sử dụng?', 'Để phân loại 4 sinh vật thành các nhóm riêng rẽ trong sơ đồ khóa lưỡng phân cần sử dụng 3 lần phân nhánh (3 cặp đặc điểm tương phản đối lập).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho các đặc điểm sau:' || chr(10) || '(1) Có hệ thần kinh.' || chr(10) || '(2) Đa bào phức tạp.' || chr(10) || '(3) Sống tự dưỡng.' || chr(10) || '(4) Cơ thể phân hóa thành các mô và cơ quan.' || chr(10) || '(5) Có hình thức sinh sản hữu tính.' || chr(10) || '(6) Có khả năng di chuyển chủ động.' || chr(10) || 'Các đặc điểm có ở cả giới Thực vật và giới Động vật là:', 'Cả giới Thực vật và giới Động vật đều là sinh vật đa bào phức tạp (2), cơ thể phân hóa thành mô và cơ quan (4), và đều có khả năng sinh sản hữu tính (5).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tên phổ thông của sinh vật là', 'Tên phổ thông là tên gọi phổ biến, thông dụng nhất của sinh vật trong ngôn ngữ của một quốc gia, được đưa vào danh mục tra cứu chính thức.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 1)
    VALUES ('SINGLE_CHOICE', '“Giúp vi khuẩn bám vào tế bào vật chủ” là vai trò của', 'Ở vi khuẩn, lông (tiêu mao/nhung mao) có chức năng chính giúp vi khuẩn bám dính vào bề mặt hoặc tế bào vật chủ; trong khi roi có vai trò hỗ trợ di chuyển.', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vật chất di truyền của một virus là', 'Lõi của virus chỉ chứa một trong hai loại axit nucleic làm vật chất di truyền: hoặc là ADN, hoặc là ARN (không chứa đồng thời cả hai loại).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát hình dưới đây và chọn chú thích đúng:', 'Cấu tạo chung gồm 3 thành phần chính từ ngoài vào trong: 1 là màng tế bào (bao bọc bên ngoài), 2 là khối tế bào chất (ở giữa), và 3 là nhân tế bào (nằm trong cùng).', 'KHTN 6 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI HỌC KÌ 1 KHTN 6 - ĐỀ SỐ 2
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN6_02',
        'Đề thi học kì 1 KHTN 6 - Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ dùng để đo khối lượng của một vật là', 'Dụng cụ dùng để đo khối lượng của vật là cân.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Độ lớn của lực hút của Trái Đất tác dụng lên vật gọi là', 'Trọng lượng là độ lớn của lực hút của Trái Đất tác dụng lên vật.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu sau đây, phát biểu nào đúng?', 'Phát biểu đúng là: Lực kế là dụng cụ để đo lực.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hai bạn Nam và Hòa cùng đưa thùng hàng lên sàn ô tô (Nam đứng dưới đất còn Hòa đứng trên thùng xe). Nhận xét nào về lực tác dụng của Nam và Hòa lên thùng hàng sau đây là đúng?', 'Nam đứng dưới đất còn Hòa đứng trên thùng xe nên Nam đẩy và Hòa kéo thùng hàng.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào sau đây là hoạt động nghiên cứu khoa học:', 'Hoạt động "Tìm hiểu vi khuẩn bằng kính hiển vi" và hoạt động "tìm hiểu vũ trụ" là hoạt động nghiên cứu khoa học.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hành động nào sau đây không thực hiện đúng quy tắc an toàn trong phòng thực hành', 'Đổ hóa chất vào cống thoát nước là hành động không thực hiện đúng quy tắc an toàn trong phòng thực hành vì có thể gây ô nhiễm nguồn nước và nguy hiểm cho hệ thống thoát nước.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một vật đặt trên mặt bàn nằm ngang. Dùng tay búng vào vật để nó chuyển động. Vật sau đó chuyến động chậm dần vì có', 'Một vật đặt trên mặt bàn nằm ngang. Dùng tay búng vào vật để nó chuyển động. Vật sau đó chuyển động chậm dần vì có lực ma sát cản trở chuyển động giữa vật và mặt bàn.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đổi các đơn vị đo nhiệt độ sau:' || chr(10) || 'a) 37 °C = …… °F' || chr(10) || 'b) 50 °F = …… °C', '37 °C = 32 + (37 × 1,8) = 98,6 °F.' || chr(10) || '50 °F = (50 - 32) : 1,8 = 10 °C.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thời gian giữa hai nhịp tim liên tiếp của người bình thường khoảng 0,8 s. Hỏi trong 1 phút, tim của một người bình thường đập bao nhiêu nhịp?', 'Đổi: 1 phút = 60 giây. Trong 1 phút, số nhịp đập của tim người bình thường là: 60 : 0,8 = 75 (nhịp).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hãy diễn tả bằng lời phương, chiều và độ lớn của lực vẽ ở hình bên:', 'Mũi tên có phương nằm ngang, hướng từ trái sang phải. Tỉ xích 1 cm ứng với 10 N, độ dài mũi tên 2 cm ứng với độ lớn 10 × 2 = 20 N. Do đó lực của người đẩy thùng hàng có phương nằm ngang, chiều hướng từ trái sang phải, cường độ 20 N.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Người ta dùng búa để đóng một cái cọc tre xuống đất. Lực mà búa tác dụng lên cọc tre sẽ gây ra những kết quả gì?', 'Lực mà búa tác dụng lên cọc tre làm cọc tre lún sâu xuống đất (biến đổi chuyển động) và làm đầu cọc tre có thể bị dập, nứt (biến dạng).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Trong các lực ở hình bên, lực nào là lực tiếp xúc, lực nào là lực không tiếp xúc?', 'Lực tiếp xúc xuất hiện khi có sự tiếp xúc trực tiếp giữa các vật (hình b, c, d), còn lực không tiếp xúc xuất hiện khi không có sự tiếp xúc trực tiếp (hình a).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Giải thích hiện tượng sau và cho biết trong hiện tượng này, ma sát có lợi hay có hại: Ô tô đi vào bùn dễ bị sa lầy.', 'Ô tô đi trên bùn dễ bị sa lầy vì lực ma sát giữa bánh xe và mặt đường dính bùn nhỏ, làm cho bánh xe quay tít mà không bám vào mặt đường được. Trường hợp này lực ma sát có lợi vì nhờ có nó mà xe mới di chuyển được và không bị sa lầy.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Từ hình vẽ, hãy xác định chiều dài của khối hộp?', 'Một đầu của khối hộp ở vạch 2 cm, đầu còn lại ở vạch 5 cm. Chiều dài của khối hộp là: 5 - 2 = 3 cm.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Người ta sử các dụng thiết bị để đo khối lượng của 1cm³ nước. Hãy sắp xếp các bước theo đúng thứ tự thực hiện, bắt đầu là D.' || chr(10) || 'A. Đổ 50cm³ nước vào ống đong.' || chr(10) || 'B. Chia khối lượng của nước cho 50.' || chr(10) || 'C. Lấy ống đong rỗng ra khỏi cân.' || chr(10) || 'D. Đặt ống đong rỗng lên cân.' || chr(10) || 'E. Lấy khối lượng của ống đong chứa nước trừ đi khối lượng của ống đong rỗng.' || chr(10) || 'F. Ghi lại khối lượng của ống đong rỗng.' || chr(10) || 'G. Ghi lại khối lượng của ống đong và nước.' || chr(10) || 'H. Đặt ống đong chứa nước lên cân.', 'Các bước đúng: Đặt ống đong rỗng lên cân (D) → Ghi lại khối lượng ống đong rỗng (F) → Lấy ống đong rỗng ra khỏi cân (C) → Đổ 50cm³ nước vào ống đong (A) → Đặt ống đong chứa nước lên cân (H) → Ghi lại khối lượng của ống đong và nước (G) → Lấy khối lượng ống đong chứa nước trừ khối lượng ống đong rỗng (E) → Chia khối lượng của nước cho 50 (B).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây đều là chất?', 'Nhôm, muối ăn, đường mía đều là chất. Các phương án còn lại có chứa vật thể (con dao, đôi đũa, cái thìa).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vật liệu nào sau đây không thể tái chế?', 'Xi măng sau khi đã đông kết trong bê tông, vữa xây dựng thì không thể tái chế lại thành xi măng ban đầu.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chỉ ra đâu là tính chất hóa học của chất', 'Cơm để lâu bị mốc là quá trình chất bị biến đổi thành chất mới, thể hiện tính chất hóa học. Các hiện tượng còn lại là hiện tượng vật lí (hòa tan, nóng chảy).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Để bảo vệ không khí trong lành chúng ta nên', 'Trồng cây xanh giúp quang hợp hấp thụ CO₂ và thải O₂, lọc bụi bẩn giúp bầu không khí luôn trong lành.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Điền từ thích hợp vào chỗ trống trong phát biểu sau: “Nguyên liệu là vật liệu…. chưa qua xử lí và cần được chuyển hóa để tạo ra sản phẩm”', 'Nguyên liệu là vật liệu thô chưa qua xử lí và cần được chuyển hóa để tạo ra sản phẩm.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nước đựng trong cốc bay hơi càng nhanh khi', 'Tốc độ bay hơi của chất lỏng càng nhanh khi nhiệt độ càng cao, diện tích mặt thoáng càng lớn và gió càng mạnh.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Để duy trì một sức khỏe tốt với chế độ ăn hợp lí ta nên làm gì?', 'Chế độ ăn uống hợp lí cần đảm bảo ăn đủ và đa dạng các nhóm chất dinh dưỡng cần thiết cho cơ thể.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cách sử dụng nhiên liệu hiệu quả, tiết kiệm là', 'Đập than vừa nhỏ, chẻ nhỏ củi làm tăng diện tích tiếp xúc giữa nhiên liệu với không khí, giúp nhiên liệu cháy hoàn toàn và tỏa nhiệt hiệu quả.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nhóm thức ăn nào dưới đây là dạng lương thực?', 'Lương thực là các loại thức ăn chứa hàm lượng lớn tinh bột cung cấp năng lượng chính cho con người: gạo, ngô, khoai, sắn, lúa mì,...', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi khai thác quặng sắt, ý nào sau đây là không đúng?', 'Không nên khai thác thủ công vì năng suất thấp, lãng phí tài nguyên và gây ô nhiễm môi trường nghiêm trọng.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát tế bào bên và cho biết mũi tên đang chỉ vào thành phần nào của tế bào.', 'Đây là tế bào động vật, thành phần ở trung tâm được mũi tên chỉ vào là nhân tế bào.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tế bào vi khuẩn có kích thước', 'Tế bào vi khuẩn có kích thước hiển vi rất nhỏ, thông thường chỉ vào khoảng 0,5 - 10 μm.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cơ thể lớn lên nhờ', 'Cơ thể sinh vật lớn lên là nhờ sự tăng về kích thước (sự lớn lên) và số lượng (sự phân chia) của các tế bào cấu tạo nên nó.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Có bao nhiêu phát biểu sau đây sai?' || chr(10) || '(1) Cơ thể đơn bào có tổ chức đơn giản, cơ thể chỉ là một tế bào.' || chr(10) || '(2) Vi khuẩn, nấm men, ... là cơ thể đơn bào.' || chr(10) || '(3) Cơ thể đa bào có cấu tạo gồm nhiều hơn một tế bào. Mỗi loại tế bào thường thực hiện một chức năng sống riêng biệt nhưng phối hợp với nhau thực hiện các quá trình sống của cơ thể.' || chr(10) || '(4) Trùng roi, cây bưởi, cây lim, con gà, con chó, ... là cơ thể đơn bào.', 'Chỉ có 1 phát biểu sai là (4), vì cây bưởi, cây lim, con gà, con chó là các cơ thể đa bào.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các nhận xét sau:' || chr(10) || '(1) Tế bào thực vật và tế bào động vật đều có các bào quan.' || chr(10) || '(2) Lục lạp là bào quan có ở tế bào động vật.' || chr(10) || '(3) Tế bào động vật và tế bào thực vật đều có màng tế bào, tế bào chất và nhân.' || chr(10) || '(4) Thành tế bào chỉ có ở tế bào động vật.' || chr(10) || '(5) Lục lạp mang sắc tố quang hợp, có khả năng hấp thụ ánh sáng để tổng hợp nên chất hữu cơ.' || chr(10) || 'Các nhận xét đúng là:', 'Các nhận xét đúng là (1), (3), (5). Nhận xét (2) sai vì lục lạp chỉ có ở tế bào thực vật; nhận xét (4) sai vì thành tế bào không có ở tế bào động vật mà có ở thực vật, nấm, vi khuẩn.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đâu là một cơ quan', 'Dạ dày là một cơ quan đơn lẻ. Hệ tiêu hóa và hệ bài tiết là cấp độ hệ cơ quan; tim và mạch máu là tập hợp các cơ quan thuộc hệ tuần hoàn.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trình tự các bước làm tiêu bản quan sát sinh vật đơn bào là' || chr(10) || 'a) Dùng ống nhỏ giọt hút lấy một giọt nước ao (hồ) lên lam kính rồi đậy bằng lamen.' || chr(10) || 'b) Dùng thìa khuấy đều nước ao (hồ) trong cốc.' || chr(10) || 'c) Quan sát tiêu bản bằng kính hiển vi.' || chr(10) || 'd) Dùng giấy thấm hút phần nước tràn ra ngoài lamen.', 'Trình tự thực hiện đúng: Khuấy đều nước ao (b) → Nhỏ một giọt lên lam kính và đậy lamen (a) → Hút phần nước tràn bằng giấy thấm (d) → Quan sát dưới kính hiển vi (c).', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Máu trong hệ mạch của hệ tuần hoàn là cấp độ tổ chức nào dưới đây?', 'Máu gồm các tế bào máu và huyết tương, thuộc cấp độ mô liên kết lỏng trong cơ thể.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho một số sinh vật sau: vi khuẩn E. coli, trùng roi, nấm men, xạ khuẩn, rêu, lúa nước, mực ống, san hô. Các sinh vật được cấu tạo từ tế bào nhân sơ là', 'Vi khuẩn E. coli và xạ khuẩn là các sinh vật thuộc giới Khởi sinh, có cấu tạo từ tế bào nhân sơ. Các sinh vật còn lại đều là sinh vật nhân thực.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Ngoài sữa chua, chúng ta còn sử dụng các sản phẩm có ứng dụng hoạt động của vi khuẩn nào', 'Quá trình ủ chượp sản xuất nước mắm truyền thống ứng dụng hoạt động của vi khuẩn phân giải protein từ cá thành các axit amin.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sinh vật thuộc giới nào sau đây có đặc điểm cấu tạo nhân tế bào khác hẳn với các giới còn lại?', 'Giới Khởi sinh gồm các sinh vật nhân sơ (chưa có nhân hoàn chỉnh), trong khi ba giới Động vật, Thực vật và Nấm đều là sinh vật nhân thực.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cấp bậc trên loài, dưới họ ở động vật được gọi là', 'Trong hệ thống phân loại sinh vật: Loài → Chi/Giống → Họ → Bộ → Lớp → Ngành → Giới. Đối với động vật thường dùng thuật ngữ "Giống", thực vật dùng "Chi".', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Người ta đã “lợi dụng” hoạt động của vi khuẩn lactic để tạo ra món ăn', 'Vi khuẩn lactic được ứng dụng trong quá trình lên men sữa thành sữa chua.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Các biểu hiện của người mắc COVID-19 là', 'Người mắc COVID-19 thường có các triệu chứng đường hô hấp điển hình như sốt, ho khan, khó thở mệt mỏi.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên sinh vật được chia thành', 'Giới Nguyên sinh (nguyên sinh vật) gồm 3 nhóm chính: động vật nguyên sinh, thực vật nguyên sinh (tảo) và nấm nhầy.', 'KHTN 6 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN III: ĐỀ THI HỌC KÌ 1 KHTN 6 - ĐỀ SỐ 3
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN6_03',
        'Đề thi học kì 1 KHTN 6 - Kết nối tri thức - Đề số 3',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 3.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Có 1 khúc vải, người ta cần cắt nó ra làm 100 khúc, thời gian để cắt 1 khúc vải là 5 giây. Hỏi nếu cắt liên tục không ngừng nghỉ thì trong bao lâu sẽ cắt xong?', 'Để cắt được 100 khúc vải, chỉ cần cắt 99 lần (khúc cuối cùng không cần cắt). Thời gian cắt xong khúc vải là: 99 × 5 = 495 (giây).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây nói về lực ma sát là đúng?', 'Lực ma sát trượt cản trở chuyển động trượt của vật này trên bề mặt vật kia. Lực ma sát luôn ngược hướng với hướng chuyển động; khi vật chuyển động nhanh dần thì lực ma sát nhỏ hơn lực đẩy, còn khi chuyển động chậm dần thì lực ma sát lớn hơn lực đẩy.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Một túi đường có khối lượng 2 kg thì có trọng lượng gần bằng', 'Trọng lượng của túi đường là: P = 10 × m = 10 × 2 = 20 (N).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Treo một quả cân 100 g vào một lực kế thì kim của lực kế chỉ vạch thứ 2. Khi kim của lực kế chỉ vạch thứ 5 thì tổng khối lượng của các quả cân đã treo vào lực kế là bao nhiêu?', 'Độ dãn của lò xo treo thẳng đứng tỉ lệ với khối lượng vật treo. Treo 100 g thì kim chỉ vạch thứ 2 ⇒ Mỗi vạch tương ứng với khối lượng: 100 : 2 = 50 (g). Khi chỉ vạch thứ 5, tổng khối lượng quả cân treo là: 50 × 5 = 250 (g).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Điều nào sau đây là tác hại của khoa học tự nhiên đối với con người và môi trường sống?', 'Rác thải từ pin Mặt Trời chứa nhiều hóa chất độc hại là một trong những tác động tiêu cực/tác hại của ứng dụng khoa học công nghệ đối với môi trường.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Lực có thể gây ra tác dụng nào dưới đây?', 'Lực tác dụng lên một vật có thể làm thay đổi tốc độ (nhanh lên, chậm lại hoặc dừng lại), đổi hướng chuyển động (vật đứng yên chuyển sang chuyển động) hoặc làm vật bị biến dạng.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đơn vị đo trọng lượng là:', 'Trọng lượng là độ lớn của trọng lực nên có đơn vị đo là niutơn (kí hiệu: N).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Sắp xếp các lực trong các trường hợp sau theo độ lớn tăng dần', 'Ước lượng độ lớn của lực trong các trường hợp: Ngón tay bấm điện thoại cần lực nhỏ nhất; tiếp đến là lực tay cầm quả táo; lực học sinh đeo ba lô; và lớn nhất là lực đẩy xe hàng (thứ tự tăng dần: b – d – c – a).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi làm thí nghiệm, chúng ta tiếp xúc với: nguồn điện; nguồn nhiệt; hóa chất; chất dễ cháy nổ; dụng cụ sắc nhọn; động vật; … Vì thế chúng ta cần', 'Khi làm việc trong phòng thực hành, cần nắm vững các mối nguy hiểm tiềm ẩn và tuân thủ nghiêm ngặt các quy định an toàn để phòng tránh rủi ro, tai nạn.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Để đo chu vi của miệng cốc hình tròn, phải sử dụng loại thước nào?', 'Do miệng cốc có dạng đường cong tròn nên ta cần sử dụng thước dây (có tính mềm dẻo, dễ uốn quanh miệng cốc) để đo chu vi chính xác nhất.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hai lực cân bằng là hai lực:', 'Hai lực cân bằng là hai lực cùng tác dụng lên một vật, có cùng độ lớn (cường độ), phương cùng nằm trên một đường thẳng và có chiều ngược nhau.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong các trường hợp sau, trường hợp nào chịu lực cản của nước?', 'Bạn Lan đang tập bơi chuyển động trực tiếp trong môi trường nước nên cơ thể chịu lực cản của nước. Các trường hợp còn lại chuyển động trong không khí nên chịu lực cản của không khí.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nhiệt độ cao nhất ghi trên nhiệt kế y tế là', 'Nhiệt kế y tế thủy ngân thông thường dùng để đo thân nhiệt con người có thang đo từ 35 °C đến 42 °C, do đó nhiệt độ cao nhất ghi trên nhiệt kế là 42 °C.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khối lượng của một vật cho biết điều gì?', 'Khối lượng của một vật là số đo chỉ lượng chất chứa bên trong vật đó.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Mẫu vật nào sau đây không cần quan sát bằng kính hiển vi?', 'Gân lá cây có kích thước tương đối lớn, có thể quan sát trực tiếp bằng mắt thường hoặc sử dụng kính lúp cầm tay mà không cần đến kính hiển vi quang học.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Tế bào có kích thước nhỏ có ý nghĩa', 'Kích thước nhỏ giúp tế bào có tỉ lệ S/V lớn, nhờ đó sự trao đổi chất qua màng (hấp thụ dinh dưỡng và đào thải chất cặn bã) diễn ra nhanh chóng, giúp tế bào sinh trưởng và phân chia hiệu quả.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình ảnh dưới đây mô tả kích thước một số tế bào ở người. Trình tự sắp xếp tăng dần về kích thước của các tế bào là:', 'Đổi các kích thước về cùng đơn vị micromet: Tế bào hồng cầu (khoảng 7 μm) < Tế bào niêm mạc miệng (khoảng 50 μm) < Tế bào trứng (khoảng 130 μm = 0,13 mm) < Tế bào cơ (kích thước tính theo chiều dài lên tới hàng nghìn μm / milimet).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Sự lớn lên của tế bào chủ yếu là do', 'Quá trình trao đổi chất làm tăng nhanh khối lượng và kích thước của tế bào chất, dẫn đến sự lớn lên tổng thể của tế bào.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Có bao nhiêu phát biểu sau đây đúng?' || chr(10) || '(1) Hầu hết các sinh vật có kích thước khác nhau là do cơ thể chúng có số lượng tế bào giống nhau.' || chr(10) || '(2) Hầu hết các sinh vật có kích thước khác nhau là do cơ thể chúng có số lượng tế bào khác nhau.' || chr(10) || '(3) Tuỳ thuộc vào số lượng tế bào cấu tạo nên cơ thể, tất cả sinh vật trên Trái Đất được chia làm hai nhóm lớn là cơ thể đơn bào và cơ thể đa bào.' || chr(10) || '(4) Cơ thể đơn bào có tổ chức phức tạp, được cấu tạo từ nhiều tế bào.', 'Có 2 phát biểu đúng là (2) và (3). Phát biểu (1) sai vì kích thước sinh vật khác nhau chủ yếu do số lượng tế bào; phát biểu (4) sai vì cơ thể đơn bào chỉ cấu tạo từ một tế bào duy nhất.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Thân cây cà rốt có màu cam là phát biểu', 'Củ cà rốt màu cam thực chất là phần rễ củ (rễ biến dạng để tích lũy chất dinh dưỡng), không phải là thân cây.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Đây là dụng cụ nào', 'Hình ảnh mô tả kính lúp cầm tay dùng để phóng to hình ảnh vật thể ở mức độ vừa phải.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong thí nghiệm quan sát sinh vật đơn bào, ta không cần sử dụng dụng cụ nào sau đây', 'Sinh vật đơn bào có kích thước hiển vi rất bé nên độ phóng đại của kính lúp không đủ để quan sát, bắt buộc phải dùng kính hiển vi cùng lam kính, lamen và giấy thấm hút.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cơ quan là gì?', 'Cơ quan là một tập hợp của nhiều loại mô cùng phối hợp để thực hiện những chức năng sống nhất định, nằm ở một vị trí xác định trong cơ thể.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nhân thực, đa bào, dị dưỡng, có khả năng di chuyển là các đặc điểm của giới', 'Giới Động vật bao gồm các sinh vật nhân thực, cấu tạo đa bào phức tạp, dinh dưỡng theo kiểu dị dưỡng và phần lớn có khả năng di chuyển chủ động.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Vi khuẩn có ở đâu?' || chr(10) || '- Trong không khí.' || chr(10) || '- Trong nước.' || chr(10) || '- Trong đất.' || chr(10) || '- Trong cơ thể sinh vật.' || chr(10) || '- Ở những nơi cực nóng hoặc cực lạnh.', 'Vi khuẩn phân bố vô cùng rộng rãi ở khắp mọi nơi trên Trái Đất: trong đất, trong nước, trong không khí, trong cơ thể sinh vật khác và thậm chí ở cả những môi trường cực đoan (nước sôi, băng tuyết). Cả 5 môi trường đều có vi khuẩn sinh sống.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Những giới sinh vật thuộc nhóm sinh vật nhân thực là', 'Theo hệ thống phân loại 5 giới của Whittaker, 4 giới thuộc nhóm sinh vật nhân thực gồm: Giới Nguyên sinh, Giới Nấm, Giới Thực vật và Giới Động vật (chỉ có giới Khởi sinh là nhân sơ).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Loài Sao la có tên khoa học là Pseudoryx nghetinhensis, hãy cho biết tên giống của loài này là', 'Trong tên khoa học của sinh vật theo nguyên tắc danh pháp kép: từ đầu tiên viết hoa là tên giống (chi) - Pseudoryx; từ thứ hai viết thường là tên loài - nghetinhensis.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trình tự tăng dần về kích thước của các đối tượng là', 'Kích thước từ nhỏ đến lớn: Virus (tính bằng nanomet, hàng chục đến vài trăm nm) → Tế bào vi khuẩn (vài micromet) → Tế bào thực vật (vài chục đến hàng trăm micromet).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Bệnh do virus có thể lây truyền qua', 'Các bệnh do virus có phương thức lây truyền đa dạng: lây qua đường máu, từ mẹ sang con, giọt bắn đường hô hấp, tiếp xúc bề mặt trực tiếp hoặc qua vết cắn của động vật truyền bệnh (vectơ truyền bệnh).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Động vật nguyên sinh có khả năng sống tự dưỡng và dị dưỡng là:', 'Trùng roi xanh có chứa các hạt diệp lục giúp quang hợp tự dưỡng khi có ánh sáng mặt trời; khi ở trong bóng tối lâu ngày, chúng chuyển sang dinh dưỡng dị dưỡng.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Quá trình nào sau đây thể hiện tính chất hoá học?', 'Đun nóng đường xuất hiện chất màu đen (than/carbon) là hiện tượng hóa học vì có sự phân hủy chất cũ và hình thành chất mới. Các quá trình khác chỉ là biến đổi trạng thái vật lí.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đâu là vật thể tự nhiên trong các vật thể sau?', 'Dãy núi là vật thể có sẵn trong tự nhiên, hình thành do các quá trình địa chất; các vật thể còn lại là vật thể nhân tạo do con người tạo ra.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Với cùng một chất, nhiệt độ nóng chảy cũng chính là', 'Đối với một chất nguyên chất, nhiệt độ nóng chảy (chuyển từ rắn sang lỏng) bằng nhiệt độ đông đặc (chuyển từ lỏng sang rắn).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Thành phần nào của không khí là nguyên nhân chủ yếu gây ra hiệu ứng nhà kính?', 'Khí carbon dioxide (CO₂) có khả năng hấp thụ bức xạ nhiệt hồng ngoại từ mặt đất phát ra, ngăn không cho nhiệt lượng thoát vào không gian, là nguyên nhân chính gây hiệu ứng nhà kính.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong các vật liệu sau, vật liệu nào dẫn điện tốt?', 'Kim loại dẫn điện tốt do có mật độ electron tự do cao, trong khi thủy tinh, gốm và cao su là các vật liệu cách điện.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Người ta khai thác than đá để cung cấp cho các nhà máy nhiệt điện sản xuất điện. Lúc này, than đá được gọi là', 'Than đá được đốt cháy để giải phóng nhiệt năng phục vụ chạy tuabin phát điện, do đó đóng vai trò là nhiên liệu (chất đốt).', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Dãy nào dưới đây gồm các nguyên liệu có sẵn trong tự nhiên?', 'Đá vôi, tre, cát, quặng sắt đều là các nguồn nguyên liệu thô có sẵn trực tiếp trong tự nhiên chưa qua tinh chế công nghiệp. Nhựa hay dầu dừa đều đã qua chế biến nhân tạo.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cho các nhận xét dưới đây:' || chr(10) || '(1) Vitamin D có vai trò rất lớn trong quá trình phát triển của xương, được hấp thụ tốt nhờ ánh sáng mặt trời.' || chr(10) || '(2) Cà chua có tác dụng chống lão hóa, đu đủ có tác dụng hạn chế táo bón.' || chr(10) || '(3) Chỉ cần ăn đầy đủ 3 nhóm chất dinh dưỡng lớn như chất béo, chất đạm, tinh bột là đã đủ cho sự phát triển toàn diện của cơ thể.' || chr(10) || '(4) Cần có chế độ ăn hợp lí, phối hợp nhiều loại thức ăn, chế độ ăn phù hợp lứa tuổi.' || chr(10) || 'Số nhận xét đúng là:', 'Có 3 nhận xét đúng là (1), (2) và (4). Nhận xét (3) sai vì ngoài chất béo, chất đạm, tinh bột, cơ thể cần bổ sung đầy đủ vitamin, khoáng chất và nước để phát triển cân đối, khỏe mạnh.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Vì sao các nhà leo núi đôi khi phải cần trang bị các bình oxygen?', 'Khí oxygen có khối lượng mol lớn hơn khối lượng mol trung bình của không khí (MO₂ = 32 > 29), đồng thời áp suất khí quyển càng lên cao càng giảm làm mật độ phân tử khí loãng đi, khiến lượng oxygen giảm mạnh. Do đó các nhà leo núi cần mang theo bình dưỡng khí.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Cho các phát biểu sau:' || chr(10) || '(1) Hiện tượng sương mù vào buổi sáng là quá trình ngưng tụ của hơi nước.' || chr(10) || '(2) Nước lỏng để trong tủ lạnh bị đóng đá là quá trình nóng chảy.' || chr(10) || '(3) Sự bay hơi xảy ra ở nhiệt độ xác định, nhiệt độ đó gọi là nhiệt độ bay hơi.' || chr(10) || '(4) Sự bay hơi diễn ra ở trên bề mặt và trong lòng chất lỏng gọi là sự sôi.' || chr(10) || 'Số phát biểu đúng là:', 'Có 2 phát biểu đúng là (1) và (4). Phát biểu (2) sai vì nước lỏng đóng thành đá là quá trình đông đặc; phát biểu (3) sai vì sự bay hơi có thể diễn ra ở mọi nhiệt độ trên bề mặt chất lỏng.', 'KHTN 6 - HK1 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN IV: ĐỀ THI HỌC KÌ 1 KHTN 6 - ĐỀ SỐ 4
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN6_04',
        'Đề thi học kì 1 KHTN 6 - Kết nối tri thức - Đề số 4',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 40 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 4.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hãy giải thích tại sao bầu khí quyển của Trái Đất không thoát vào không gian?', 'Do tác dụng của lực hấp dẫn giữa Trái Đất và bầu khí quyển, nên bầu khí quyển của Trái Đất không thoát vào không gian.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Con số 250g được ghi trên hộp mứt Tết chỉ:', 'Trên nhãn hộp mứt ghi 250g là khối lượng của mứt bên trong hộp.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây, ma sát là có hại?', 'Giày đi mãi đế bị mòn gây hỏng giày, đây là trường hợp ma sát có hại. Các trường hợp còn lại lực ma sát đều đóng vai trò có lợi.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Lực nào trong các lực dưới đây là lực kéo?', 'Lực mà con trâu tác dụng vào cái cày khi đang kéo lê trên đồng ruộng là lực kéo. Lực ném tạ là lực đẩy, lực chim đậu làm cành cây cong là lực uốn, lực nâng bóng bay là lực đẩy Archimedes.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây là sai?', 'Mặt Trăng có khối lượng nên vẫn có lực hấp dẫn hút các vật (bằng khoảng 1/6 trọng lực trên Trái Đất), do đó phát biểu "Không có lực hấp dẫn trên Mặt Trăng" là sai.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Treo thẳng đứng một lò xo, đầu dưới treo quả nặng 50 g thì độ biến dạng của lò xo là 0,1 cm. Nếu treo thêm một quả nặng khác thì độ biến dạng của lò xo là 0,5 cm. Hãy xác định khối lượng của vật nặng treo thêm vào lò xo.', 'Độ dãn của lò xo treo thẳng đứng tỉ lệ thuận với khối lượng vật treo.' || chr(10) || 'Độ biến dạng tăng lên 0,5 cm ứng với khối lượng tổng cộng là: 50 x (0,5 : 0,1) = 250 g.' || chr(10) || 'Khối lượng quả nặng treo thêm vào là: 250 - 50 = 200 g.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Nhiệt kế nào sau đây có thể dùng để đo nhiệt độ của nước đang sôi?', 'Nước sôi ở 100°C. Nhiệt kế thủy ngân có thang đo tới trên 100°C nên dùng được để đo nhiệt độ của nước sôi. (Nhiệt kế rượu sôi ở khoảng 78°C và nhiệt kế y tế chỉ đo tối đa 42°C nên không dùng được).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hãy diễn tả bằng lời phương, chiều và độ lớn của lực vẽ ở hình dưới đây:', 'Lực hút có phương nghiêng với phương nằm ngang một góc 45°, chiều hướng từ trên xuống. Tỉ xích 1 cm ứng với 2 N, mũi tên dài 1 cm tương ứng cường độ 2 N.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình nào dưới đây biểu diễn hai lực cân bằng:', 'Hai lực cân bằng là hai lực cùng đặt lên một vật, có cùng độ lớn, cùng phương nhưng ngược chiều nhau, tương ứng với Hình a.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào dưới đây không được làm trong phòng thực hành?', 'Tự ý làm thí nghiệm khi không có giáo viên/người phụ trách hướng dẫn là hành động vi phạm nội quy an toàn phòng thực hành, có nguy cơ gây cháy nổ, ngộ độc hoặc chấn thương.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Điền tên các bộ phận của kính lúp cầm tay tương ứng với các vị trí (1), (2), (3)', 'Cấu tạo của kính lúp cầm tay gồm các bộ phận: (1) – khung kính; (2) – mặt kính (thấu kính hội tụ); (3) – tay cầm.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu sau đây, phát biểu nào là đúng?', 'Mật độ của nước lớn hơn rất nhiều so với không khí nên lực cản của môi trường nước tác dụng lên vật chuyển động lớn hơn lực cản của không khí. (Chuyển động càng nhanh thì lực cản càng lớn).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Thời gian giữa hai nhịp tim liên tiếp của người bình thường khoảng 0,8 s. Hỏi trong 1 phút, tim của một người bình thường đập bao nhiêu nhịp?', 'Đổi: 1 phút = 60 giây. Trong 1 phút, số nhịp đập của tim người bình thường là: 60 : 0,8 = 75 nhịp.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Dùng bình chia độ có ĐCNN là 1 cm³ đang chứa một lượng nước có thể tích 55 cm³ thả quả cầu nhôm vào bình thì mực nước trong bình dâng lên đến vạch 75 cm³. Vậy thể tích quả cầu là:', 'Thể tích quả cầu nhôm bằng thể tích chất lỏng dâng lên: V = 75 - 55 = 20 cm³.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Điều nào dưới đây là lợi ích của ứng dụng khoa học tự nhiên đối với con người?', 'Hệ thống tưới tiêu tự động trong nông nghiệp giúp tiết kiệm nước, giảm thiểu sức lao động và nâng cao năng suất cây trồng.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vật thể nào sau đây vừa là vật thể tự nhiên, vừa là vật sống?', 'Ngựa vằn là sinh vật có sẵn trong tự nhiên và có các dấu hiệu đặc trưng của sự sống (trao đổi chất, sinh trưởng, sinh sản), do đó vừa là vật thể tự nhiên vừa là vật sống.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các tính chất sau: hình dạng xác định (1); khó bị nén (2); thể tích xác định (3); dễ lan tỏa theo mọi hướng (4). Số tính chất của chất lỏng là', 'Chất lỏng có thể tích xác định (3), khó bị nén (2), không có hình dạng riêng mà phụ thuộc vào vật chứa. Do đó có 2 tính chất đúng là (2) và (3).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các hiện tượng thực tế sau:' || chr(10) || '(1) Trong quá trình làm rượu, người ta đun bỗng rượu (hỗn hợp cái rượu và nước) ở nhiệt độ khoảng 78°C sau đó dẫn hơi rượu qua ống làm lạnh thu được dung dịch rượu.' || chr(10) || '(2) Nắng nóng gay gắt khiến cho nhựa đường bị chảy ra, có thể gây biến dạng con đường.' || chr(10) || '(3) Vào mùa đông, một số vùng núi cao ở Việt Nam xuất hiện tuyết rơi.' || chr(10) || '(4) Để tạo ra các cây nến có kích thước khác nhau người ta đem đun nóng chảy sáp nến rồi đổ vào khuôn có kích thước tương ứng và để nguội.' || chr(10) || 'Số hiện tượng xảy ra sự đông đặc là', 'Sự đông đặc (từ lỏng sang rắn) xảy ra ở hiện tượng (3) hơi nước/nước lỏng đóng băng thành tuyết và (4) sáp nến lỏng để nguội đóng rắn lại trong khuôn.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Calcium hydroxide có những tính chất sau: là chất rắn (1), màu trắng (2), ít tan trong nước (3), khi tan trong nước tạo dung dịch làm làm giấy quỳ tím chuyển sang màu xanh (4), dung dịch này có thể tạo được kết tủa màu trắng khi gặp khí carbon dioxide (5). Số tính chất vật lí của calcium hydroxide là', 'Có 3 tính chất vật lí gồm: thể rắn (1), màu trắng (2), ít tan trong nước (3). Các tính chất (4) và (5) là tính chất hóa học vì có phản ứng biến đổi chất.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tính chất nào sau đây không phải của oxygen?', 'Khí oxygen ít tan trong nước (ở 20°C và 1 atm, 1 lít nước chỉ hòa tan được khoảng 31 ml oxygen), do đó tính chất "tan nhiều trong nước" là sai.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các quá trình sau:' || chr(10) || '(a) đốt củi, than.' || chr(10) || '(b) quang hợp của cây xanh.' || chr(10) || '(c) hô hấp của động vật, thực vật.' || chr(10) || '(d) hòa tan muối ăn.' || chr(10) || 'Các quá trình cần tới oxygen là', 'Khí oxygen là chất cần thiết để duy trì sự cháy (đốt củi, than) và sự hô hấp của sinh vật. Quá trình quang hợp hấp thụ CO₂ và giải phóng O₂.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Chất nào chiếm tỉ lệ về thể tích lớn nhất trong không khí?', 'Khí nitrogen chiếm khoảng 78% thể tích không khí (oxygen chiếm khoảng 21%, còn lại 1% là các khí khác).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát các hình ảnh sau. Em hãy nối các vật thể ở cột A tương ứng với vật liệu ở cột B.', 'Ghép cặp phù hợp giữa vật thể và vật liệu cấu tạo: 1 - b; 2 - d; 3 - a; 4 - e.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Ở nhiều vùng nông thôn, người ta xây dựng hầm biogas để thu gom chất thải động vật. Theo em, việc xây hầm ủ chất thải gia súc để lấy biogas đem lại những lợi ích gì?', 'Việc làm hầm biogas vừa giúp giải quyết chất thải chuồng trại, diệt trừ mầm bệnh, bảo vệ môi trường, vừa tạo ra nguồn năng lượng sạch để đun nấu hoặc phát điện.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho các hình ảnh sau: Số lương thực trong các hình ảnh trên là', 'Lương thực là các loại thức ăn chứa hàm lượng tinh bột cao, gồm 4 loại trong hình là: ngô, sắn, khoai lang và gạo.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tế bào thần kinh có hình dạng', 'Tế bào thần kinh (nơron) ở người có hình sao với nhiều sợi nhánh và một sợi trục dài phân nhánh.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Kiểm soát sự di chuyển của các chất đi ra và vào trong tế bào là vai trò của', 'Màng tế bào có tính thấm chọn lọc, kiểm soát sự trao đổi chất (các chất đi vào và đi ra khỏi tế bào).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tế bào nào sau đây không có nhân', 'Tế bào hồng cầu người khi trưởng thành bị tiêu biến nhân để tăng khả năng vận chuyển khí oxygen và carbon dioxide.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vật sống nào sau đây không có cấu tạo cơ thể là đa bào?', 'Nấm men là sinh vật đơn bào (cơ thể chỉ gồm một tế bào duy nhất). Các cây hoa là cơ thể đa bào.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Quan sát hình dưới đây và cho biết cơ quan nào không thuộc hệ chồi', 'Cây xanh gồm hệ chồi (lá, thân, cành, hoa, quả nằm trên mặt đất) và hệ rễ (bộ rễ nằm dưới lòng đất). Cơ quan D là rễ nên không thuộc hệ chồi.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 31 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Một trong các đặc trưng của cơ thể sống là lấy thức ăn từ bên ngoài, chức năng này được thực hiện bởi hệ cơ quan nào sau đây', 'Hệ tiêu hóa có chức năng tiếp nhận thức ăn, tiêu hóa thức ăn thành các chất dinh dưỡng để cơ thể hấp thu và thải chất bã ra ngoài.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 32 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Thành phần quan sát được ở tế bào hành tây là', 'Dưới kính hiển vi quang học khi làm tiêu bản biểu bì vảy hành tây, ta có thể dễ dàng quan sát thấy thành tế bào, tế bào chất và nhân tế bào.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 33 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Nhận định nào dưới đây đúng khi nói về sinh vật đa bào?', 'Thực vật và động vật là các sinh vật đa bào gồm hàng triệu đến hàng tỉ tế bào biệt hóa thực hiện các chức năng khác nhau.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 34 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Một khoá lưỡng phân có mấy lựa chọn ở mỗi nhánh?', 'Nguyên tắc của khóa lưỡng phân là tại mỗi bước (mỗi nhánh) luôn đưa ra 2 lựa chọn dựa trên một cặp đặc điểm đối lập tương phản.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 35 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Khi xây dựng khóa lưỡng phân phân loại giới Thực vật, đặc điểm C là', 'Trong sơ đồ phân nhánh khóa lưỡng phân, đối lập với nhánh "Có hạt" là nhánh đặc điểm "Không có hạt".', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 36 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Cho các ý sau:' || chr(10) || '(1) Tế bào nhân thực' || chr(10) || '(2) Thành tế bào bằng xenluloz' || chr(10) || '(3) Sống tự dưỡng' || chr(10) || '(4) Cơ thể đơn bào hoặc đa bào dạng sợi' || chr(10) || '(5) Không có lục lạp, không di động được' || chr(10) || 'Trong các ý trên, có mấy ý không phải là đặc điểm của giới Nấm?', 'Có 2 ý không phải đặc điểm của giới Nấm: Ý (2) sai vì thành tế bào nấm chủ yếu bằng chitin (không phải xenluloz); Ý (3) sai vì nấm sống dị dưỡng (hoại sinh hoặc kí sinh, không có khả năng tự dưỡng).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 37 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Ghép nội dung ở cột A (Giới sinh vật) với cột B (Cấu trúc) cho phù hợp.', 'Giới Khởi sinh: tế bào nhân sơ, đơn bào (I-1, 3); Giới Nguyên sinh: nhân thực, đơn bào hoặc đa bào (II-2, 3, 4); Giới Thực vật: nhân thực, đa bào (III-2, 4); Giới Nấm: nhân thực, đơn bào hoặc đa bào (IV-2, 3, 4); Giới Động vật: nhân thực, đa bào (V-2, 4).', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 38 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Để bảo quản thực phẩm trước sự tấn công của vi khuẩn hoại sinh, chúng ta có thể áp dụng phương pháp nào sau đây?', 'Các biện pháp bảo quản như ướp lạnh, sấy khô, ướp muối đều ức chế hoặc tiêu diệt sự phát triển và sinh sôi của vi khuẩn hoại sinh.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 39 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Bệnh sốt xuất huyết do virus nào gây ra', 'Bệnh sốt xuất huyết do virus Dengue gây ra, truyền sang người qua vết đốt của muỗi vằn Aedes aegypti.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 40 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trùng sốt rét do máu truyền vào máu người sẽ đi tới', 'Sau khi xâm nhập vào máu người qua vết đốt của muỗi Anopheles, trùng sốt rét theo dòng máu di chuyển đầu tiên đến tế bào gan để sinh sản trước khi chui vào phá hủy hồng cầu.', 'KHTN 6 - HK1 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công toàn bộ 4 đề thi Cuối kì 1 KHTN 6 (160 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 3. LỚP 6 - GIỮA HỌC KỲ 2 (Nguồn: insert code lớp 6 giữa kì 2.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point DOUBLE PRECISION := 0.5; -- Đề 20 câu, thang điểm 10.0
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 6
    SELECT id INTO v_class_id FROM grades WHERE grade = 6;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 6', 6, 'Chương trình Khoa học tự nhiên THCS Lớp 6', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 2
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 2;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 2', 2, 'Học kỳ 2 năm học Lớp 6', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 6 HỌC KỲ 2
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN6_HK2';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 6', 'KHTN6_HK2', 'Môn Khoa học Tự nhiên Lớp 6 - Học kỳ 2', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA KÌ 2 KHTN 6 - ĐỀ SỐ 1
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN6_01',
        'Đề thi giữa kì 2 KHTN 6 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cây trồng nào sau đây không được xem là cây lương thực?', 'Lương thực là thức ăn chứa hàm lượng lớn tinh bột, nguồn cung cấp chính về năng lượng và chất bột đường trong khẩu phần thức ăn. Cây trồng thuộc nhóm lương thực là cây lúa, cây ngô, lúa mì,… Cây trồng không thuộc nhóm lương thực: cây nho.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các thực phẩm dưới đây, loại nào chứa nhiều protein (chất đạm) nhất?', 'Protein còn gọi là chất đạm, có vai trò cấu tạo, duy trì và phát triển cơ thể; protein liên quan đến mọi chức năng sống của cơ thể và cần thiết cho sự chuyển hóa các chất dinh dưỡng. Protein có nhiều trong thịt, cá, trứng, sữa và các loại hạt như đậu, đỗ…', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ngô, khoai sẽ cung cấp chất dinh dưỡng nào nhiều nhất cho cơ thể?', 'Ngô, khoai cùng với gạo là nguồn cung cấp carbohydrate chính cho cơ thể.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nhận xét nào sau đây là không đúng về thực phẩm?', 'Lương thực, thực phẩm dễ bị hư hỏng, biến đổi tính chất khi để lâu ngoài không khí, nhất là trong môi trường nóng, ẩm. Khi đó, chúng sinh ra những chất độc, có hại cho sức khỏe.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một trong những tính chất nào sau đây cho biết chất lỏng là tinh khiết?', 'Chất tinh khiết được tạo ra từ một chất duy nhất, mỗi chất tinh khiết đều có thành phần hóa học và tính chất nhất định (như nhiệt độ sôi, nhiệt độ đông đặc/hóa rắn không đổi).', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hỗn hợp được tạo ra từ', 'Hỗn hợp được tạo ra khi hai hay nhiều chất trộn lẫn với nhau.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn cụm từ còn thiếu ở nhận định sau: “Chất tinh khiết có tính chất…”.', 'Chất tinh khiết có tính chất vật lí và hóa học nhất định.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Không khí là', 'Không khí chứa nhiều loại chất khí khác nhau trộn lẫn như oxygen, nitrogen, carbon dioxide,... nên không khí là một hỗn hợp.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào dưới đây không phải của giới Nấm?', 'Nấm là những sinh vật nhân thực, đơn bào hoặc đa bào, sống dị dưỡng và tế bào không có lục lạp chứa sắc tố quang hợp.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vòng cuống nấm và bao gốc nấm là đặc điểm có ở loại nấm nào?', 'Nấm độc thường có màu sắc sặc sỡ, có vòng cuống nấm và bao gốc nấm.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Loại nấm nào dưới đây được sử dụng để sản xuất rượu vang?', 'Người ta sử dụng nấm men để lên men các loại quả như nho nhằm phục vụ cho việc sản xuất rượu vang.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Loại nấm nào được sử dụng để sản xuất penicillin?', 'Loại nấm được sử dụng để sản xuất kháng sinh penicillin là nấm mốc (Penicillium).', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Con đường nào dưới đây không phải là con đường lây truyền các bệnh do nấm?', 'Các bệnh do nấm lây qua: tiếp xúc với vật nuôi/cơ thể nhiễm bệnh, dùng chung đồ cá nhân, môi trường ô nhiễm, vệ sinh cơ thể kém; không có cơ chế truyền dọc từ mẹ sang con.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi trồng nấm rơm, người ta thường chọn vị trí có điều kiện như thế nào?', 'Khi trồng nấm rơm cần chọn vị trí thoáng mát, tránh ánh nắng trực tiếp để không làm khô ráo hay ảnh hưởng xấu tới sự sinh trưởng của hệ sợi và quả thể nấm.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đại diện nào dưới đây không thuộc ngành Thực vật?', 'Rong đuôi chó (Ceratophyllum) trên thực tế thường được phân loại khác biệt hoặc theo chương trình SGK, đại diện không thuộc ngành Thực vật được chỉ ra trong đáp án là rong đuôi chó.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cây rêu thường mọc ở nơi có điều kiện như thế nào?', 'Rêu thường sống ở nơi ẩm ướt do cơ thể chưa có mạch dẫn thực sự và chưa có rễ chính thức, sinh sản phụ thuộc vào nước.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Loại thực vật nào dưới đây có chứa chất độc gây hại đến sức khỏe của con người?', 'Nhựa cây trúc đào có chứa chất độc glucoside (oleandrin). Chất này đi vào cơ thể có thể gây buồn nôn, mệt lả, chóng mặt, tụt huyết áp, rối loạn nhịp tim và tử vong.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cơ quan sinh sản của ngành Hạt trần được gọi là gì?', 'Thực vật Hạt trần chưa có hoa và quả thật sự; cơ quan sinh sản của chúng là các nón (nón đực và nón cái), hạt nằm lộ trên các lá noãn hở.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hành động nào dưới đây góp phần bảo vệ thực vật?', 'Trồng cây gây rừng giúp bảo vệ độ che phủ của rừng, bảo tồn các loài thực vật và chống xói mòn đất.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ở dương xỉ, ổ túi bào tử thường nằm ở đâu?', 'Ở dương xỉ, các túi bào tử chứa bào tử sinh sản thường tập trung thành từng đốm nhỏ (ổ túi bào tử) ở mặt dưới của các lá già.', 'KHTN 6 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI GIỮA KÌ 2 KHTN 6 - ĐỀ SỐ 2
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN6_02',
        'Đề thi giữa kì 2 KHTN 6 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm của người bị bệnh hắc lào là?', 'Bệnh hắc lào do một loại nấm gây ra. Người bị bệnh hắc lào thường xuất hiện vùng da có dạng tròn, đóng vảy, có thể sưng đỏ và gây ngứa.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm cơ bản nhất để phân biệt nhóm động vật có xương sống với nhóm động vật không xương sống là?', 'Đặc điểm cơ bản nhất để phân biệt nhóm động vật có xương sống với nhóm động vật không xương sống là: có xương sống.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong những nhóm cây sau đây, nhóm gồm các cây thuộc ngành Hạt kín là?', 'Cây bưởi, cây táo, cây hồng xiêm, cây lúa đều là thực vật có hoa và hạt được bảo vệ bên trong quả (ngành Hạt kín). Cây thông, vạn tuế thuộc ngành Hạt trần; dương xỉ thuộc ngành Dương xỉ; rêu thuộc ngành Rêu.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nhóm động vật nào sau đây có số lượng loài lớn nhất?', 'Nhóm chân khớp là nhóm có số lượng loài lớn nhất trong số các ngành động vật. Nhóm có hơn 1 triệu loài được mô tả, chiếm trên 80% tất cả các loài sinh vật được tìm thấy trên Trái Đất.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sự đa dạng của động vật được thể hiện rõ nhất ở:', 'Sự đa dạng của động vật được thể hiện rõ nhất ở số lượng loài và môi trường sống phong phú (dưới nước, trên cạn, trong đất, trên không).', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các vai trò sau:' || chr(10) || '(1) Đảm bảo sự phát triển bền vững của con người.' || chr(10) || '(2) Là nguồn cung cấp tài nguyên vô cùng, vô tận.' || chr(10) || '(3) Phục vụ nhu cầu tham quan, giải trí của con người.' || chr(10) || '(4) Giúp con người thích nghi với biến đổi khí hậu.' || chr(10) || '(5) Liên tục hình thành thêm nhiều loài mới phục vụ cho nhu cầu của con người.' || chr(10) || 'Những vai trò nào là vai trò của đa dạng sinh học đối với con người?', 'Đa dạng sinh học đảm bảo sự phát triển bền vững của con người thông qua việc: Cung cấp ổn định nguồn nước, lương thực, thực phẩm; Tạo ra môi trường sống thuận lợi; Tạo cảnh quan thiên nhiên phục vụ tham quan, giải trí; Giúp con người ứng phó với thay đổi khí hậu bằng cách giảm ảnh hưởng của thiên tai.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thực vật góp phần làm giảm ô nhiễm môi trường bằng cách:', 'Thực vật góp phần làm giảm ô nhiễm môi trường bằng cách tán lá giữ lại bụi bẩn, hấp thụ các khí độc, đồng thời qua quang hợp giúp cân bằng hàm lượng CO₂ và O₂ trong khí quyển.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khẳng định nào sau đây là đúng?', 'Nấm là những sinh vật nhân thực, cấu tạo đơn bào (nấm men) hoặc đa bào (nấm mốc, nấm đảm), sống dị dưỡng.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thực vật có vai trò gì đối với động vật?', 'Thực vật tổng hợp chất hữu cơ và giải phóng oxygen cung cấp cho hoạt động sống và là nguồn thức ăn của động vật. Ngoài ra, thực vật còn cung cấp nơi ở, nơi sinh sản và bảo vệ cho nhiều loài động vật.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Động vật có xương sống bao gồm:', 'Động vật có xương sống bao gồm các lớp động vật chính: cá, lưỡng cư, bò sát, chim và thú (động vật có vú).', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Các loài nào dưới đây là vật chủ trung gian truyền bệnh?', 'Các loài động vật là vật chủ trung gian truyền bệnh phổ biến gây nguy hại cho sức khỏe con người gồm ruồi (truyền bệnh tiêu hóa), muỗi (sốt xuất huyết, sốt rét), chuột (dịch hạch).', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sinh cảnh nào dưới đây có độ đa dạng sinh học thấp nhất?', 'Hoang mạc là nơi có khí hậu khắc nghiệt, biên độ nhiệt ngày và đêm lớn, lượng mưa rất ít nên có rất ít loài sinh vật có thể thích nghi, dẫn đến độ đa dạng sinh học thấp nhất.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Năng lượng có thể truyền từ vật này sang vật khác thông qua:', 'Năng lượng có thể truyền từ vật này sang vật khác thông qua hai hình thức cơ bản là tác dụng lực (thực hiện công) và truyền nhiệt.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các tình huống sau đây, tình huống nào có lực tác dụng mạnh nhất?', 'Tình huống gió bão có năng lượng khổng lồ tác dụng lực cực mạnh làm gãy đổ cây cối và phá hủy các công trình xây dựng kiên cố.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chúng ta nhận biết điện năng từ ổ cắm điện cung cấp cho máy tính thông qua biểu hiện:', 'Điện năng cung cấp cho máy tính được chuyển hóa và nhận biết qua: ánh sáng từ màn hình/đèn báo, âm thanh phát ra khi hoạt động/khởi động, và nhiệt lượng tỏa ra từ thân máy.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Loại năng lượng nào làm máy phát điện ở nhà máy thủy điện tạo ra điện?', 'Trong nhà máy thủy điện, năng lượng của dòng nước chảy từ trên cao làm quay cánh tuabin gắn với máy phát để tạo ra điện năng.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây là đúng khi nói về định luật bảo toàn năng lượng?', 'Định luật bảo toàn năng lượng khẳng định: Năng lượng không tự sinh ra cũng không tự mất đi, nó chỉ chuyển hóa từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Năng lượng của nước chứa trong hồ của đập thủy điện là:', 'Nước được ngăn giữ ở trên độ cao của đập chứa dự trữ năng lượng dưới dạng thế năng hấp dẫn.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong quá trình chuyển hóa lẫn nhau của năng lượng từ dạng này sang dạng khác, tổng năng lượng tại bất kỳ thời điểm nào cũng:', 'Theo định luật bảo toàn năng lượng, trong một hệ kín, năng lượng toàn phần luôn được bảo toàn và không đổi tại bất kỳ thời điểm nào.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một người đàn ông đứng trên đỉnh núi thả rơi một viên đá xuống chân núi, lấy mốc thế năng ở chân núi. Trong quá trình rơi của viên đá đã có sự chuyển hóa năng lượng là:', 'Khi thả rơi, thế năng của viên đá giảm dần và chuyển hóa thành động năng (làm tốc độ tăng dần); đồng thời do ma sát với không khí, một phần năng lượng chuyển hóa thành nhiệt năng tỏa ra môi trường.', 'KHTN 6 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN III: ĐỀ THI GIỮA KÌ 2 KHTN 6 - ĐỀ SỐ 3
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN6_03',
        'Đề thi giữa kì 2 KHTN 6 Kết nối tri thức - Đề số 3',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 3.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Nguyên sinh vật dưới đây có tên là:', 'Nguyên sinh vật trong hình là tảo lục.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Một quyển sách 100g và một quả cân bằng sắt 100g đặt gần nhau nên mặt bàn. Nhận xét nào sau đây là không đúng?', 'Một quyển sách 100g và một quả cân bằng sắt 100g đặt gần nhau trên mặt bàn có cùng khối lượng là 100g, cùng trọng lượng xấp xỉ 1N, có lực hấp dẫn giữa chúng nhưng có thể tích khác nhau do khối lượng riêng của sắt lớn hơn nhiều so với giấy.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Chọn đáp án sai?', 'Mọi quá trình biến đổi trong tự nhiên đều cần tới năng lượng, do đó phát biểu A là sai.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Loài thiên địch sử dụng đẻ trứng kí sinh vào sinh vật gây hại hay trứng của sinh vật gây hại?', 'Ong mắt đỏ là loài thiên địch được sử dụng để đẻ trứng kí sinh vào trứng của sâu hại, tiêu diệt sâu hại ngay từ giai đoạn trứng.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong các hoạt động sau, hoạt động nào xuất hiện lực tiếp xúc?', 'Người thợ dùng búa đóng vào cọc tiếp xúc trực tiếp với cọc nên xuất hiện lực tiếp xúc. Viên đá rơi (trọng lực) và nam châm hút viên bi sắt (lực từ) là các lực không tiếp xúc.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong tự nhiên, nguyên sinh vật có vai trò:', 'Trong tự nhiên, nguyên sinh vật đóng vai trò quan trọng: tảo quang hợp cung cấp oxygen cho thủy sinh vật, là nguồn thức ăn cho động vật lớn hơn, và nhiều loài sống cộng sinh hỗ trợ sự sống của sinh vật khác.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 3 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Lần lượt treo vào một lò xo các vật có khối lượng m1, m2, m3 thì lò xo dãn ra như hình vẽ. Hãy so sánh các khối lượng m1, m2, m3.', 'Độ dãn của lò xo treo thẳng đứng tỉ lệ thuận với khối lượng của vật treo. Quan sát chiều dài dãn của lò xo ta thấy: l2 > l1 > l3 nên tương ứng m2 > m1 > m3.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Mô liên kết ở người có chức năng:', 'Mô liên kết ở người có chức năng chính là nâng đỡ, liên kết và neo giữ các cơ quan trong cơ thể.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Virus được phát hiện lần đầu tiên từ cây gì?', 'Virus được phát hiện lần đầu tiên trên cây thuốc lá (virus khảm thuốc lá - TMV).', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Bước nhuộm xanh methylene khi làm tiêu bản quan sát vi khuẩn trong nước dưa muối, cà muối có ý nghĩa gì?', 'Tế bào vi khuẩn trong suốt khó nhìn, việc nhuộm xanh methylene giúp vi khuẩn bắt màu thuốc nhuộm đậm hơn, nổi bật dưới nền kính hiển vi để quan sát dễ dàng.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào của cây xanh giúp bổ sung vào bầu khí quyển lượng khí oxygen mất đi do hô hấp và đốt cháy nhiên liệu?', 'Hoạt động quang hợp của cây xanh hấp thụ khí carbon dioxide và giải phóng oxygen vào bầu khí quyển.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Môi trường có sự đa dạng sinh học lớn nhất là:', 'Rừng mưa nhiệt đới có điều kiện nhiệt độ, độ ẩm và ánh sáng dồi dào, thuận lợi nhất cho sự sống nên có độ đa dạng sinh học cao nhất trên cạn.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Ý nghĩa của việc xây dựng khóa lưỡng phân là:', 'Khóa lưỡng phân giúp phân chia sinh vật thành các nhóm xác định từ thấp đến cao dựa trên các cặp đặc điểm đối lập, giúp việc nhận diện và nghiên cứu khoa học trở nên trật tự, hiệu quả.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Lực xuất hiện khi lấy một chiếc thước nhựa khô và sạch cọ xát vào mảnh vải dạ hoặc len khô rồi đưa lại gần các vụn giấy mỏng là:', 'Thước nhựa sau khi cọ xát bị nhiễm điện và có khả năng hút các mẩu giấy vụn từ một khoảng cách nhất định mà chưa cần chạm vào, do đó đây là lực hút tĩnh điện (lực không tiếp xúc).', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào sau đây không đúng khi nói về nhóm Thân mềm?', 'Nhóm Thân mềm không phải tất cả đều có lợi; một số loài gây hại cho nông nghiệp và cây trồng như ốc bươu vàng, ốc sên phá hoại mùa màng.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Loại nấm không thể quan sát được bằng mắt thường là:', 'Nấm men là các loài nấm đơn bào có kích thước hiển vi siêu nhỏ nên không thể quan sát cấu trúc từng tế bào bằng mắt thường mà phải qua kính hiển vi.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đâu là mối quan hệ giữa trọng lượng và khối lượng?', 'Mối quan hệ giữa trọng lượng P và khối lượng m được tính theo công thức: P = m × g (trong đó g là gia tốc trọng trường, ở bậc THCS thường lấy gần đúng g ≈ 10 N/kg).', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Việc phân loại thế giới sống có ý nghĩa gì đối với chúng ta?' || chr(10) || '(1) Gọi đúng tên sinh vật.' || chr(10) || '(2) Đưa sinh vật vào đúng nhóm phân loại.' || chr(10) || '(3) Thấy được vai trò của sinh vật trong tự nhiên và thực tiễn.' || chr(10) || '(4) Nhận ra sự đa dạng của sinh giới.', 'Ý nghĩa chính của việc phân loại sinh học là: gọi đúng tên sinh vật (1), đưa sinh vật vào đúng nhóm phân loại (2) và nhận ra sự đa dạng phong phú của sinh giới (4).', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Làm thế nào để sử dụng nhiên liệu hiệu quả?', 'Để sử dụng nhiên liệu an toàn và tiết kiệm cần: cung cấp đủ không khí, tăng diện tích tiếp xúc giữa nhiên liệu với không khí, và điều chỉnh lượng nhiệt/nhiên liệu phù hợp với nhu cầu đun nấu, vận hành.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào dưới đây không đúng khi nói về vai trò vi khuẩn?', 'Khẳng định "Mọi vi khuẩn đều có lợi" là sai, vì có rất nhiều loài vi khuẩn gây bệnh nguy hiểm cho người, vật nuôi và cây trồng hoặc làm ôi thiu, hỏng thực phẩm.', 'KHTN 6 - GK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN IV: ĐỀ THI GIỮA KÌ 2 KHTN 6 - ĐỀ SỐ 4
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN6_04',
        'Đề thi giữa kì 2 KHTN 6 Kết nối tri thức - Đề số 4',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 4.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào dưới đây không có ở các loài động vật đới nóng?', 'Đặc điểm không có ở động vật đới nóng là thường hoạt động vào ban ngày trong mùa hè. Vì mùa hè nóng, động vật có xu hướng hoạt động vào ban đêm.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Khi đi xe đạp, bộ phận nào của xe đạp có thể xảy ra sự hao phí năng lượng nhiều nhất?', 'Bộ phận có thể xảy ra sự hao phí năng lượng nhiều nhất của xe đạp có thể là các chỗ tiếp xúc giữa trục với ổ bi, giữa bánh xe với mặt đường.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Lực nào sau đây là lực tiếp xúc?', 'Lực của quả cân tác dụng lên lò xo khi treo quả cân vào lò xo là lực tiếp xúc.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Nhóm thực vật là đại diện của nhóm dương xỉ là:', 'Nhóm thực vật đại diện cho nhóm dương xỉ là cây dương xỉ, cỏ bợ, lông culi, bèo ong.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào sau đây là đúng khi nói về vi khuẩn?', 'Cấu tạo vi khuẩn đơn giản, tế bào nhân sơ gồm thành tế bào, màng tế bào, chất tế bào và vùng nhân.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Trong 3 cách đun nước ở hình sau, cách đun trong hình nào ít hao phí năng lượng nhất?', 'Cách đun nước bằng cách dùng ấm điện ít hao phí năng lượng nhất vì gần như toàn bộ năng lượng cung cấp cho ấm sẽ làm nóng nước. Còn ở hai cách đun còn lại có nhiều năng lượng bị tổn thất ra bên ngoài môi trường.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cá cóc Tam Đảo được xếp vào nhóm ngành động vật nào?', 'Do cá cóc là động vật có xương sống, và có những đặc điểm thích nghi được với đời sống trên cạn giống như lưỡng cư nên được xếp vào nhóm Lưỡng cư.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Treo thẳng đứng một lò xo, đầu dưới treo quả nặng 100g thì độ biến dạng của lò xo là 0,5cm. Nếu thay quả nặng trên bằng một quả nặng khác thì độ biến dạng của lò xo là 1,5cm. Hãy xác định khối lượng của vật treo trong trường hợp này.', 'Do độ dãn của lò xo treo thẳng đứng tỉ lệ với khối lượng vật treo nên ta có: m2 = 100 * (1.5 / 0.5) = 300g.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tại sao khi phanh gấp, lốp xe ô tô để lại một vệt đen dài trên đường nhựa?', 'Khi phanh gấp, lốp xe ô tô để lại một vệt đen dài trên đường nhựa là do ma sát giữa lốp xe và mặt đường lớn làm cho cao su nóng lên, mềm ra và dính vào mặt đường.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong các trường hợp sau, trường hợp nào chịu lực cản của không khí?', 'Thợ lặn, con cá và tàu ngầm hoạt động dưới nước chịu lực cản của nước. Bạn Mai đi bộ trên bãi biển chịu lực cản của không khí.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Động vật nguyên sinh nào dưới đây có lớp vỏ bằng đá vôi?', 'Trùng lỗ là nguyên sinh vật duy nhất trong các đại diện trên có lớp vỏ bằng đá vôi.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm để phân biệt nấm đơn bào và nấm đa bào là:', 'Để phân biệt nấm đơn bào và nấm đa bào ta dựa vào số lượng tế bào cấu tạo nên cơ thể nấm.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong cơ thể sinh vật, một tế bào bắt đầu quá trình sinh sản để tạo nên các tế bào mới. Nếu tế bào này thực hiện 6 lần sinh sản liên tiếp thì sẽ tạo ra được bao nhiêu tế bào con?', 'Một tế bào qua n lần sinh sản (phân chia) liên tiếp sẽ tạo ra 2^n tế bào con. Với 6 lần sinh sản liên tiếp: 2^6 = 64 tế bào con.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đâu không phải là ví dụ của sự lớn lên và sinh sản tế bào?', 'Sự cụp lá cây xấu hổ khi chạm tay vào là ví dụ của tính cảm ứng ở sinh vật. Các phương án còn lại đều là ví dụ của sự lớn lên và sinh sản của tế bào.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Tế bào có chiều dài lớn nhất trong các loại tế bào sau là:', 'Tế bào có chiều dài lớn nhất là tế bào thần kinh người (nơron), chiều dài của sợi trục có thể lên tới khoảng 100 cm.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Chức năng bảo vệ và kiểm soát các chất đi vào và đi ra khỏi tế bào (quá trình trao đổi chất giữa tế bào và môi trường) là của bào quan nào?', 'Màng tế bào có chức năng bảo vệ tế bào và kiểm soát có chọn lọc các chất đi vào và đi ra khỏi tế bào.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hai chất lỏng không hòa tan vào nhau nhưng khi chịu tác động, chúng lại phân tán vào nhau thì gọi là:', 'Nhũ tương là hỗn hợp không đồng nhất gồm một hay nhiều chất lỏng phân tán trong môi trường chất lỏng khác mà không tan vào nhau.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hỗn hợp nào sau đây không được xem là dung dịch?', 'Hỗn hợp không được xem là dung dịch là bột mì và nước khuấy đều (đây là huyền phù), vì bột mì không tan trong nước tạo thành hỗn hợp đồng nhất.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Lục lạp ở tế bào thực vật có chức năng:', 'Lục lạp ở tế bào thực vật chứa sắc tố diệp lục, có chức năng quang hợp để tổng hợp chất hữu cơ từ năng lượng mặt trời và các chất vô cơ.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Chất có vai trò cấu tạo nên cơ thể sinh vật, tham gia cung cấp năng lượng và hầu hết các hoạt động sống là:', 'Chất đạm (protein) có vai trò cấu tạo nên tế bào và cơ thể sinh vật, tham gia cung cấp năng lượng cũng như điều hòa hầu hết các hoạt động sống của cơ thể.', 'KHTN 6 - GK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công toàn bộ 4 đề thi Giữa kì 2 KHTN 6 (80 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 4. LỚP 6 - CUỐI HỌC KỲ 2 (Nguồn: insert code lớp 6 kì 2.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_28 DOUBLE PRECISION := ROUND((10.0 / 28.0)::numeric, 4); -- ~0.3571 điểm/câu cho đề 28 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 6
    SELECT id INTO v_class_id FROM grades WHERE grade = 6;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 6', 6, 'Chương trình Khoa học tự nhiên THCS Lớp 6', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 2
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 2;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 2', 2, 'Học kỳ 2 năm học Lớp 6', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 6 HỌC KỲ 2
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN6_HK2';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 6', 'KHTN6_HK2', 'Môn Khoa học Tự nhiên Lớp 6 - Học kỳ 2', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI HỌC KÌ 2 KHTN 6 - ĐỀ SỐ 1 (28 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK2_KHTN6_01',
        'Đề thi học kì 2 KHTN 6 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 2 gồm 28 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Độ giãn của lò xo treo theo phương thẳng đứng, tỉ lệ với:', 'Độ giãn của lò xo treo theo phương thẳng đứng tỉ lệ với khối lượng của vật treo.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tập hợp các loài nào dưới đây thuộc lớp Động vật có vú (Thú)?', 'Tập hợp các loài thuộc lớp Thú là: Cá voi, vịt trời, rùa, thỏ (theo đáp án chi tiết của đề thi).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu sau đây, phát biểu nào là đúng:', 'Lực hút Trái Đất có phương thẳng đứng, chiều hướng từ trên xuống dưới (hướng về phía tâm Trái Đất).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào sau đây không phải đặc điểm của Rêu?', 'Rêu là thực vật bậc thấp chưa có mạch dẫn ở thân và lá. Chúng chỉ có rễ giả là những sợi nhỏ, cơ quan sinh sản nằm ở ngọn cây và sinh sản bằng bào tử.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi quạt điện hoạt động thì có sự chuyển hóa:', 'Khi quạt điện hoạt động, phần lớn điện năng được chuyển hóa thành cơ năng làm cánh quạt quay.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Ghép một số thứ tự ở cột A với một chữ ở cột B để được một câu đúng hoàn chỉnh.', 'Dựa vào kiến thức về sự chuyển hóa giữa các dạng năng lượng, thứ tự ghép nối chính xác là: 1 – c; 2 – b; 3 – d; 4 – e; 5 – a.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các vật liệu sau, vật liệu dẫn điện tốt là:', 'Kim loại có nhiều hạt mang điện tự do nên dẫn điện rất tốt; thủy tinh, gốm, cao su là các vật liệu cách điện.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đa dạng sinh học không biểu thị ở tiêu chí nào sau đây?', 'Theo kiến thức chương trình, độ đa dạng sinh học thường được thể hiện qua các tiêu chí đa dạng loài, đa dạng môi trường sống và đa dạng hệ sinh thái.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây là biểu hiện của một vật có động năng?', 'Động năng là năng lượng mà một vật có được do chuyển động, do đó vật chuyển động là biểu hiện của động năng.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây xuất hiện lực ma sát trượt?', 'Khi viết phấn trên bảng, đầu viên phấn trượt trên bề mặt nhám của bảng làm xuất hiện lực ma sát trượt.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thế năng đàn hồi của vật là:', 'Thế năng đàn hồi là dạng năng lượng xuất hiện khi vật bị biến dạng đàn hồi (như lò xo bị nén hoặc kéo dãn).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khẳng định nào dưới đây đúng khi nói về cấu tạo của nấm?', 'Trong cấu tạo nấm lớn, phần sợi nấm nằm dưới cơ chất đóng vai trò là cơ quan sinh dưỡng; phần mũ nấm và cuống nấm thuộc cơ quan sinh sản.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đơn vị của trọng lực là:', 'Trọng lực là một loại lực hút nên có đơn vị đo là niutơn (kí hiệu: N).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vợt bắt bướm được dùng để bắt các loài động vật nào?', 'Vợt bắt bướm được sử dụng để bắt các loài côn trùng bay hoặc nhảy trên mặt đất, tán lá như bướm, cào cào, châu chấu.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các dụng cụ và thiết bị sau đây, thiết bị nào chủ yếu biến đổi điện năng thành cơ năng.', 'Quạt điện biến đổi phần lớn điện năng thành cơ năng làm quay cánh quạt tạo gió. Bàn là, bếp điện biến điện năng thành nhiệt năng; bóng đèn biến điện năng thành quang năng.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các hoạt động làm suy giảm đa dạng sinh học là:', 'Ô nhiễm môi trường, chặt phá rừng và săn bắt bừa bãi động thực vật hoang dã đều là những nguyên nhân chính trực tiếp làm suy giảm đa dạng sinh học.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một quyển sách nằm yên trên mặt bàn, lực hấp dẫn do Trái Đất tác dụng vào quyển sách có độ lớn', 'Độ lớn của lực hấp dẫn mà Trái Đất tác dụng lên vật chính là trọng lượng của vật đó.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Lực nào sau đây là lực không tiếp xúc?', 'Trọng lực (lực hút của Trái Đất) tác dụng lên quyển sách từ xa mà không cần sự tiếp xúc trực tiếp giữa Trái Đất và vật.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây liên quan đến lực tiếp xúc?', 'Khi thủ môn bắt bóng, bàn tay tiếp xúc trực tiếp với bề mặt quả bóng để cản phá nên đây là lực tiếp xúc.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong cùng một khu vực, so với nơi trống trải thì nơi có rừng có gì khác biệt về khí hậu?', 'Tán cây rừng cản bức xạ mặt trời và quá trình thoát hơi nước giúp làm dịu môi trường xung quanh, khiến nhiệt độ nơi có rừng thường thấp hơn và mát mẻ hơn nơi trống trải.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Lực nào sau đây là lực không tiếp xúc? (Câu 21)', 'Lực không tiếp xúc xuất hiện khi vật gây ra lực không tiếp xúc trực tiếp với vật chịu tác dụng của lực (lực hút Trái Đất).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đại diện nào dưới đây thuộc lớp bò sát?', 'Cá sấu là động vật có xương sống thuộc lớp Bò sát. Cá cóc bụng hoa thuộc lớp Lưỡng cư, cá ngựa thuộc lớp Cá, cá heo thuộc lớp Thú.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Năng lượng nào sau đây không phải năng lượng tái tạo?', 'Than đá là nhiên liệu hóa thạch, phải mất hàng triệu năm mới hình thành nên là nguồn năng lượng không tái tạo.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Sự chuyển thể nào sau đây xảy ra tại nhiệt độ xác định?', 'Sự sôi là sự hóa hơi đặc biệt diễn ra ở cả mặt thoáng và trong lòng chất lỏng tại một nhiệt độ xác định (gọi là nhiệt độ sôi).', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Mặt trời là một ngôi sao trong Ngân Hà. Chúng ta thấy Mặt Trời to và sáng hơn nhiều so với các ngôi sao khác trên bầu trời. Điều này là do:', 'Mặt Trời có kích thước và độ sáng trung bình trong dải Ngân Hà, nhưng vì nó là ngôi sao ở khoảng cách gần Trái Đất nhất nên ta thấy nó to và sáng nhất.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thực vật góp phần làm giảm ô nhiễm môi trường bằng cách', 'Thực vật cản bớt bụi bẩn, hấp thụ khí độc và thông qua quang hợp giúp cân bằng hàm lượng CO₂ và O₂ trong khí quyển.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hành tinh nào xếp thứ ba kể từ Mặt Trời?', 'Thứ tự sắp xếp các hành tinh từ Mặt Trời ra xa gồm: Thủy Tinh → Kim Tinh → Trái Đất → Hỏa Tinh → Mộc Tinh → Thổ Tinh → Thiên Vương Tinh → Hải Vương Tinh. Do đó Trái Đất xếp thứ ba.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một vật trên mặt đất có khối lượng 5 kg bị Trái đất hút 1 lực bằng bao nhiêu N?', 'Độ lớn lực hút của Trái Đất (trọng lượng): P = 10 x m = 10 x 5 = 50 N.', 'KHTN 6 - HK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI HỌC KÌ 2 KHTN 6 - ĐỀ SỐ 2 (28 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK2_KHTN6_02',
        'Đề thi học kì 2 KHTN 6 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 2 gồm 28 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các dụng cụ và thiết bị sau đây, thiết bị nào chủ yếu biến đổi điện năng thành nhiệt năng.', 'Bàn là điện là thiết bị chủ yếu biến đổi điện năng thành nhiệt năng để làm phẳng quần áo. Máy khoan, quạt điện và máy bơm nước chủ yếu biến đổi điện năng thành cơ năng.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vật liệu nào là chất cách điện?', 'Gỗ (khô) là chất cách điện. Đồng, sắt, nhôm là các kim loại có tính dẫn điện tốt.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cây nào dưới đây không được xếp vào nhóm thực vật có hoa?', 'Cây dương xỉ sinh sản bằng bào tử, không có hoa. Cây chuối, cây ngô, cây lúa đều là thực vật có hoa (ngành Hạt kín).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào làm xuất hiện lực không tiếp xúc?', 'Quả táo rơi từ trên cây xuống do tác dụng của trọng lực (lực hút của Trái Đất), đây là lực không tiếp xúc. Các trường hợp còn lại đều xuất hiện lực tiếp xúc giữa các vật.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nấm đảm là loại nấm có thể quả dạng', 'Nấm đảm (như nấm rơm, nấm hương,...) thường có cơ quan sinh sản (thể quả) dạng hình mũ.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Người ta biểu diễn lực bằng yếu tố gì?', 'Lực là một đại lượng vectơ nên được biểu diễn bằng một mũi tên có gốc là điểm đặt của lực, hướng theo hướng của lực và độ dài biểu diễn độ lớn của lực theo một tỉ xích cho trước.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vì sao nói thực vật có vai trò bảo vệ đất và nguồn nước?', 'Thực vật có hệ rễ phát triển mạnh giúp giữ đất chống xói mòn, tán cây cản bớt sức nước chảy do mưa lớn gây ra, giúp nước mưa thấm dần xuống các lớp đất sâu tạo thành nguồn nước ngầm.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào đúng về lò xo?', 'Lực đàn hồi xuất hiện ở hai đầu lò xo và luôn có chiều ngược với chiều biến dạng của lò xo (chống lại sự biến dạng).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Lứa tuổi từ 11 - 15 là lứa tuổi có sự phát triển nhanh chóng về chiều cao. Chất quan trọng nhất cho sự phát triển của xương là:', 'Calcium (canxi) là thành phần khoáng chất cấu tạo chính yếu của xương và răng, quyết định sự phát triển chiều cao và độ chắc khỏe của xương.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chỉ có thể nói về trọng lực của vật nào?', 'Trọng lực là lực hút của Trái Đất tác dụng lên vật thể nằm trong vùng trường hấp dẫn của nó. Do đó, ta nói về trọng lực của người (hoặc vật) đứng trên mặt đất.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong những nhóm cây sau đây, nhóm gồm các cây thuộc ngành Hạt kín là:', 'Nhóm gồm các cây thuộc ngành Hạt kín là: cây bưởi, cây táo, cây hồng xiêm, cây lúa. (Dương xỉ thuộc ngành Dương xỉ; rêu thuộc ngành Rêu; thông, vạn tuế thuộc ngành Hạt trần).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào không xuất hiện lực ma sát?', 'Khi lò xo bị nén chỉ xuất hiện lực đàn hồi chống lại sự nén. Các trường hợp còn lại đều có lực ma sát (lăn, trượt hoặc nghỉ).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các vật liệu sau, vật liệu dẫn điện tốt là: (Câu 13)', 'Kim loại có nhiều hạt mang điện tự do (electron tự do) nên là vật liệu dẫn điện tốt. Thủy tinh, gốm, cao su là chất cách điện.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi thả rơi quả bóng từ độ cao 3m xuống mặt đất thì quả bóng chịu tác dụng của những lực nào?', 'Khi quả bóng rơi trong khí quyển, nó đồng thời chịu tác dụng của trọng lực (lực hút Trái Đất kéo bóng xuống) và lực cản của không khí (ngược chiều chuyển động).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một học sinh đá quả bóng nhựa vào tường sau đó quả bóng bị méo đi. Lực tác dụng lên quả bóng sẽ gây ra những kết quả nào sau đây?', 'Quả bóng va chạm vào tường bị bật ngược trở lại (biến đổi chuyển động) và bị méo đi (biến dạng). Như vậy lực vừa làm biến dạng vừa làm biến đổi chuyển động của quả bóng.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Mũi tên được bắn bay đi là nhờ năng lượng từ đâu?', 'Khi cánh cung bị kéo căng, nó tích trữ thế năng đàn hồi. Khi buông tay, thế năng đàn hồi của cánh cung chuyển hóa thành động năng đẩy mũi tên bay đi.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu sau đây, phát biểu nào đúng? (Câu 17)', 'Cả ba phát biểu A, B, C đều đúng theo định luật vạn vật hấp dẫn và khái niệm về trọng lượng trong vật lí.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dạng năng lượng tích trữ trong cánh cung khi được kéo căng là gì?', 'Cánh cung bị biến dạng đàn hồi khi kéo căng nên tích trữ thế năng đàn hồi.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây liên quan đến lực tiếp xúc? (Câu 19)', 'Thủ môn bắt bóng cần có sự tiếp xúc trực tiếp giữa tay/găng tay của thủ môn và bề mặt quả bóng, nên đây là lực tiếp xúc. Các trường hợp còn lại liên quan đến lực hấp dẫn (lực không tiếp xúc).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thiết bị nào sẽ biến đổi điện năng chủ yếu thành nhiệt năng?', 'Bếp điện sử dụng dòng điện để đốt nóng dây mayso hoặc mặt kính từ/hồng ngoại, biến đổi điện năng chủ yếu thành nhiệt năng để đun nấu.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào dưới đây không phải của nấm?', 'Tế bào nấm không chứa lục lạp nên nấm không có khả năng quang hợp mà sống bằng hình thức dị dưỡng (hoại sinh hoặc kí sinh).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong quá trình đun nước sôi thì năng lượng nào có ích?', 'Mục đích chính của việc đun nước là làm nóng và sôi lượng nước trong ấm, nên phần nhiệt lượng truyền cho nước trong ấm là năng lượng có ích. Nhiệt làm nóng vỏ ấm và thất thoát ra không khí là năng lượng hao phí.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các vật sau đây, vật nào có thế năng đàn hồi?', 'Dây cao su khi bị kéo dãn (biến dạng đàn hồi) sẽ tích trữ thế năng đàn hồi.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đồ dùng nào sử dụng nguồn năng lượng tái tạo?', 'Năng lượng mặt trời và năng lượng gió đều là các nguồn năng lượng tái tạo vô tận, sạch và thân thiện với môi trường. Cả 3 đồ dùng trên đều khai thác các nguồn năng lượng này.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Ở Ninh Thuận, người ta dùng các tuabin gió để sản xuất điện. Năng lượng cung cấp cho tuabin gió là:', 'Tuabin gió vận hành nhờ động năng của các luồng gió thổi làm quay cánh quạt tuabin để máy phát tạo ra điện.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Biện pháp nào sẽ giúp tiết kiệm năng lượng?', 'Tất cả các biện pháp trên đều là thói quen sử dụng điện khoa học, hiệu quả và giúp tiết kiệm năng lượng.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên nhân gây bệnh giun sán kí sinh ở người là:', 'Trứng giun, ấu trùng sán thường bám trên rau sống chưa rửa sạch hoặc nằm trong thịt cá sống/tái (gỏi cá). Ăn các món này là nguyên nhân trực tiếp dẫn tới nhiễm giun sán.', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chuyển động nào là chuyển động thực?', 'Chuyển động Trái Đất tự quay quanh trục từ Tây sang Đông và chuyển động quanh Mặt Trời là các chuyển động thực. Việc ta thấy Mặt Trời mọc ở đằng Đông lặn ở đằng Tây chỉ là chuyển động nhìn thấy (chuyển động biểu kiến).', 'KHTN 6 - HK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN III: ĐỀ THI HỌC KÌ 2 KHTN 6 - ĐỀ SỐ 3 (28 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK2_KHTN6_03',
        'Đề thi học kì 2 KHTN 6 Kết nối tri thức - Đề số 3',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 2 gồm 28 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 3.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Độ dãn của lò xo treo theo phương thẳng đứng, tỉ lệ với:', 'Độ dãn của lò xo treo thẳng đứng tỉ lệ thuận với khối lượng của vật treo vào nó (hoặc trọng lượng của vật treo).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào sử dụng năng lượng hiệu quả?', 'Gom đủ lượng quần áo định mức cho mỗi lần giặt giúp tiết kiệm điện và nước tối đa, tránh lãng phí năng lượng khi vận hành máy giặt nhiều lần.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi quạt điện hoạt động thì có sự chuyển hóa:', 'Quạt điện tiêu thụ điện năng từ nguồn để làm quay cánh quạt (tạo thành cơ năng).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong quá trình sử dụng tủ lạnh, năng lượng hao phí là gì?', 'Năng lượng có ích là nhiệt lượng lấy đi từ bên trong tủ để làm mát; phần nhiệt lượng tỏa ra ngoài môi trường ở giàn nóng và âm thanh rung phát ra từ động cơ là năng lượng hao phí.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong số các tác hại sau, tác hại nào không phải do nấm gây ra?', 'Bệnh viêm gan B ở người do virus viêm gan B (HBV) gây ra, không phải do nấm.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây là đúng về sự chuyển hóa năng lượng trong các dụng cụ sau?', 'Khi hoạt động, nồi cơm điện biến đổi điện năng thành nhiệt năng (chủ yếu để làm chín cơm) và quang năng (ở các đèn báo tín hiệu).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Vật chất di truyền của một virus là', 'Lõi vật chất di truyền của mỗi loại virus chỉ chứa một trong hai loại axit nucleic: hoặc là ADN, hoặc là ARN (không bao giờ chứa đồng thời cả hai loại).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nếu chọn mặt đất làm mốc tính thế năng thì vật nào sau đây có thế năng hấp dẫn?', 'Mũi tên đang bay ở một độ cao nhất định so với mặt đất nên nó sở hữu thế năng hấp dẫn.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Rêu là thực vật có đặc điểm nào sau đây?', 'Rêu là nhóm thực vật bậc thấp chưa có mạch dẫn, chưa có hoa và hạt; cơ quan sinh sản của rêu là túi bào tử và sinh sản bằng bào tử.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trong các trường hợp sau, trường hợp nào chịu lực cản của nước?', 'Khi bơi lội, cơ thể bạn Lan chuyển động trong môi trường nước nên chịu tác dụng của lực cản của nước.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Khi bếp ga hoạt động có sự chuyển hóa:', 'Khí gas cháy giải phóng năng lượng tích trữ trong các liên kết hóa học (hóa năng) biến đổi thành nhiệt năng (và quang năng) để đun nấu thức ăn.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trọng lượng của một vật được tính theo công thức nào?', 'Mối liên hệ xấp xỉ giữa trọng lượng P (đơn vị N) và khối lượng m (đơn vị kg) của một vật trên bề mặt Trái Đất là: P = 10 · m.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Động vật nào sau đây thuộc lớp Thú?', 'Dơi là động vật có vú (lớp Thú) thích nghi với đời sống bay lượn, sinh con và nuôi con bằng sữa mẹ. Chim cánh cụt và đà điểu thuộc lớp Chim; cá sấu thuộc lớp Bò sát.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào xảy ra do trọng lực tác dụng lên vật?', 'Quả dừa rụng rơi thẳng đứng từ trên cao xuống đất là do tác dụng của trọng lực (lực hút của Trái Đất).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Nội dung nào dưới đây là đúng khi nói về nguyên sinh vật?', 'Phần lớn nguyên sinh vật là cơ thể đơn bào nhân thực kích thước vi mô (như trùng giày, trùng roi, tảo lục); một số loài tảo (như tảo xoắn, rong mơ) có cấu tạo đa bào kích thước lớn nhìn thấy được bằng mắt thường.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào lực ma sát có ích?', 'Lực ma sát giữa phấn và bảng giúp bột phấn bám dính để lại nét chữ trên bảng (khi bảng quá trơn/ma sát kém thì không viết được). Vì vậy ma sát ở đây là có ích.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Động vật ở vùng lạnh thường có hiện tượng ngủ đông, điều đó có ý nghĩa nào dưới đây?', 'Vào mùa đông lạnh giá thức ăn khan hiếm, trạng thái ngủ đông giúp hạ thân nhiệt và giảm tối đa tốc độ trao đổi chất, từ đó tiết kiệm năng lượng duy trì sự sống.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đơn vị của năng lượng là gì?', 'Trong hệ thống đo lường quốc tế (SI), đơn vị chuẩn của năng lượng và công cơ học là Jun (kí hiệu: J).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào dưới đây sai khi nói về nguyên nhân làm cho sinh vật nhiệt đới đa dạng và phong phú?', 'Khí hậu ấm áp, nguồn thức ăn dồi dào và sinh cảnh phong phú là các điều kiện thuận lợi giúp sinh vật phát triển đa dạng. Sự cạnh tranh khốc liệt gay gắt không phải là nguyên nhân trực tiếp làm cho sinh vật trở nên đa dạng, phong phú.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Năng lượng được phân loại theo các tiêu chí nào?', 'Năng lượng thường được phân loại dựa theo 3 tiêu chí chủ đạo: nguồn gốc tạo ra năng lượng (tái tạo hay không tái tạo), nguồn gốc vật chất (hóa thạch, sinh khối, hạt nhân...) và mức độ ô nhiễm môi trường (năng lượng sạch hay năng lượng gây ô nhiễm).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Loài động vật nào dưới đây đẻ con?', 'Thỏ thuộc lớp Thú có hình thức sinh sản là thai sinh (đẻ con) và nuôi con bằng sữa mẹ. Cá chép, thằn lằn, chim bồ câu đều sinh sản bằng cách đẻ trứng.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Ngân Hà của chúng ta thuộc kiểu Thiên Hà nào?', 'Ngân Hà (Milky Way) là một thiên hà dạng xoắn ốc có thanh ngáng ở vùng trung tâm (thiên hà xoắn ốc).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Để tiến hành quan sát nguyên sinh vật cần chuẩn bị những dụng cụ, thiết bị gì?', 'Bộ dụng cụ chuẩn để làm tiêu bản giọt ép quan sát nguyên sinh vật gồm: Kính hiển vi, lam kính, lamen, ống nhỏ giọt, giấy thấm và cốc đựng mẫu nước ngâm.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Dải Ngân Hà là gì?', 'Dải Ngân Hà là tên gọi của thiên hà chứa Mặt Trời và Hệ Mặt Trời của chúng ta (bao gồm cả Trái Đất).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đà điểu không biết bay nhưng vẫn được xếp vào lớp Chim vì?', 'Dù không biết bay do cánh thoái hóa, đà điểu vẫn có các đặc điểm cấu tạo đặc trưng của lớp Chim: toàn thân có lông vũ bao phủ, mỏ sừng, chi trước biến đổi thành cánh và di chuyển trên mặt đất bằng 2 chân sau.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Một đơn vị thiên văn là gì?', 'Đơn vị thiên văn (kí hiệu: AU) là đơn vị đo khoảng cách trong thiên văn học, có giá trị xấp xỉ bằng khoảng cách trung bình từ Trái Đất đến Mặt Trời (khoảng 150 triệu km).', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào sau đây đúng khi nói về da của ếch?', 'Ếch thuộc lớp Lưỡng cư có đặc điểm da trần (không có vảy), luôn tiết chất nhầy ẩm ướt để hỗ trợ trao đổi khí qua da.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 3)
    VALUES ('SINGLE_CHOICE', 'Sao chổi là gì?', 'Sao chổi là một dạng tiểu hành tinh/thiên thể nhỏ chứa nhiều băng tuyết và bụi đá chuyển động quanh Mặt Trời theo quỹ đạo elip dẹt. Khi đến gần Mặt Trời, nhiệt làm bốc hơi băng tạo thành cái đuôi sáng kéo dài.', 'KHTN 6 - HK2 - Đề 3', NOW(), NOW()) RETURNING id INTO v_q_id;


