    -- Câu 1 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Năng lượng của nước chứa trong hồ của đập thủy điện là', 'Năng lượng của nước chứa trong hồ của đập thủy điện là thế năng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Năng lượng nào dưới đây là năng lượng tái tạo?', 'Năng lượng mặt trời là năng lượng tái tạo.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ nào sau đây khi hoạt động biến đối phần lớn điện năng mà nó nhận vào thành nhiệt năng?', 'Nồi cơm điện khi hoạt động biến đối phần lớn điện năng mà nó nhận vào thành nhiệt năng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Nhóm động vật nào sau đây không thuộc động vật có xương sống?', 'Nhóm động vật chân khớp không thuộc động vật có xương sống.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Biến dạng của vật nào dưới đây không phải là biến dạng đàn hồi?', 'Que nhôm bị uốn cong không phải là biến dạng đàn hồi (đây là biến dạng dẻo).', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hầu hết động vật lớp Thú có những đặc điểm nào dưới đây?' || chr(10) || '(1) Lông mao bao phủ khắp cơ thể.' || chr(10) || '(2) Đi bằng 2 chân' || chr(10) || '(3) Đẻ con và nuôi con bằng sữa mẹ' || chr(10) || '(4) Có răng', 'Hầu hết động vật lớp Thú có những đặc điểm: 1) Lông mao bao phủ khắp cơ thể; 3) Đẻ con và nuôi con bằng sữa mẹ; 4) Có răng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng nào sau đây là kết quả tác dụng của lực hút của Trái Đất?', 'Quả bưởi rụng trên cây xuống là kết quả tác dụng của lực hút của Trái Đất.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong các vật sau đây, vật nào không cần năng lượng điện khi hoạt động?', 'Bếp than hoạt động không cần năng lượng điện.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây, ma sát là có hại?', 'Giày đi mãi, đế bị mòn ma sát là có hại.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Bạch tuộc và ốc sên có nhiều đặc điểm khác nhau nhưng đều được xếp chung vào ngành Thân mềm vì cả hai đều có đặc điểm nào dưới đây?', 'Bạch tuộc và ốc sên có nhiều đặc điểm khác nhau nhưng đều được xếp chung vào ngành Thân mềm vì cả hai đều có đặc điểm có cơ thể mềm, không phân đốt.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Một vận động viên võ thuật có khối lượng 82 kg. Trọng lượng của người đó là', 'Một vận động viên võ thuật có khối lượng 82 kg. Trọng lượng của người đó là: P = 10m = 10.82 = 820N.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào dưới đây góp phần hạn chế sự suy giảm đa dạng sinh học?', 'Hoạt động góp phần hạn chế sự suy giảm đa dạng sinh học là: thành lập các khu bảo tồn thiên nhiên, khu dự trữ sinh quyển.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 4 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Thiết bị sau đây cần nhận năng lượng vào ở dạng nào để hoạt động?', 'Hình ảnh là tua bin gió, nhận năng lượng từ gió để hoạt động.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Da của loài cá nào sau đây có thể dùng làm túi, đóng giày?', 'Da của loài cá mập có thể dùng làm túi, đóng giày.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Năng lượng có thể truyền từ vật này sang vật khác thông qua:', 'Năng lượng có thể truyền từ vật này sang vật khác thông qua tác dụng lực, truyền nhiệt.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Giun đũa thường kí sinh ở vị trí nào trên cơ thể người?', 'Giun đũa thường kí sinh ở ruột non trên cơ thể người.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong các tình huống sau đây, tình huống nào có lực tác dụng mạnh nhất?', 'Năng lượng của gió làm các công trình xây dựng bị phá hủy có lực tác dụng mạnh nhất.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đại diện ruột khoang nào sau đây có cơ thể hình dù, thích nghi với lối sống bơi lội?', 'Đại diện ruột khoang là sứa có cơ thể hình dù, thích nghi với lối sống bơi lội.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Chúng ta nhận biết điện năng từ ổ cắm điện cung cấp cho máy tính thông qua biểu hiện:', 'Chúng ta nhận biết điện năng từ ổ cắm điện cung cấp cho máy tính thông qua biểu hiện: ánh sáng, âm thanh, nhiệt do máy tính phát ra.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây là biểu hiện của một vật có động năng?', 'Trường hợp là biểu hiện của một vật có động năng là: Cho vật chuyển động.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào dưới đây vật không có năng lượng?', 'Tảng đá nằm trên mặt đất không có năng lượng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Thế năng đàn hồi của vật là:', 'Thế năng đàn hồi của vật là năng lượng do vật bị biến dạng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Trong pin Mặt Trời có sự chuyển hóa', 'Trong pin Mặt Trời có sự chuyển hóa quang năng thành điện năng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm khí hậu ở nơi đất trống không có rừng là:', 'Đặc điểm khí hậu ở nơi đất trống không có rừng là: nhiệt độ cao, nắng gắt, nóng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vì sao nên sử dụng bóng đèn LED?', 'Nên sử dụng bóng đèn LED vì: Thời gian sử dụng lâu, tiêu thụ năng lượng điện ít, hiệu quả thắp sáng cao.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Vì sao khi mưa nhiều, trên mặt đất lại có nhiều giun đất?', 'Khi mưa nhiều, trên mặt đất lại có nhiều giun đất vì nước ngập cơ thể nên chúng bị ngạt thở.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Một người đàn ông đứng trên đỉnh núi thả rơi một viên đá xuống chân núi, lấy mốc thế năng ở chân núi. Trong quá trình rơi của viên đá đã có sự chuyển hóa năng lượng là:', 'Một người đàn ông đứng trên đỉnh núi thả rơi một viên đá xuống chân núi, lấy mốc thế năng ở chân núi. Trong quá trình rơi của viên đá đã có sự chuyển hóa năng lượng là thế năng chuyển hóa thành động năng.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 4)
    VALUES ('SINGLE_CHOICE', 'Lực tiếp xúc xuất hiện khi vật (hoặc đối tượng) gây ra lực …. với vật (hoặc đối tượng) chịu tác dụng của lực.', 'Lực tiếp xúc xuất hiện khi vật (hoặc đối tượng) gây ra lực có sự tiếp xúc với vật (hoặc đối tượng) chịu tác dụng của lực.', 'KHTN 6 - HK2 - Đề 4', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công toàn bộ 4 đề thi Cuối kì 2 KHTN 6 (112 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 5. LỚP 7 - GIỮA HỌC KỲ 1 (Nguồn: insert code lớp 7 giữa kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_30 DOUBLE PRECISION := ROUND((10.0 / 30.0)::numeric, 4); -- ~0.3333 điểm/câu cho đề 30 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 7
    SELECT id INTO v_class_id FROM grades WHERE grade = 7;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 7', 7, 'Chương trình Khoa học tự nhiên THCS Lớp 7', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 7', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 7 HỌC KỲ 1
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN7_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 7', 'KHTN7_HK1', 'Môn Khoa học Tự nhiên Lớp 7 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA KÌ 1 KHTN 7 - ĐỀ SỐ 1 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN7_01',
        'Đề thi giữa kì 1 KHTN 7 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây không đúng?', 'Khối lượng nguyên tử tập trung chủ yếu ở hạt nhân nguyên tử vì khối lượng electron ở lớp vỏ rất nhỏ không đáng kể.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có số electron bằng 8. Tổng số hạt trong X là 24. X có số neutron là', 'Trong nguyên tử trung hòa về điện, số proton bằng số electron: P = E = 8. Tổng số hạt trong nguyên tử là P + E + N = 24 hay 2E + N = 24. Suy ra N = 24 - 2 × 8 = 8.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong một nguyên tử có số proton bằng 9, số electron trong các lớp của vỏ nguyên tử, viết từ lớp trong ra lớp ngoài lần lượt là', 'Nguyên tử có số proton bằng 9 nên có 9 electron. Lớp thứ nhất trong cùng chứa tối đa 2 electron; 7 electron còn lại được điền tiếp vào lớp thứ hai.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hạt nhân một nguyên tử oxygen có 8 proton và 8 neutron. Khối lượng của nguyên tử oxygen xấp xỉ bằng', 'Khối lượng nguyên tử xấp xỉ bằng khối lượng hạt nhân: m ≈ 1 × P + 1 × N = 1 × 8 + 1 × 8 = 16 amu.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tên hóa học của những nguyên tố có kí hiệu S, Na, P, K lần lượt là', 'Kí hiệu hóa học tương ứng với các tên gọi là S (Sulfur), Na (Sodium), P (Phosphorus), K (Potassium).', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có số đơn vị điện tích hạt nhân là 20. Số neutron trong X bằng 20. Tên gọi của nguyên tố X là (Biết khối lượng nguyên tử theo amu của Ca = 40, S = 32, K = 39, O = 16)', 'Số proton bằng số đơn vị điện tích hạt nhân là 20. Khối lượng nguyên tử m_X ≈ P + N = 20 + 20 = 40 amu, do đó X là Calcium (Ca).', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho bảng sau: Phát biểu nào sau đây là không đúng?', 'Các nguyên tử thuộc cùng một nguyên tố hóa học phải có cùng số proton. X3 có số proton khác với X2 nên không thể thuộc cùng một nguyên tố hóa học.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X thuộc chu kì 3 và có 3 electron lớp ngoài cùng. X có tổng số hạt mang điện là', 'X thuộc chu kì 3 nên có 3 lớp electron. Số electron phân bố lần lượt là 2, 8, 3, suy ra tổng số electron là E = 13 và P = 13. Tổng số hạt mang điện là P + E = 13 + 13 = 26.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có tổng số hạt là 48, trong đó số hạt mang điện nhiều hơn số hạt không mang điện là 16 hạt. Vị trí của X trong bảng tuần hoàn là', 'Có 2P + N = 48 và 2P - N = 16. Giải hệ ta được 4P = 64 suy ra P = 16 (vỏ có 16 electron). Cấu trúc electron là 2, 8, 6 (3 lớp electron nên thuộc chu kì 3; 6 electron lớp ngoài cùng nên thuộc nhóm VIA).', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho các phát biểu sau:' || chr(10) || '(a) Nguyên tố hóa học là tập hợp những nguyên tử có cùng số proton trong hạt nhân.' || chr(10) || '(b) Nguyên tử trung hòa về điện.' || chr(10) || '(c) Kí hiệu hóa học của nguyên tố được biểu diễn bằng một hoặc hai chữ cái trong tên nguyên tố.' || chr(10) || '(d) Số thứ tự chu kì bằng số electron lớp ngoài cùng.' || chr(10) || 'Số phát biểu sai là', 'Phát biểu (d) sai vì số thứ tự chu kì bằng số lớp electron, không phải số electron lớp ngoài cùng. Ba phát biểu còn lại đều đúng.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tốc độ cho biết', 'Tốc độ là đại lượng đặc trưng cho sự nhanh hay chậm của chuyển động.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một người đi xe máy vi phạm giao thông chạy với tốc độ 60 km/h thì bị CSGT phát hiện và bắt đầu đuổi theo với tốc độ 90 km/h, khi đó xe máy đã cách trạm kiểm tra 1km. Hỏi sau bao lâu thì CSGT đuổi kịp người đi xe máy?', 'Hiệu vận tốc giữa CSGT và xe máy là 90 - 60 = 30 km/h. Thời gian đuổi kịp là t = s / v_hiệu = 1 / 30 giờ = 2 phút.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ưu điểm của dụng cụ đo tốc độ bằng đồng hồ hiện số và cổng quang điện là:', 'Thiết bị sử dụng cảm biến ánh sáng để tự động kích hoạt bộ đếm thời gian, loại bỏ hoàn toàn độ trễ do phản xạ của con người nên mang lại độ chính xác rất cao.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trên đoạn đường cắm biển hạn chế tốc độ 50km/h. CSGT dùng súng bắn tốc độ một ô tô đang di chuyển. Ở lần bắn 1, xác định được khoảng cách từ vị trí bắn đến ô tô là 50m. Ở lần bắn 2, khoảng cách đó là 65m. Biết hai lần bắn cách nhau 0,8s. Hỏi ô tô có đang chạy quá tốc độ cho phép không? Nếu có thì vượt bao nhiêu km/h so với tốc độ cho phép?', 'Vận tốc của xe là v = (65 - 50) / 0,8 = 18,75 m/s = 67,5 km/h. Ô tô đã chạy quá tốc độ và vượt: 67,5 - 50 = 17,5 km/h.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Bảng dưới đây mô tả chuyển động của một ô tô trong 4h. Hình vẽ nào sau đây biểu diễn đúng đồ thị quãng đường – thời gian của chuyển động trên?', 'Xác định các điểm tọa độ (thời gian; quãng đường) từ bảng số liệu rồi nối các điểm lại, ta thu được đồ thị tương ứng ở phương án D.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho đồ thị quãng đường – thời gian của vật dưới đây. Mô tả chuyển động cho đồ thị này là:', 'Đồ thị là đường thẳng nằm ngang song song với trục thời gian, thể hiện quãng đường không thay đổi theo thời gian, nghĩa là vật đang đứng yên.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Các đồ thị (I), (II) biểu diễn chuyển động của xe (I) và xe (II). Dựa vào đồ thị cho biết nhận xét nào sau đây không đúng?', 'Trong 20 giây đầu tiên, đồ thị xe (I) nằm trên trục thời gian (s = 0), tức xe (I) chưa chuyển động nên tốc độ bằng 0 m/s. Phát biểu B sai.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây không đúng khi nói về khoảng cách an toàn giữa các xe đang lưu thông trên đường?', 'Khi trời mưa đường trơn trượt làm giảm độ ma sát bám đường, người điều khiển phương tiện cần phải tăng khoảng cách an toàn để đảm bảo xử lý kịp thời.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một con báo châu Phi phóng đến con mồi đang đứng yên cách nó 280m với tốc độ trung bình 70km/h mất bao lâu?', 'Đổi quãng đường s = 280 m = 0,28 km. Thời gian t = s / v = 0,28 / 70 = 0,004 h = 14,4 s.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Một người đi xe đạp xuống một cái dốc dài 200m hết 50s. Sau đó xe đi tiếp một quãng đường nằm ngang dài 100m trong 20s. Tính tốc độ trung bình của người đó trên cả hai đoạn đường.', 'Tốc độ trung bình trên toàn bộ quãng đường là: v_tb = (s1 + s2) / (t1 + t2) = (200 + 100) / (50 + 20) = 300 / 70 ≈ 4,3 m/s.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trao đổi chất và chuyển hóa năng lượng ở sinh vật gồm các quá trình?', 'Trao đổi chất và chuyển hóa năng lượng bao gồm quá trình trao đổi chất giữa cơ thể với môi trường ngoài và quá trình chuyển hoá các chất diễn ra bên trong tế bào.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Chọn từ thích hợp để hoàn thiện sơ đồ sau. Cơ thể người thải ra những gì trong quá trình trao đổi chất?', 'Cơ thể người thu nhận khí oxygen, chất dinh dưỡng, nước và đồng thời bài tiết ra khí carbon dioxide, năng lượng nhiệt cùng các chất cặn bã/chất thải.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Quá trình phân giải đường glucose trong hô hấp tế bào tạo ra năng lượng được tích trữ trong?', 'Năng lượng giải phóng từ phân giải glucose trong hô hấp tế bào được tích lũy chủ yếu dưới dạng liên kết giàu năng lượng trong phân tử ATP.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hô hấp tế bào có vai trò như thế nào trong hoạt động sống của sinh vật?', 'Hô hấp tế bào có vai trò cốt lõi là giải phóng và cung cấp nguồn năng lượng (ATP) cho mọi hoạt động sống của cơ thể sinh vật.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tại ti thể của tế bào, các chất hữu cơ tổng hợp được từ quá trình quang hợp hoặc từ', 'Trong ti thể, các chất hữu cơ lấy từ thức ăn được oxy hóa và phân giải giải phóng carbon dioxide cùng năng lượng phục vụ tế bào.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nhận định nào dưới đây là đúng khi bàn về đặc điểm của lá cây giúp là cây nhận được nhiều ánh sáng?', 'Phiến lá có dạng bản dẹt, mỏng và diện tích bề mặt lớn giúp phiến lá hấp thụ được tối đa lượng ánh sáng chiếu vào.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Với cây xanh, quang hợp có những vai trò nào sau đây?' || chr(10) || '(1) Cung cấp năng lượng cho các hoạt động sống của cây.' || chr(10) || '(2) Điều hòa không khí.' || chr(10) || '(3) Tạo chất hữu cơ và chất khí.' || chr(10) || '(4) Giữ ấm cho cây.', 'Trực tiếp đối với bản thân cây xanh, quang hợp tạo ra các chất hữu cơ và khí oxygen, đồng thời tích lũy năng lượng nuôi dưỡng các cơ quan của cây.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Quang hợp không có vai trò nào sau đây?', 'Quá trình oxi hóa các hợp chất hữu cơ để giải phóng năng lượng là vai trò của hô hấp tế bào, không phải quá trình quang hợp.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Quá trình quang hợp sẽ bị giảm hoặc ngừng hẳn khi nhiệt độ', 'Quang hợp diễn ra hiệu quả trong khoảng 25°C - 35°C; khi nhiệt độ hạ quá thấp (dưới 10°C) hoặc tăng quá cao (trên 40°C) đều làm suy giảm hoặc ức chế hoàn toàn quang hợp.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi gieo hạt trồng rau cải, sau một tuần, cây cải đã lớn và chen chúc nhau, người ta nhổ bớt những cây cải mọc gần nhau. Ý nghĩa của việc làm này là gì?', 'Tỉa bớt cây giúp duy trì khoảng cách và mật độ thích hợp để từng cá thể cây đón đủ ánh sáng, hút đủ nước và chất dinh dưỡng phát triển thuận lợi.', 'KHTN 7 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI GIỮA KÌ 1 KHTN 7 - ĐỀ SỐ 2 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN7_02',
        'Đề thi giữa kì 1 KHTN 7 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sai khi nói về neutron?', 'Neutron nằm ở trong hạt nhân nguyên tử, kí hiệu n và không mang điện tích. Do đó phương án C sai.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có số electron là 9. Số đơn vị điện tích hạt nhân của X là', 'Nguyên tử trung hòa về điện nên số proton bằng số electron = 9. Số đơn vị điện tích hạt nhân bằng số proton nên bằng 9.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho mô hình cấu tạo nguyên tử của nguyên tố nitrogen. Số lớp electron và số electron lớp ngoài cùng của nitrogen lần lượt là', 'Từ mô hình nguyên tử suy ra nitrogen (N) có 2 lớp electron và có 5 electron ở lớp ngoài cùng.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hạt nhân một nguyên tử sodium có 11 proton và 12 neutron. Khối lượng của một nguyên tử sodium xấp xỉ bằng', 'Khối lượng nguyên tử tập trung chủ yếu ở hạt nhân, xấp xỉ bằng m_P + m_N ≈ 1 × 11 + 1 × 12 = 23 amu.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Oxygen là nguyên tố hóa học phổ biến trong không khí. Trong hạt nhân nguyên tử có 8 proton. Số electron trong các lớp của vỏ nguyên tử oxygen, viết từ lớp trong ra lớp ngoài lần lượt là', 'Nguyên tử có số proton bằng 8 nên có 8 electron. Lớp thứ nhất trong cùng chứa tối đa 2 electron; 6 electron còn lại được xếp vào lớp thứ hai. Thứ tự từ trong ra ngoài là 2, 6.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử carbon, helium, phosphorus, potassium có kí hiệu hóa học lần lượt là:', 'Kí hiệu hóa học tương ứng của carbon là C, helium là He, phosphorus là P và potassium là K.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có số đơn vị điện tích hạt nhân là 20. Số neutron trong X bằng 20. Tên gọi của nguyên tố X là (Biết khối lượng nguyên tử theo amu của Al = 27, S = 32, K = 39, Ca = 40)', 'Số proton = số đơn vị điện tích hạt nhân = 20. Khối lượng nguyên tử m_X ≈ P + N = 20 + 20 = 40 amu, do đó X là calcium.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố M có 2 lớp electron và có 7 electron ở lớp ngoài cùng. Vị trí của M và tính chất của M trong bảng tuần hoàn là', 'M có 2 lớp electron nên thuộc chu kì 2. M có 7 electron lớp ngoài cùng nên thuộc nhóm VIIA và là phi kim. Tổng số electron là 2 + 7 = 9 nên M ở ô thứ 9.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố X có số hiệu nguyên tử là 10. Phát biểu sau đây là đúng?', 'Số hiệu nguyên tử là 10 nên X có 10 electron. Cấu hình gồm 2 lớp (2, 8), lớp ngoài cùng có 8 electron bão hòa nên X thuộc nhóm VIIIA và là một khí hiếm (neon).', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có tổng số hạt là 40. Tổng số hạt mang điện nhiều hơn tổng số hạt không mang điện là 12 hạt. X có số đơn vị điện tích hạt nhân là', 'Ta có hệ phương trình: 2P + N = 40 và 2P - N = 12. Cộng vế theo vế được 4P = 52 suy ra P = 13. Vậy số đơn vị điện tích hạt nhân của X là 13.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một xe máy chạy qua chiếc cầu dài 250m hết 20 giây. Hỏi với tốc độ đó xe máy đi quãng đường dài 1,2 km hết bao nhiêu thời gian?', 'Tốc độ của xe máy là v = s / t = 250 / 20 = 12,5 m/s. Đổi 1,2 km = 1200 m. Thời gian cần đi là t = s / v = 1200 / 12,5 = 96 s.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Công thức nào xác định tốc độ của chuyển động của một vật thể?', 'Tốc độ chuyển động của một vật được tính bằng quãng đường vật đi được chia cho thời gian chuyển động: v = s / t.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Một người tập luyện chạy bộ xuất phát lúc 5 giờ 05 phút 01 giây theo hướng từ nhà đến cột đèn và tới chân cột đèn lúc 5 giờ 09 phút 05 giây. Ngay sau đó, từ cột đèn người này chạy theo hướng ngược lại và chạy ngang qua cây bàng bên vệ đường lúc 5 giờ 19 phút 25 giây. Tính tốc độ chạy của người này.', 'Tổng thời gian chạy là t = 5h 19min 25s - 5h 05min 01s = 14min 24s = 864 s. Tổng quãng đường chạy là s = 400 + 1000 = 1400 m. Tốc độ trung bình là v = s / t = 1400 / 864 ≈ 1,62 m/s.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong một thí nghiệm đo tốc độ của xe đồ chơi chạy pin, khi cho xe chạy qua hai cổng quang điện cách nhau 20cm thì thời gian xe chạy qua hai cổng quang điện được hiển thị trên đồng hồ là 1,02s. Tính tốc độ chuyển động của xe.', 'Tốc độ chuyển động của xe là v = s / t = 20 / 1,02 ≈ 19,6 cm/s.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Từ đồ thị quãng đường – thời gian, ta không thể xác định được thông tin nào sau đây?', 'Đồ thị quãng đường – thời gian cho biết thời gian và quãng đường đi được, từ đó tính được tốc độ chuyển động nhưng không cho biết hướng cụ thể trong không gian của chuyển động.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho đồ thị quãng đường – thời gian của vật dưới đây. Mô tả chuyển động cho đồ thị này là:', 'Đồ thị biểu diễn quãng đường tăng đều theo thời gian dạng đường thẳng dốc lên xuất phát từ gốc tọa độ, chứng tỏ vật chuyển động với tốc độ không đổi.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Các đồ thị (I), (II) biểu diễn chuyển động của xe (I) và xe (II). Nhận xét không đúng là:', 'Tốc độ của xe I là v1 = 60 / 1 = 60 km/h; tốc độ của xe II là v2 = 60 / 2 = 30 km/h. Do v1 > v2 nên xe I chạy nhanh hơn xe II, nhận xét C sai.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho quy định về khoảng cách an toàn theo Luật Giao thông đường bộ Việt Nam và hình vẽ dưới đây. Nhận xét đúng là:', 'Với tốc độ 60 km/h quy định khoảng cách an toàn tối thiểu là 35m. Với khoảng cách thực tế lớn hơn, ô tô hoàn toàn có thể an toàn tránh va chạm. Do đó cả A và C đều đúng.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Một chú rùa chuyển động với tốc độ không đổi 2,51cm/s, trong lúc chú thỏ đang dừng lại và thong thả gặm cà rốt. Kể từ lúc thỏ dừng lại, cần thời gian bao lâu để rùa có thể đi xa thỏ 140 cm?', 'Thời gian để rùa di chuyển được khoảng cách 140 cm là: t = s / v = 140 / 2,51 ≈ 55,8 s.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Ốc sên, Bọ ngựa, Dế mèn cùng tham gia cuộc thi đua tốc độ xem ai nhanh hơn. Cả ba cùng di chuyển một quãng đường 2m trên một bờ tường. Ốc sên thận trọng, di chuyển 4 cm mất 20s. Bọ ngựa sải chân, cứ 15s thì di chuyển được 60cm. Dế mèn nhẩn nha, cứ 6s thì đi được 18cm. Hãy sắp xếp theo thứ bậc nhanh nhất, chậm nhất trong cuộc thi.', 'Tốc độ của Ốc sên là 4 / 20 = 0,2 cm/s; Bọ ngựa là 60 / 15 = 4 cm/s; Dế mèn là 18 / 6 = 3 cm/s. Sắp xếp từ nhanh nhất đến chậm nhất: Bọ ngựa > Dế mèn > Ốc sên.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vì sao trong khẩu phần ăn, chúng ta nên chú trọng đến rau và hoa quả tươi?', 'Rau và quả tươi giàu chất xơ giúp tiêu hóa dễ dàng (ý A) và giàu vitamin, khoáng chất hỗ trợ chuyển hóa chất và năng lượng (ý C). Do đó phương án D đúng.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Em hãy cho biết trao đổi chất ở động vật gồm những hoạt động nào sau đây?' || chr(10) || '(1) Lấy thức ăn.' || chr(10) || '(2) Nghiền nhỏ thức ăn.' || chr(10) || '(3) Biến đổi thức ăn.' || chr(10) || '(4) Thải ra.' || chr(10) || '(5) Tăng nhiệt độ.', 'Trao đổi chất ở động vật bao gồm quá trình thu nhận chất dinh dưỡng từ môi trường (lấy thức ăn), biến đổi hóa học các chất và bài tiết (thải ra). Các hoạt động gồm: (1), (3), (4).', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình quang hợp góp phần làm giảm lượng khí nào sau đây trong khí quyển?', 'Trong quá trình quang hợp, cây xanh hấp thụ carbon dioxide (CO2) từ khí quyển và thải ra khí oxygen (O2), giúp làm giảm lượng CO2 trong không khí.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Những sinh vật nào sau đây có khả năng quang hợp trong điều kiện có ánh sáng ?' || chr(10) || '(1) Tảo lục.' || chr(10) || '(2) Thực vật.' || chr(10) || '(3) Ruột khoang.' || chr(10) || '(4) Nấm.' || chr(10) || '(5) Trùng roi xanh.', 'Sinh vật có khả năng quang hợp phải chứa diệp lục. Trong danh sách gồm có tảo lục, thực vật và trùng roi xanh (khi có ánh sáng). Nấm và ruột khoang không thể quang hợp.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các yếu tố kể sau đây, yếu tố nào ảnh hưởng đến quá trình quang hợp?', 'Quá trình quang hợp chịu ảnh hưởng của nhiều yếu tố môi trường bao gồm: ánh sáng, nhiệt độ, nước, nồng độ CO2 và các nguyên tố khoáng.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình quang hợp sẽ bị giảm hoặc ngừng hẳn khi nhiệt độ (Câu 26)', 'Nhiệt độ thích hợp cho quang hợp ở đa số thực vật là 25°C - 35°C. Khi nhiệt độ quá thấp (dưới 10°C) hoặc quá cao (trên 40°C), quang hợp sẽ suy giảm hoặc ngừng hẳn.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Bạn Bảo Lan tiến hành thí nghiệm như sau: Lấy vài cành rong đuôi chó cho vào phễu thủy tinh trong suốt úp ngược và đặt trong cốc thủy tinh đựng đầy nước. Lấy ống nghiệm chứa đầy nước, dùng ngón tay cái bịt vào đầu ống nghiệm rồi úp lên cuống phễu thủy tinh. Chiếu ánh sáng đèn vào cốc thủy tinh chứa ống nghiệm khoảng 15 - 20 phút. Thay đổi cường độ chiếu sáng bằng cách thay đổi khoảng cách giữa đèn và cành rong. Cành rong đuôi chó quang hợp giải phóng khí oxygen tạo bọt khí. Khi khoảng cách đèn càng xa, số lượng bọt khí càng ít. Em hãy cho biết, thí nghiệm bạn Bảo Lan làm nhằm chứng minh ảnh hưởng của nhân tố nào đến quá trình quang hợp của cây?', 'Việc thay đổi khoảng cách của nguồn sáng làm thay đổi cường độ ánh sáng chiếu tới cành rong, từ đó làm thay đổi tốc độ giải phóng bọt khí oxygen.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Về mặt năng lượng, hô hấp tế bào và quang hợp có mối quan hệ với nhau như thế nào?', 'Quang hợp tích lũy quang năng từ Mặt Trời thành hóa năng trong glucose; sau đó hô hấp tế bào phân giải glucose để chuyển hóa năng lượng đó thành ATP cung cấp cho hoạt động sống.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quang hợp của cây sẽ như thế nào khi tế bào lá cây mất nước?', 'Khi tế bào lá mất nước, khí khổng sẽ đóng lại để hạn chế thoát hơi nước, khiến lượng khí CO2 khuếch tán vào lá giảm mạnh, làm quang hợp bị ngưng trệ hoặc gặp khó khăn.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nếu hàm lượng carbon dioxide tăng lên thì quang hợp tăng nhưng', 'Khi nồng độ CO2 tăng lên thì cường độ quang hợp tăng, tuy nhiên nếu nồng độ CO2 tăng quá cao sẽ gây độc tế bào và ức chế làm giảm quá trình quang hợp.', 'KHTN 7 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 Giữa kì 1 KHTN Lớp 7 (60 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 6. LỚP 7 - CUỐI HỌC KỲ 1 (Nguồn: insert code lớp 7 kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_30 DOUBLE PRECISION := ROUND((10.0 / 30.0)::numeric, 4); -- ~0.3333 điểm/câu cho đề 30 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 7
    SELECT id INTO v_class_id FROM grades WHERE grade = 7;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 7', 7, 'Chương trình Khoa học tự nhiên THCS Lớp 7', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 7', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 7 HỌC KỲ 1
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN7_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 7', 'KHTN7_HK1', 'Môn Khoa học Tự nhiên Lớp 7 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI HỌC KÌ 1 KHTN 7 - ĐỀ SỐ 1 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN7_01',
        'Đề thi học kì 1 KHTN 7 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố hóa học là tập hợp những nguyên tử cùng loại có cùng số hạt nào trong hạt nhân?', 'Nguyên tố hóa học là tập hợp những nguyên tử cùng loại có cùng số proton trong hạt nhân.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Bảng tuần hoàn các nguyên tố hóa học được sắp xếp theo', 'Bảng tuần hoàn các nguyên tố hóa học được sắp xếp theo chiều tăng dần điện tích hạt nhân của nguyên tử.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử nitrogen có số electron là 7. Số đơn vị điện tích hạt nhân của nitrogen là', 'Nguyên tử trung hòa về điện nên số electron bằng số proton (E = P = 7). Số đơn vị điện tích hạt nhân bằng số proton nên bằng 7.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho mô hình cấu tạo của nguyên tử carbon. Phát biểu nào sau đây là sai?', 'Hạt nhân nguyên tử được cấu tạo bởi proton và neutron, không chứa electron. Hạt nhân nguyên tử carbon có 6 proton. Do đó phát biểu B sai.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nitrogen là nguyên tố hóa học phổ biến trong không khí. Trong hạt nhân nguyên tử có 7 proton. Số electron trong các lớp của vỏ nguyên tử nitrogen, viết từ lớp trong ra lớp ngoài lần lượt là', 'Nguyên tử nitrogen có 7 proton nên có 7 electron. Lớp thứ nhất trong cùng chứa tối đa 2 electron; 5 electron còn lại được xếp vào lớp thứ hai. Thứ tự từ trong ra ngoài lần lượt là 2, 5.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hạt nhân một nguyên tử fluorine có 9 proton và 10 neutron. Khối lượng của nguyên tử fluorine xấp xỉ bằng', 'Khối lượng nguyên tử tập trung chủ yếu ở hạt nhân: m ≈ m_P + m_N ≈ 1 × 9 + 1 × 10 = 19 amu.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử hydrogen, nitrogen, fluorine, potassium có kí hiệu hóa học lần lượt là:', 'Kí hiệu hóa học tương ứng lần lượt là H (hydrogen), N (nitrogen), F (fluorine), K (potassium).', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho bảng sau: Phát biểu nào sau đây là đúng?', 'Nguyên tố hóa học là tập hợp các nguyên tử có cùng số proton. Do X1 và X2 có cùng số proton nên thuộc cùng một nguyên tố hóa học.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tổng số hạt trong nguyên tử M là 18. Nguyên tử M có tổng số hạt mang điện gấp đôi số hạt không mang điện. Vị trí và tính chất cơ bản của nguyên tố M trong bảng tuần hoàn là', 'Có 2P + N = 18 và 2P = 2N (P = N). Suy ra 3P = 18 hay P = 6. M có 6 electron được phân bố thành 2 lớp (2, 4): có 2 lớp electron nên thuộc chu kì 2; có 4 electron lớp ngoài cùng nên thuộc nhóm IVA và là phi kim.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố X thuộc nhóm IIA, chu kì 3. Điện tích hạt nhân của nguyên tố X là', 'X thuộc chu kì 3 nên có 3 lớp electron; thuộc nhóm IIA nên có 2 electron lớp ngoài cùng. Cấu hình electron là 2, 8, 2, suy ra X có 12 electron (12 proton). Do đó điện tích hạt nhân của X là +12.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một con chuột túi chạy 20 phút với tốc độ không đổi thì chạy được quãng đường dài 16,8 km. Tốc độ của con chuột túi là', 'Đổi thời gian t = 20 phút = 1/3 giờ. Tốc độ chuyển động của chuột túi là v = s / t = 16,8 / (1/3) = 50,4 km/h.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hùng đạp xe lên dốc dài 150 m với tốc độ 2 m/s, sau đó xuống dốc dài 120 m hết 30 s. Hỏi tốc độ trung bình của Hùng trên cả đoạn đường dốc?', 'Thời gian lên dốc là t1 = s1 / v1 = 150 / 2 = 75 s. Tốc độ trung bình trên toàn bộ quãng đường dốc là: v_tb = (s1 + s2) / (t1 + t2) = (150 + 120) / (75 + 30) = 270 / 105 ≈ 2,57 m/s.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Để đo tốc độ của một người chạy cự li ngắn, ta cần những dụng cụ đo nào?', 'Để xác định tốc độ chạy cự li ngắn trên đường chạy ngoài trời, ta sử dụng thước cuộn để đo chiều dài quãng đường và đồng hồ bấm giây để đo thời gian chạy.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình dưới đây là đồ thị quãng đường – thời gian của một vật chuyển động. Dựa vào hình vẽ, hãy chọn các phát biểu đúng trong các phát biểu sau:' || chr(10) || 'a) Tốc độ của vật là 2 m/s.' || chr(10) || 'b) Sau 2 s, vật đi được 4 m.' || chr(10) || 'c) Từ giây thứ 4 đến giây thứ 6, vật đi được 12 m.' || chr(10) || 'd) Thời gian để vật đi được 8 m là 4 s.', 'Từ đồ thị, sau 6 s vật đi được 12 m nên tốc độ là v = 12 / 6 = 2 m/s (a đúng); sau 2 s vật đi được 4 m (b đúng); từ giây thứ 4 (8 m) đến giây thứ 6 (12 m) vật đi được 12 - 8 = 4 m (c sai); thời gian để đi 8 m là t = 8 / 2 = 4 s (d đúng). Vậy a, b, d là các phát biểu đúng.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình dưới đây biểu diễn đồ thị quãng đường – thời gian của một vật chuyển động trong khoảng thời gian 8s. Tốc độ của vật là:', 'Dựa vào đồ thị, quãng đường vật đi được tương ứng sau 8 giây là s = 20 m. Tốc độ của vật là v = s / t = 20 / 8 = 2,5 m/s.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Xe buýt trên đường không có giải phân cách cứng với tốc độ v nào sau đây là tuân thủ quy định về tốc độ tối đa của Hình 11.1?', 'Theo quy định tốc độ tối đa của xe cơ giới đường bộ, xe buýt lưu thông trên đường hai chiều không có dải phân cách cứng chỉ được chạy tối đa dưới 60 km/h (50 km/h < v < 60 km/h).', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các dàn loa thường có các loa thùng và ta thường nghe thấy âm thanh phát ra từ cái loa đó. Bộ phận nào sau đây của loa là nguồn âm?', 'Nguồn âm là vật phát ra âm khi dao động; ở loa thùng, màng loa dao động tạo nên sóng âm truyền trong không khí.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ta nghe được tiếng hát của ca sĩ trên tivi. Vậy đâu là nguồn âm?', 'Bộ phận trực tiếp dao động phát ra âm thanh truyền đến tai người nghe tại nơi xem tivi là màng loa bên trong tivi.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Âm thanh không thể truyền trong', 'Sóng âm cần môi trường vật chất mang hạt (rắn, lỏng, khí) để lan truyền dao động, do đó không thể truyền qua môi trường chân không.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Giả sử trong không gian vũ trụ thuộc hệ Mặt Trời có hai thiên thạch va chạm với nhau thì ở trên Trái Đất ta có nghe thấy âm thanh của vụ nổ này không? Tại sao?', 'Khoảng không gian vũ trụ giữa các thiên thể là môi trường chân không, mà âm thanh không thể lan truyền trong chân không nên ta không thể nghe thấy âm thanh vụ nổ trên Trái Đất.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất hữu cơ được tổng hợp ở thực vật thông qua quá trình nào?', 'Quá trình quang hợp sử dụng năng lượng ánh sáng mặt trời để biến đổi CO2 và H2O thành các hợp chất hữu cơ (glucose, tinh bột) ở cây xanh.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Bào quan thực hiện chức năng quang hợp ở thực vật là:', 'Bào quan thực hiện chức năng quang hợp ở tế bào thực vật là lục lạp (chứa sắc tố diệp lục hấp thu năng lượng ánh sáng).', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hô hấp tế bào gồm', 'Hô hấp tế bào là chuỗi các phản ứng hóa sinh bẻ gãy các liên kết trong phân tử chất dinh dưỡng hữu cơ nhằm giải phóng và sản sinh năng lượng (ATP) phục vụ tế bào.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ở động vật khi tiếp xúc với môi trường có nồng độ carbon dioxide cao thì', 'Khi nồng độ CO2 ngoài môi trường quá cao, CO2 cạnh tranh liên kết với hemoglobin trong hồng cầu làm giảm lượng O2 vận chuyển tới mô, gây ức chế hô hấp tế bào và có nguy cơ dẫn đến tử vong.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ý kiến nào sau đây là không đúng khi nói về vai trò của nước trong quá trình quang hợp?', 'Vì các nhận định A, B, C đều là những vai trò thực tế của nước đối với quang hợp và sự đóng mở khí khổng, nên ý kiến cho rằng "Tất cả các nhận định trên đều sai" là phát biểu không đúng.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hãy cho biết những nguyên nhân dẫn đến việc ô nhiễm thực phẩm.' || chr(10) || '(1) Sử dụng phân bón hữu cơ cho cây lương thực.' || chr(10) || '(2) Lạm dụng thuốc bảo vệ thực vật.' || chr(10) || '(3) Khử khuẩn chuồng trại sau mỗi vụ chăn nuôi.' || chr(10) || '(4) Ao, chuồng bị ô nhiễm.' || chr(10) || '(5) Thực phẩm bị tiêm, tẩm hóa chất.' || chr(10) || '(6) Ăn chín, uống sôi.' || chr(10) || '(7) Chế biên thực phẩm không đảm bảo vệ sinh.' || chr(10) || '(8) Điều kiện bảo quản thực phẩm không phù hợp.', 'Những nguyên nhân làm thực phẩm nhiễm bẩn, nhiễm độc gồm: lạm dụng hóa chất/thuốc BVTV (2), môi trường nuôi thả ô nhiễm (4), tẩm ướp hóa chất (5), mất vệ sinh khâu chế biến (7) và bảo quản sai quy cách (8).', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây không được dùng làm nguyên liệu cho quá trình chuyển hoá các chất trong tế bào?', 'Nhiệt năng là dạng năng lượng phát sinh hoặc trao đổi, không phải là chất phản ứng/nguyên liệu tham gia vào các phản ứng hóa sinh chuyển hóa chất trong tế bào.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vì sao mở nắp mang cá có thể biết cá còn tươi hay không?', 'Cá còn tươi thì hệ tuần hoàn và trao đổi khí vừa diễn ra giúp máu ở các lá mang giàu oxygen nên có màu đỏ tươi; cá ươn thì mang chuyển sang đỏ sẫm hoặc nhợt nhạt.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thực vật có thể lấy chất dinh dưỡng từ những nguồn nào sau đây?', 'Cây xanh tự dưỡng lấy các chất khoáng vô cơ hòa tan trong đất (C, H, O, N, P,...) qua hệ rễ để tổng hợp nên các chất hữu cơ nuôi cơ thể.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đâu không phải là vai trò của nước?', 'Chất xúc tác sinh học cho các phản ứng trong cơ thể là các enzyme, nước đóng vai trò dung môi, môi trường phản ứng và thành phần cấu trúc chứ không phải chất xúc tác.', 'KHTN 7 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI HỌC KÌ 1 KHTN 7 - ĐỀ SỐ 2 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN7_02',
        'Đề thi học kì 1 KHTN 7 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử được cấu tạo bởi hai thành phần chính là', 'Nguyên tử gồm hạt nhân nguyên tử và vỏ nguyên tử.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho mô hình nguyên tử Aluminium. Số electron, proton của Aluminium lần lượt là:', 'Đếm số electron xung quanh hạt nhân ta được số electron = 13. Do nguyên tử trung hòa về điện nên số proton = số electron = 13.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong một nguyên tử có số proton bằng 5, số electron trong các lớp của vỏ nguyên tử, viết từ lớp trong ra lớp ngoài lần lượt là', 'Nguyên tử có số proton bằng 5 nên có 5 electron. Lớp thứ nhất trong cùng chứa tối đa 2 electron; 3 electron còn lại được xếp vào lớp thứ hai. Do đó thứ tự là 2, 3.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một nguyên tố hóa học được đặc trưng bởi', 'Một nguyên tố hóa học là tập hợp các nguyên tử cùng loại có cùng số proton trong hạt nhân, do đó được đặc trưng bởi số proton.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tên của những nguyên tố nào có kí hiệu lần lượt là O, Cl, Al, Ca?', 'O, Cl, Al, Ca lần lượt là kí hiệu hóa học của các nguyên tố oxygen, chlorine, aluminium, calcium.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho bảng sau: Phát biểu nào sau đây là sai?', 'X và Z có số proton khác nhau (P_X = 6, P_Z = 8) nên không thể thuộc cùng một nguyên tố hóa học. Do đó phát biểu A sai.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử của nguyên tố X có số đơn vị điện tích hạt nhân là 16. Số neutron trong X bằng 16. Tên gọi của nguyên tố X là (Biết khối lượng nguyên tử theo amu của Ca = 40, S = 32, K = 39, O = 16)', 'Số proton = số đơn vị điện tích hạt nhân = 16. Khối lượng nguyên tử m_X ≈ P + N = 16 + 16 = 32 amu, do đó X là Sulfur (S).', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố X (Z = 8) là nguyên tố cần thiết cho quá trình hô hấp của sinh vật, nếu thiếu nguyên tố này sự cháy không thể xảy ra. Kí hiệu hóa học, vị trí của X trong bảng tuần hoàn là', 'Nguyên tố X là Oxygen (kí hiệu O). Z = 8 nên có 8 electron, phân bố thành 2 lớp (2, 6): có 2 lớp electron nên thuộc chu kì 2; có 6 electron lớp ngoài cùng nên thuộc nhóm VIA.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây là sai?', 'Các electron được sắp xếp lần lượt vào các lớp theo chiều từ gần hạt nhân ra ngoài vỏ nguyên tử, không phải từ ngoài vỏ vào hạt nhân.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hạt nhân nguyên tử nguyên tố A có 24 hạt, trong đó số hạt không mang điện là 12. Vị trí và tính chất của A trong bảng tuần hoàn là', 'Hạt nhân có P + N = 24 mà N = 12 nên P = 12 (nguyên tử có 12 electron). Cấu trúc electron là 2, 8, 2 (3 lớp electron nên thuộc chu kì 3; 2 electron lớp ngoài cùng nên thuộc nhóm IIA và là kim loại).', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một xà lan đi dọc bờ sông trên quãng đường AB với tốc độ 12km/h trong 10 phút. Quãng đường AB là:', 'Đổi 10 phút = 1/6 giờ. Quãng đường AB đi được là: s = v × t = 12 × (1/6) = 2 km.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một con thỏ chạy một quãng đường 1,5km hết 2 phút và một con chuột túi chạy với vận tốc 14m/s. Con nào chạy nhanh hơn?', 'Đổi 1,5 km = 1500 m; 2 phút = 120 s. Vận tốc của thỏ là v = 1500 / 120 = 12,5 m/s. Vì 14 m/s > 12,5 m/s nên chuột túi chạy nhanh hơn thỏ.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong phòng thí nghiệm, người ta thường sử dụng những dụng cụ đo nào để đo tốc độ của các vật chuyển động nhanh và có kích thước nhỏ?', 'Để đo tốc độ của các vật chuyển động nhanh và kích thước nhỏ trong phòng thí nghiệm, người ta dùng thước cùng với đồng hồ đo thời gian hiện số kết nối cổng quang điện để đảm bảo độ chuẩn xác cao.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình vẽ biểu diễn đồ thị quãng đường – thời gian của người đi bộ. Từ đồ thị xác định tốc độ đi bộ của người đó.', 'Dựa vào đồ thị quãng đường – thời gian, xác định giá trị quãng đường và thời gian tương ứng để tính tốc độ: v = s / t = 1,4 m/s.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hình biểu diễn đồ thị quãng đường – thời gian của một xe buýt xuất phát từ trạm A, chạy theo tuyến cố định đến trạm B, cách A 80km. Sau bao lâu kể từ lúc xuất phát xe buýt đi đến trạm B:', 'Dóng tọa độ quãng đường s = 80 km sang trục thời gian tương ứng, ta xác định được thời gian xe buýt đến trạm B là sau 2,0 giờ kể từ lúc xuất phát.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Hãy dùng quy tắc “3 giây” để xác định khoảng cách an toàn của xe ô tô chạy với tốc độ 70 km/h. Khoảng cách tính được này có phù hợp với quy định về tốc độ tối đa trong Bảng 11.1 không?', 'Đổi tốc độ: 70 km/h = 70 / 3,6 ≈ 19,44 m/s. Khoảng cách an toàn theo quy tắc 3 giây là s = 19,44 × 3 ≈ 58,3 m. Khoảng cách này lớn hơn mức tối thiểu 35 m quy định tại bảng 11.1 nên hoàn toàn phù hợp.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vật phát ra âm trong trường hợp nào dưới đây?', 'Mọi vật phát ra âm thanh đều do các bộ phận của vật đó dao động tạo nên.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi trời mưa dông, ta thường nghe thấy tiếng sấm. Vậy vật nào đã dao động phát ra tiếng sấm?', 'Nhiệt độ cực lớn của tia sét làm không khí xung quanh dãn nở đột ngột và co lại nhanh chóng, sự dao động mạnh mẽ của khối không khí này phát ra tiếng sấm.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây chứng tỏ sóng âm truyền được trong chất rắn?', 'Hiện tượng áp tai vào mặt bàn gỗ và nghe được tiếng gõ nhẹ từ đầu bàn đối diện chứng minh âm thanh lan truyền qua chất rắn (gỗ).', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Âm thanh không thể truyền trong chân không vì', 'Âm thanh là sóng cơ học lan truyền dao động qua các hạt vật chất; trong môi trường chân không không có các phân tử/nguyên tử vật chất nên âm thanh không thể truyền qua.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nêu ý nghĩa câu thơ của Bác Hồ “Mùa xuân là Tết trồng cây / Làm cho đất nước càng ngày càng xuân”.', 'Câu thơ của Bác Hồ nhấn mạnh ý nghĩa và khẳng định lợi ích vô cùng to lớn, lâu bền của việc trồng cây đối với môi trường và đời sống đất nước.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thức ăn đã tiêu hóa thành chất dinh dưỡng đi đến các bộ phận khác nhau của cơ thể bằng con đường nào?', 'Sau khi hấp thu từ hệ tiêu hóa vào máu, các chất dinh dưỡng được dòng máu trong hệ tuần hoàn vận chuyển đi khắp các mô, tế bào trong cơ thể.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Máu có màu đỏ sẫm là biểu hiện của', 'Theo đáp án công bố của đề thi (Câu 23 chọn A), máu đi theo chu trình trao đổi khí từ tim qua phổi có sự thay đổi sắc tố; khi nghèo O2/giàu CO2 máu có màu đỏ thẫm/sẫm.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chiều vận chuyển các chất trong mạch gỗ và mạch rây có gì khác nhau?', 'Mạch gỗ vận chuyển nước và muối khoáng từ rễ đi lên các cơ quan phía trên; mạch rây vận chuyển các sản phẩm hữu cơ từ lá đi xuống rễ, quả, thân để dự trữ và sử dụng.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nước ảnh hưởng thế nào đến quá trình đóng mở khí khổng của cây?', 'Cơ chế đóng mở khí khổng dựa vào sự trương nước: tế bào hình hạt đậu no nước làm thành mỏng căng ra kéo thành dày theo hướng mở rộng lỗ khí; khi thiếu nước tế bào xẹp lại khiến lỗ khí khép kín.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình quang hợp góp phần làm giảm lượng khí nào sau đây trong khí quyển?', 'Quang hợp hấp thụ lượng lớn khí carbon dioxide (CO2) từ bầu khí quyển để biến đổi thành chất hữu cơ và giải phóng O2, làm giảm hiệu ứng nhà kính.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Những sinh vật nào sau đây có khả năng quang hợp trong điều kiện có ánh sáng ?' || chr(10) || '(1) Tảo lục.' || chr(10) || '(2) Thực vật.' || chr(10) || '(3) Ruột khoang.' || chr(10) || '(4) Nấm.' || chr(10) || '(5) Trùng roi xanh.', 'Các sinh vật chứa chất diệp lục có khả năng tự dưỡng quang hợp gồm: Tảo lục (1), Thực vật (2), Trùng roi xanh khi có ánh sáng (5).', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Em hãy cho biết trao đổi chất ở động vật gồm những hoạt động nào sau đây?' || chr(10) || '(1) Lấy thức ăn.' || chr(10) || '(2) Nghiền nhỏ thức ăn.' || chr(10) || '(3) Biến đổi thức ăn.' || chr(10) || '(4) Thải ra.' || chr(10) || '(5) Tăng nhiệt độ.', 'Trao đổi chất ở động vật bao gồm các khâu chính: lấy chất dinh dưỡng/thức ăn từ môi trường (1), biến đổi các chất (3), và đào thải các chất cặn bã ra ngoài môi trường (4).', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Em hãy vận dụng kiến thức về hô hấp tế bào, giải thích vì sao con người khi ở trên đỉnh núi cao thường thở nhanh hơn so với khi ở vùng đồng bằng?', 'Lên đỉnh núi cao không khí bị loãng làm giảm phân áp và nồng độ oxygen; cơ thể phải tăng nhịp hô hấp thở sâu, thở nhanh hơn để bù đắp đủ nhu cầu oxygen duy trì chu trình hô hấp tế bào.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi nghe đến bệnh bướu cổ là bệnh lí rất thường gặp ở nước ta do nguyên nhân thiếu chất khoáng iodine, mẹ Lan quyết định bổ sung iodine trong khẩu phần ăn hàng ngày cho cả gia đình. Theo em, mẹ Lan nên bổ sung loại thực phẩm nào để có đủ iodine ngăn ngừa bệnh bướu cổ?', 'Hải sản biển (các loại cá biển, tôm, cua biển và đặc biệt là rong/tảo biển) là nguồn thực phẩm tự nhiên chứa hàm lượng vi chất iodine dồi dào nhất.', 'KHTN 7 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 Cuối kì 1 KHTN Lớp 7 (60 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 7. LỚP 7 - GIỮA HỌC KỲ 2 (Nguồn: insert code lớp 7 giữa kì 2.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_20 DOUBLE PRECISION := 0.5; -- Đề 20 câu, thang điểm 10.0
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 7
    SELECT id INTO v_class_id FROM grades WHERE grade = 7;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 7', 7, 'Chương trình Khoa học tự nhiên THCS Lớp 7', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 2
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 2;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 2', 2, 'Học kỳ 2 năm học Lớp 7', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 7 HỌC KỲ 2
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN7_HK2';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 7', 'KHTN7_HK2', 'Môn Khoa học Tự nhiên Lớp 7 - Học kỳ 2', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA KÌ 2 KHTN 7 - ĐỀ SỐ 1 (20 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN7_01',
        'Đề thi giữa kì 2 KHTN 7 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Công thức tính vận tốc là:', 'Công thức tính vận tốc là: v = s / t.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Liên kết giữa nguyên tử oxygen và 2 nguyên tử hydrogen trong phân tử nước là loại liên kết:', 'Liên kết giữa nguyên tử oxygen và 2 nguyên tử hydrogen trong phân tử nước là loại liên kết cộng hóa trị.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ở thực vật có hai loại mô phân sinh là:', 'Ở thực vật có hai loại mô phân sinh chính là mô phân sinh đỉnh và mô phân sinh bên.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vật nào sau đây dao động với tần số lớn nhất?', 'Tần số dao động của con lắc: f₁ = 1500 / 30 = 50 Hz. Mặt trống: f₂ = 1000 / 10 = 100 Hz. Dây đàn: f₃ = 988 / 2 = 494 Hz. Dây cao su: f₄ = 1900 / 15 ≈ 126,6 Hz. Do đó, dây đàn có tần số lớn nhất (f₃ > f₄ > f₂ > f₁).', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trái Đất là một nam châm khổng lồ vì:', 'Trái Đất là một nam châm khổng lồ vì kim của la bàn đặt trên mặt đất luôn định hướng theo trục Bắc – Nam.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cơ chế của hình thức trao đổi khí giữa cơ thể sinh vật với môi trường là:', 'Sự trao đổi khí giữa cơ thể và môi trường tuân theo cơ chế khuếch tán, di chuyển từ vùng có nồng độ phân tử khí cao sang vùng có nồng độ phân tử khí thấp hơn.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một oxide có công thức XO₂, trong đó X chiếm 30,43% (khối lượng). Biết khối lượng phân tử của oxide bằng 46 amu. Công thức hóa học của oxide trên là', 'Ta có: M_X + 2 × 16 = 46 ⇒ M_X = 14 amu (X là Nitrogen - N). Do đó công thức hóa học của oxide là NO₂.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn đáp án đúng khi nói về nhu cầu ánh sáng của cây ưa sáng cây ưa bóng.', 'Theo đáp án đề thi lựa chọn phương án A (lưu ý nội dung chuẩn: cây ưa sáng cần nhiều ánh sáng mạnh, cây ưa bóng không cần nhiều ánh sáng).', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Chiếu một tia sáng tới chếch một góc 20° vào một gương phẳng ta được tia sáng phản xạ tạo với tia sáng tới một góc', 'Góc hợp bởi tia tới và mặt gương là 20° ⇒ góc tới i = 90° - 20° = 70°. Theo định luật phản xạ ánh sáng: i'' = i = 70°. Góc tạo bởi tia phản xạ và tia tới là i + i'' = 70° + 70° = 140°.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các tác nhân của môi trường tác động tới cơ thể sinh vật được gọi là gì?', 'Các nhân tố môi trường tác động lên cơ thể sinh vật được gọi là các kích thích, gây ra các phản ứng cảm ứng tương ứng của sinh vật.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Ghép một nội dung ở cột A với một nội dung phù hợp ở cột B.', 'Tốc độ chuyển động cho biết sự nhanh, chậm của chuyển động (1 - c); Tốc độ chuyển động được xác định bằng quãng đường đi được trong một đơn vị thời gian (2 - d); Đơn vị tốc độ phụ thuộc vào đơn vị độ dài và đơn vị thời gian (3 - a); Đơn vị của tốc độ là m/s và km/h (4 - b).', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn đáp án đúng khi nói về nhu cầu ánh sáng của cây ưa sáng cây ưa bóng. (Câu 12)', 'Các cây ưa sáng cần nhiều ánh sáng mạnh (như ngô, thông, dừa,...), còn các cây ưa bóng không cần nhiều ánh sáng (như lá lốt, trầu không,...).', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Trong hợp chất này, nguyên tử C sử dụng bao nhiêu electron lớp ngoài cùng của nó để tạo liên kết cộng hóa trị với các nguyên tử H?', 'Nguyên tử carbon có 4 electron lớp ngoài cùng, do đó nó dùng cả 4 electron này góp chung với các nguyên tử hydrogen để tạo 4 liên kết cộng hóa trị bền vững.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Loài thực vật nào sau đây có thể thích nghi với môi trường khô hạn, thiếu nước kéo dài?', 'Cây xương rồng có thân mọng nước và lá tiêu giảm thành gai để hạn chế sự thoát hơi nước, giúp thích nghi tốt với môi trường khô hạn.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Lúc 1h sáng, một đoàn tàu hỏa chạy từ ga A đến ga B với tốc độ 60 km/h, đến ga B lúc 2h và dừng ở ga B 15 phút. Sau đó đoàn tàu tiếp tục chạy với vận tốc cũ thì đến ga C lúc 3h15 phút. Hình vẽ nào sau đây biểu diễn đúng đồ thị quãng đường – thời gian của đoàn tàu nói trên?', 'Tổng thời gian chuyển động từ A đến C là 3h15 - 1h = 2h 15 phút (loại A). Khi tàu nghỉ tại B 15 phút, quãng đường không đổi nên đồ thị có đoạn nằm ngang (loại C và D), do đó đồ thị B đúng.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong tế bào của hầu hết các sinh vật nhân thực, quá trình hô hấp xảy ra trong loại bào quan nào?', 'Ở sinh vật nhân thực, ti thể là bào quan chuyên trách thực hiện quá trình hô hấp tế bào để giải phóng năng lượng ATP.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một cành hoa bị héo sau khi được cắm vào nước một thời gian thì cành hoa tươi trở lại. Cấu trúc nào sau đây có vai trò quan trọng trong hiện tượng trên?', 'Mạch gỗ có chức năng vận chuyển nước và muối khoáng hòa tan từ dưới lên thân và lá, giúp cành hoa bù nước và tươi trở lại.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nhận xét nào sau đây là đúng khi nói về quá trình quang hợp và hô hấp?', 'Quang hợp và hô hấp là hai quá trình ngược nhau nhưng phụ thuộc lẫn nhau, vì sản phẩm của quang hợp (chất hữu cơ, O₂) là nguyên liệu cho hô hấp, và ngược lại sản phẩm hô hấp (CO₂, H₂O) là nguyên liệu cho quang hợp.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Kết luận nào sau đây là đúng?', 'Các vật có bề mặt mềm, xốp, gồ ghề/sần sùi phản xạ âm kém (hấp thụ âm tốt). Các vật cứng, bề mặt phẳng, nhẵn phản xạ âm tốt.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng nào dưới đây cho thấy sự vận chuyển chất hữu cơ theo mạch rây từ lá đến các bộ phận khác của cây?', 'Mạch rây nằm ở phần vỏ thân cây dẫn chất hữu cơ từ lá xuống; khi cạo bỏ một khoanh vỏ, dòng vận chuyển bị chặn lại làm chất hữu cơ tích tụ ứ đọng khiến mép vỏ phía trên phình to.', 'KHTN 7 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI GIỮA KÌ 2 KHTN 7 - ĐỀ SỐ 2 (20 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN7_02',
        'Đề thi giữa kì 2 KHTN 7 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 20 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chỉ ra phát biểu sai. Ảnh của một vật qua gương phẳng', 'Ảnh của một vật qua gương phẳng là ảnh ảo, kích thước luôn bằng kích thước vật. Do đó phương án B sai.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nước là dung môi hòa tan nhiều chất trong cơ thể sống vì chúng có', 'Nước là dung môi hòa tan nhiều chất trong cơ thể sống vì chúng có tính phân cực. Tính phân cực của nước được thể hiện ở vùng oxygen mang điện tích âm và vùng hydrogen mang điện tích dương.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào của lá giúp lá nhận được nhiều ánh sáng?', 'Đặc điểm của lá giúp lá nhận được nhiều ánh sáng là do phiến lá có dạng bản mỏng, giúp tăng diện tích bề mặt tiếp xúc để hấp thu ánh sáng.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một thanh nam châm bị gãy làm hai thì', 'Một thanh nam châm bị gãy làm hai thì mỗi nửa tạo thành một nam châm độc lập và đều có đầy đủ hai cực Bắc – Nam.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho biết mỗi một cặp electron dùng chung giữa các nguyên tử C và nguyên tử H tướng ứng với một liên kết cộng hóa trị, thì nguyên tử C tạo được bao nhiêu liên kết cộng hóa trị với các nguyên tử H?', 'Mỗi nguyên tử hydrogen có 1 electron, cần thêm 1 electron để đạt cấu hình bền vững; nguyên tử carbon có 4 electron lớp ngoài cùng nên góp chung 4 electron với 4 nguyên tử hydrogen, tạo ra 4 liên kết cộng hóa trị.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Ở thực vật, các chất nào dưới đây thường được vận chuyển từ rễ lên lá?', 'Ở thực vật, nước và chất khoáng hòa tan thường được dòng mạch gỗ vận chuyển theo chiều từ rễ lên lá.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nam châm vĩnh cửu có:', 'Bất kì nam châm nào cũng có hai cực: cực luôn chỉ về hướng Bắc gọi là cực Bắc, cực luôn chỉ về hướng Nam gọi là cực Nam.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các phát biểu sau:' || chr(10) || '(1) Cung cấp nguồn chất hữu cơ làm thức ăn cho sinh vật dị dưỡng.' || chr(10) || '(2) Cung cấp khí oxygen.' || chr(10) || '(3) Điều hòa trực tiếp mực nước biển.' || chr(10) || '(4) Tăng hàm lượng khí carbon dioxide trong không khí.' || chr(10) || 'Số phát biểu đúng về vai trò của quang hợp là', 'Quang hợp cung cấp nguồn chất hữu cơ cho sinh vật (1), cung cấp khí oxygen và điều hòa không khí (2). Theo tài liệu trắc nghiệm đã chọn B (gồm 3 ý).', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nồng độ khí carbon dioxide thuận lợi cho hô hấp tế bào khoảng:', 'Hàm lượng khí carbon dioxide trong không khí đạt khoảng 0,03% là điều kiện thuận lợi nhất cho quá trình hô hấp tế bào.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Cho hai thanh nam châm thẳng đặt gần nhau có đường sức từ như hình vẽ. Đầu A, B của hai thanh nam châm tương ứng với từ cực nào?', 'Quy ước đường sức từ ở bên ngoài thanh nam châm đi ra từ cực Bắc và đi vào cực Nam. Các đường sức từ đều đi ra khỏi đầu A và đầu B nên cả A và B đều là cực Bắc.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sự xuất hiện hoa và hạt của cây hoa hướng dương là dấu hiệu của sự:', 'Sự xuất hiện các cơ quan sinh sản như hoa và hạt của cây là dấu hiệu phân hóa hình thái, đánh dấu sự phát triển ở thực vật.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hoạt động nào sau đây giúp bảo vệ tim và mạch máu?', 'Duy trì lối sống lành mạnh, giữ tinh thần thoải mái, không lạm dụng chất béo và chất kích thích giúp bảo vệ sức khỏe hệ tim mạch.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chữ SW trên la bàn có nghĩa là hướng:', 'Kí hiệu SW viết tắt từ Southwest, quy ước chỉ hướng Tây Nam trên la bàn.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình nào sau đây là quá trình sinh trưởng của thực vật?', 'Sinh trưởng là sự gia tăng kích thước và khối lượng của các bộ phận cơ thể do sự tăng số lượng và kích thước tế bào (sự tăng kích thước của cành).', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một số nguyên tố khoáng cây trồng cần một lượng rất nhỏ nhưng không thể thiếu như Cu, Bo, Mo. Các nguyên tố này thường tham gia cấu tạo nên', 'Các nguyên tố vi lượng như Cu, Bo, Mo có vai trò cấu tạo nên thành phần hoạt hóa của các enzyme xúc tác các phản ứng trao đổi chất trong tế bào.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tử sodium có 11 electron ở vỏ nguyên tử. Hạt nhân của nguyên tử sodium có số proton là:', 'Nguyên tử trung hòa về điện nên số proton trong hạt nhân bằng số electron ở lớp vỏ: P = E = 11.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đặc điểm nào sau đây không phải đặc điểm của hợp chất ion?', 'Các hợp chất ion thường tồn tại ở thể rắn, khó nóng chảy, khó bay hơi và đa số dễ tan trong nước. Do đó "khó tan trong nước" không phải đặc điểm chung của hợp chất ion.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong quá trình quang hợp ở thực vật, diệp lục có vai trò:', 'Sắc tố diệp lục đóng vai trò hấp thụ năng lượng ánh sáng mặt trời (quang năng) và chuyển hóa thành dạng hóa năng phục vụ các phản ứng quang hợp.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố Y tạo nên kim cương, than chì. Nguyên tử của nguyên tố Y có 2 lớp electron, trong đó lớp ngoài cùng có 4 electron. Kí hiệu hóa học của nguyên tử Y là gì và Y thuộc chu kì nào, nhóm nào trong bảng tuần hoàn?', 'Nguyên tố tạo nên kim cương và than chì là Carbon (C). Y có 2 lớp electron nên thuộc chu kì 2, có 4 electron lớp ngoài cùng nên thuộc nhóm IVA.', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong môi trường không có chất độc hại. Khi trồng cây bên bờ ao sau một thời gian thì rễ cây sẽ phát triển theo hướng nào?', 'Rễ cây có tính hướng nước dương, do đó rễ sẽ sinh trưởng uốn cong và vươn dài về phía có nguồn nước (phía bờ ao).', 'KHTN 7 - GK2 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 Giữa kì 2 KHTN Lớp 7 (40 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 8. LỚP 7 - CUỐI HỌC KỲ 2 (Nguồn: insert code lớp 7 kì 2.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_28 DOUBLE PRECISION := ROUND((10.0 / 28.0)::numeric, 4); -- ~0.3571 điểm/câu cho đề 28 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 7
    SELECT id INTO v_class_id FROM grades WHERE grade = 7;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 7', 7, 'Chương trình Khoa học tự nhiên THCS Lớp 7', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 2
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 2;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 2', 2, 'Học kỳ 2 năm học Lớp 7', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 7 HỌC KỲ 2
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN7_HK2';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 7', 'KHTN7_HK2', 'Môn Khoa học Tự nhiên Lớp 7 - Học kỳ 2', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI KHTN 7 - ĐỀ SỐ 1 (28 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_KHTN7_01',
        'Đề thi KHTN 7 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra gồm 28 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hóa trị của Fe trong công thức Fe2O3 là:', 'Gọi hóa trị của Fe trong phân tử là x. Áp dụng quy tắc hóa trị ta có: x × 2 = II × 3 ⇒ x = III.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thực vật sinh trưởng được là nhờ hoạt động của:', 'Quá trình sinh trưởng của cơ thể thực vật diễn ra chủ yếu nhờ hoạt động phân chia liên tục của các tế bào thuộc mô phân sinh.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng nào sau đây là tập tính bẩm sinh ở động vật?', 'Tập tính bẩm sinh sinh ra đã có, mang tính di truyền và đặc trưng cho loài, ở đây là tiếng kêu của ve sầu vào ngày hè oi ả. Các trường hợp còn lại đều là tập tính học được qua huấn luyện/trải nghiệm.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hình thức dinh dưỡng phổ biến của động vật là:', 'Động vật không tự tổng hợp được chất hữu cơ từ các chất vô cơ mà phải lấy chất dinh dưỡng từ thức ăn bên ngoài nên hình thức phổ biến là dinh dưỡng dị dưỡng.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thói quen nào sau đây tốt cho việc học tập?', 'Ngồi học chăm chú nghe giảng là thói quen rèn luyện sự tập trung và tiếp thu kiến thức chủ động, rất tốt cho việc học tập.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hình thức sinh sản trong đó cơ thể mới được hình thành từ cơ quan rễ, thân, lá của cơ thể mẹ gọi là', 'Sinh sản sinh dưỡng là hình thức sinh sản vô tính ở thực vật mà cá thể mới được tái sinh trực tiếp từ các cơ quan sinh dưỡng như rễ, thân hoặc lá của cây mẹ.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một thanh kim loại được cọ xát và mang điện tích dương. Thanh kim loại khi đó đang ở trạng thái nào sau đây?', 'Vật mang điện tích dương do mất bớt electron nhiễm điện âm khi bị cọ xát cọ quẹt, làm số proton nhiều hơn số electron.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Biện pháp canh tác nào sau đây là ứng dụng ảnh hưởng của độ ẩm trong việc điều khiển sinh trưởng và phát triển của cây trồng?', 'Cung cấp độ ẩm thích hợp qua việc tưới nước đúng kĩ thuật giúp điều khiển và tối ưu sự sinh trưởng, phát triển của cây trồng.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Kết quả của quá trình phát triển ở thực vật có hoa là:', 'Phát triển ở thực vật là toàn bộ các biến đổi cấu trúc, mô và cơ quan bao gồm cả sinh trưởng, biệt hóa hình thành các cơ quan rễ, thân, lá, hoa, quả.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Quả được hình thành do sự biến đổi của:', 'Sau khi diễn ra quá trình thụ tinh, noãn phát triển thành hạt còn bầu nhụy dày lên biến đổi phát triển thành quả chứa hạt.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Biện pháp vun gốc cho cây khoai tây dựa trên', 'Rễ và củ khoai tây có tính hướng đất dương (hướng xuống đất) và tránh ánh sáng (hướng sáng âm); vun đất vào gốc tạo bóng tối và môi trường thuận lợi để củ phát triển tốt, không bị xanh đắng.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đâu không phải là ưu điểm của hình thức mang thai và sinh con ở động vật có vú so với hình thức đẻ trứng ở các động vật khác?', 'Cả động vật đẻ trứng hay đẻ con theo phương thức hữu tính đều sinh ra con non mang tổ hợp đặc điểm của cả bố và mẹ, nên việc tạo ra con giống mẹ không phải là ưu điểm riêng biệt của việc mang thai và đẻ con.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đa số các loài thực vật trên cạn hấp thụ nước và muối khoáng chủ yếu nhờ:', 'Tế bào lông hút ở rễ là bộ phận chuyên trách bề mặt tiếp xúc trực tiếp với đất để hút nước và các khoáng chất hòa tan.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các hiện tượng sau đây, hiện tượng nào không phải là cảm ứng ở thực vật?', 'Lá cây xoan rụng do lực cơ học cơ bản của luồng gió mạnh tác động cuốn gãy, không phải phản ứng sinh học chủ động của cơ thể thực vật đối với kích thích từ môi trường.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Biện pháp nào sau đây thường được sử dụng để làm tăng số con của cá mè và cá trắm?', 'Người ta tiêm hormone hoặc hóa chất kích thích tổng hợp vào cá cái để kích thích trứng rụng đồng loạt, sau đó tiến hành thụ tinh nhân tạo nhằm nâng cao tối đa tỷ lệ cá con nở.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng cảm ứng nào sau đây được con người ứng dụng để nhận biết sự thay đổi của thời tiết?', 'Dựa vào độ cao khi bay của chuồn chuồn (bay thấp khi độ ẩm không khí cao, bay cao khi trời nắng khô ráo) người xưa đúc kết kinh nghiệm dự báo mưa nắng thời tiết.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hình thức sinh sản nào dưới đây là hình thức sinh sản hữu tính?', 'Đẻ con ở lớp Thú có sự kết hợp thụ tinh giữa tinh trùng (giao tử đực) và trứng (giao tử cái) tạo thành hợp tử, do đó đây là hình thức sinh sản hữu tính.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Mục đích của việc thắp đèn vào ban đêm cho cây thanh long nhằm:', 'Cây thanh long là cây ngày dài; thắp đèn ngắt quãng đêm tối làm kéo dài thời gian chiếu sáng, kích thích cây phân hóa mầm hoa và tạo quả trái vụ mang lại hiệu quả kinh tế cao.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một trùng giày sinh sản bằng cách tự phân chia thành hai tế bào con. Quá trình này được gọi là:', 'Sinh sản bằng cách tự phân tách cơ thể đơn bào thành hai cá thể con tương đương nhau được gọi là hình thức sinh sản phân đôi.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chúng ta có thể nhân giống cây khoai tây bằng bộ phận:', 'Củ khoai tây thực chất là dạng thân củ biến dạng chứa chất dự trữ; từ các mắt (chồi) trên thân củ có thể mọc thành các cây con mới.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tập tính học được khác tập tính bẩm sinh ở đặc điểm là:', 'Tập tính học được hình thành qua trải nghiệm và học hỏi riêng của từng cá thể trong đời sống, do đó mang tính đặc trưng riêng cho từng cá thể chứ không đồng nhất cả loài như tập tính bẩm sinh.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Việc làm trụ cho cây hồ tiêu giúp cho cây sinh trưởng nhanh, phát triển tốt dựa trên hiện tượng cảm ứng nào sau đây?', 'Cây hồ tiêu có thân leo bám; việc cắm trụ tựa giúp thân tiêu quấn bám theo hướng tiếp xúc, nâng cao khả năng vươn lên đón ánh sáng và sinh trưởng ổn định.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các tác nhân của môi trường tác động tới cơ thể sinh vật được gọi là:', 'Mọi nhân tố từ môi trường trong hoặc ngoài tác động trực tiếp lên cơ thể sinh vật được gọi là các kích thích.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi ta sử dụng la bàn để xác định phương hướng thì kim la bàn không chỉ đúng hướng Bắc địa lí vì:', 'Cực từ và cực địa lí của Trái Đất bị lệch nhau một góc (trục từ trường không trùng khít với trục tự quay địa lí của Trái Đất) nên kim la bàn chỉ hướng theo đường sức từ chứ không chỉ đúng tuyệt đối cực Bắc địa lí.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nếu thiếu nước, sự sinh trưởng và phát triển của thực vật sẽ', 'Nước là dung môi hòa tan, nguyên liệu cho quá trình trao đổi chất và duy trì sức trương tế bào; thiếu nước sẽ khiến cây giảm tốc độ phân chia tế bào làm sinh trưởng chậm dần hoặc ngừng hẳn.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng cảm ứng nào sau đây có tác nhân kích thích là ánh sáng?', 'Hiện tượng thân cây mọc uốn cong về nguồn sáng là phản ứng sinh trưởng hướng sáng dương, tác nhân kích thích trực tiếp là ánh sáng.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi quan sát cây lá bỏng, nhận thấy trên lá cây mọc ra mầm cây con. Sau đó, cây con rơi xuống đất rồi phát triển thành cây bỏng trưởng thành. Hình thức sinh sản của cây lá bỏng là', 'Cây con được tạo ra trực tiếp từ mép lá (cơ quan sinh dưỡng) của cây mẹ mà không qua thụ tinh, đây là hình thức sinh sản sinh dưỡng.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đối với cây ăn quả, việc người nông dân thường nuôi ong trong các vườn cây ăn quả sẽ có tác dụng:', 'Hoạt động tìm kiếm mật hoa của loài ong giúp phấn hoa được mang phát tán giữa các nhị và nhụy, làm gia tăng tối đa tỷ lệ thụ phấn chéo và tạo quả đậu hạt cho vườn cây.', 'KHTN 7 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI KHTN 7 - ĐỀ SỐ 2 (28 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_KHTN7_02',
        'Đề thi KHTN 7 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra gồm 28 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng cây phát triển về phía có nguồn dinh dưỡng gọi là', 'Hiện tượng cây phát triển về phía có nguồn dinh dưỡng gọi là tính hướng hóa.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sinh sản vô tính là:', 'Sinh sản vô tính là hình thức sinh sản không có sự kết hợp giữa yếu tố đực và yếu tố cái.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Người trưởng thành cần cung cấp trung bình bao nhiêu lít nước mỗi ngày?', 'Người trưởng thành cần cung cấp trung bình 1,5 - 2 lít nước mỗi ngày.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hình thức sinh sản trong đó cơ thể mới được hình thành từ cơ quan rễ, thân, lá của cơ thể mẹ gọi là', 'Hình thức sinh sản trong đó cơ thể mới được hình thành từ cơ quan rễ, thân, lá của cơ thể mẹ gọi là sinh sản sinh dưỡng.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các cây sau, cây nào không thích hợp với điều kiện khí hậu nóng?', 'Trong các cây sau, cây không thích hợp với điều kiện khí hậu nóng là cây bắp cải.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong nuôi cấy phôi động vật, người ta có thể kích thích trứng chín và rụng bằng cách nào sau đây?', 'Trong nuôi cấy phôi động vật, người ta có thể kích thích trứng chín và rụng bằng cách sử dụng hormone nhân tạo.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình di chuyển của hạt phấn đến đầu nhụy gọi là', 'Quá trình di chuyển của hạt phấn đến đầu nhụy gọi là thụ phấn.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Ví dụ nào dưới đây không phải là tập tính của động vật?', 'Ví dụ không phải là tập tính của động vật là: Người giảm cân sau khi ốm.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trường hợp nào sau đây không phải là sinh sản vô tính ở thực vật?', 'Cây táo non phát triển từ hạt là hình thức sinh sản hữu tính vì hạt được tạo ra từ quá trình thụ tinh giữa giao tử đực và giao tử cái.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các nhóm động vật sau, nhóm động vật nào có đặc điểm con non nở ra từ trứng có đặc điểm hình thái khác với cơ thể trưởng thành?', 'Các loài động vật phát triển qua biến thái có con non mang hình thái khác cơ thể trưởng thành là: Ruồi, muỗi, ếch, châu chấu, bướm.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây không đúng khi nói về quả?', 'Quả do bầu nhụy sinh trưởng dày lên phát triển thành, không phải do phôi phân chia tạo thành.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Từ trường gây ra hiện tượng nào sau đây?', 'Từ trường làm đồng hồ chạy sai giờ và gây ra hiện tượng cực quang ở các địa cực.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các nhóm sinh vật sau, nhóm sinh vật nào có hình thức sinh sản vô tính?', 'Các loài sinh vật đều có hình thức sinh sản vô tính là: Sứa, thủy tức, trùng roi, hải quỳ, san hô.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hình thức sinh sản mà mỗi mảnh nhỏ riêng biệt của cơ thể mẹ có thể phát triển thành một cơ thể mới hoàn chỉnh gọi là', 'Hình thức sinh sản mà mỗi mảnh nhỏ riêng biệt của cơ thể mẹ có thể phát triển thành một cơ thể mới hoàn chỉnh gọi là phân mảnh.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vì sao khi nhân giống cam, chanh, bưởi, hồng xiêm,... người ta thường chiết cành mà không sử dụng phương pháp giâm cành?', 'Các giống cây cam, chanh, bưởi, hồng xiêm,... có thời gian ra rễ rất chậm nên nếu giâm cành cành dễ bị héo chết trước khi kịp bén rễ; do đó người ta dùng phương pháp chiết cành.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ nào dùng để xác định phương hướng địa lí?', 'Dụng cụ dùng để xác định phương hướng địa lí là la bàn.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Để chuyển hàng là những tấm sắt nặng hàng chục tấn dễ dàng, ta có thể dùng cần cẩu gắn nam châm điện. Đến nơi xếp dỡ hàng, người điều khiển cần', 'Người điều khiển thay đổi hoạt động dòng điện để nhả vật liệu.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Thủy tức sinh sản bằng hình thức', 'Thủy tức sinh sản vô tính phổ biến bằng hình thức nảy chồi.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sự kết hợp của giao tử cái với giao tử đực tạo thành hợp tử xảy ra trong giai đoạn nào của quá trình sinh sản hữu tính ở động vật?', 'Giai đoạn kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử gọi là giai đoạn thụ tinh.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Bạn Lan tiến hành cắt một đoạn thân cây hoa hồng cắm vào trong cát ẩm. Sau 3 tuần, bạn Lan nhận thấy phần cắm xuống cát đã mọc ra rễ non. Trong trường hợp này, bạn Lan đã sử dụng phương pháp nhân giống nào sau đây?', 'Cắt một đoạn thân/cành cắm vào giá thể ẩm để phát triển thành cây con hoàn chỉnh là phương pháp giâm cành.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Khi đi ra vườn, Lan thấy mỗi lần chạm tay vào cây trinh nữ, lá của cây lại nhanh chóng cụp xuống. Hiện tượng này là', 'Hiện tượng lá cây trinh nữ cụp xuống khi có tác động cơ học là phản ứng cảm ứng của thực vật.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Vì sao người ta có thể sử dụng ong mắt đỏ để diệt sâu hại cây trồng?', 'Ong mắt đỏ có tập tính đẻ trứng vào trong trứng sâu hại; ấu trùng ong nở ra ăn chất dinh dưỡng bên trong làm trứng sâu hỏng và chết.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây không đúng khi nói về cơ quan sinh sản của thực vật có hoa?', 'Hoa đơn tính là hoa chỉ chứa nhị hoặc chỉ chứa nhụy; phát biểu B cho rằng có cả hai là sai.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Gần đến Tết, người ta thường thắp đèn vào những ruộng hoa cúc vì', 'Hoa cúc là cây ngày ngắn; thắp thêm ánh sáng đèn nhân tạo vào ban đêm làm ngắt quãng độ dài đêm tối nhằm kìm hãm ra hoa quá sớm, căn chỉnh hoa nở đúng Tết.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Yếu tố nào dưới đây tham gia điều hòa sinh sản ở sinh vật?', 'Hormone là yếu tố bên trong trực tiếp điều hòa và điều khiển quá trình sinh sản ở cơ thể sinh vật.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Sự thống nhất giữa tế bào với cơ thể và môi trường được thể hiện thông qua', 'Mối quan hệ thống nhất biện chứng giữa cấp độ tế bào, cơ thể sinh vật và môi trường sống biểu hiện qua chuỗi các hoạt động sống của cơ thể.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho các ví dụ sau: Ở thực vật, cà chua phải đủ 14 lá mới ra hoa, cây chuối thì một năm mới bắt đầu ra hoa; có những loài ra hoa, kết quả liên tục như cây đậu cô ve, đu đủ,… Các ví dụ trên chứng minh ảnh hưởng của nhân tố nào đến sinh sản ở thực vật?', 'Các hiện tượng sinh trưởng đến kích thước, số lượng lá hoặc thời gian xác định trước khi ra hoa phản ánh sự phụ thuộc của sinh sản vào độ tuổi sinh sản.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong cơ thể người, nước và chất dinh dưỡng được vận chuyển đến các tế bào và các cơ quan trong cơ thể thông qua hoạt động của', 'Dòng máu trong hệ tuần hoàn đảm nhận vai trò vận chuyển nước, chất khoáng, chất dinh dưỡng cùng oxygen đến nuôi dưỡng các tế bào và cơ quan khắp cơ thể.', 'KHTN 7 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 KHTN Lớp 7 (56 câu hỏi)!';
END $$;


-- ==============================================================================
-- PHẦN 9. LỚP 8 - GIỮA HỌC KỲ 1 (Nguồn: insert code lớp 8 giữa kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_12 DOUBLE PRECISION := ROUND((10.0 / 12.0)::numeric, 4); -- ~0.8333 điểm/câu cho đề 12 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 8
    SELECT id INTO v_class_id FROM grades WHERE grade = 8;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 8', 8, 'Chương trình Khoa học tự nhiên THCS Lớp 8', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 8', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 8 HỌC KỲ 1
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN8_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 8', 'KHTN8_HK1', 'Môn Khoa học Tự nhiên Lớp 8 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA KÌ 1 KHTN 8 - ĐỀ SỐ 1 (12 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN8_01',
        'Đề thi giữa kì 1 KHTN 8 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 12 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ như hình vẽ dưới đây có tên là gì?', 'Dụng cụ trong hình có dạng hình nón đáy phẳng, cổ hẹp là bình tam giác.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong số những quá trình dưới đây, cho biết có bao nhiêu quá trình xảy ra biến đổi hóa học?' || chr(10) || '(a) quẹt diêm vào bỏ bao thấy diêm cháy lửa' || chr(10) || '(b) thả vỏ trứng gà vào cốc nước giấm thấy có bọt khí sủi lên' || chr(10) || '(c) cho nước vào tủ lạnh để làm đá' || chr(10) || '(d) thổi hơi vào cốc nước vôi trong thấy có vẩn đục xuất hiện', 'Các quá trình xảy ra biến đổi hóa học là (a), (b), (d) do có sự tạo thành chất mới. Quá trình (c) chỉ là sự chuyển thể của nước (biến đổi vật lí).', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phản ứng hóa học là', 'Phản ứng hóa học là quá trình biến đổi từ chất này thành chất khác.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Những loại phản ứng nào sau đây cần phải cung cấp năng lượng trong quá trình phản ứng?', 'Phản ứng quang hợp là phản ứng thu nhiệt, cần cung cấp năng lượng ánh sáng liên tục trong quá trình diễn ra. Các phản ứng đốt cháy còn lại đều là phản ứng tỏa nhiệt.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Số nguyên tử hydrogen trong 0,05 mol khí hydrogen là', '1 mol phân tử H2 chứa 6,022 × 10²³ phân tử. Số phân tử H2 trong 0,05 mol là 0,05 × 6,022 × 10²³ = 3,011 × 10²² phân tử. Vì mỗi phân tử H2 gồm 2 nguyên tử H, số nguyên tử H phải là 2 × 3,011 × 10²² ≈ 6,02 × 10²² nguyên tử (đáp án nguồn chọn A theo số phân tử H2).', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Tính khối lượng (theo đơn vị gam) của hỗn hợp gồm 0,1 mol NaCl và 0,2 mol đường (C12H22O11)', 'Khối lượng hỗn hợp = m(NaCl) + m(đường) = 0,1 × 58,5 + 0,2 × 342 = 5,85 + 68,4 = 74,25 g.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khí nào sau đây nặng hơn không khí?', 'Phân tử khối trung bình của không khí là 29 g/mol. Khí O2 có M = 32 g/mol > 29 nên nặng hơn không khí (d = 32/29 ≈ 1,1). Các khí H2 (2), CH4 (16), He (4) đều nhẹ hơn không khí.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây là base không tan', 'Al(OH)3 là base không tan (kết tủa keo trắng). NaOH và Ba(OH)2 là base tan tốt, Ca(OH)2 tan ít.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây làm đổi màu quỳ tím thành đỏ:', 'Dung dịch acid làm quỳ tím chuyển sang màu đỏ. H2SO4 là sulfuric acid nên làm quỳ tím đổi màu đỏ.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Để điều chế CO2 trong phòng thí nghiệm, người ta cho đá vôi (rắn) phản ứng với dung dịch hydrochloric acid. Phản ứng xảy ra như sau:' || chr(10) || 'CaCO3 + 2HCl → CaCl2 + H2O + CO2.' || chr(10) || 'Biện pháp nào sau đây không làm phản ứng xảy ra nhanh hơn?', 'Thêm CaCl2 (sản phẩm phản ứng) không làm tăng tốc độ phản ứng. Các biện pháp đập nhỏ đá vôi (tăng diện tích tiếp xúc), tăng nhiệt độ và tăng nồng độ HCl đều làm tăng tốc độ phản ứng.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khối lượng của CuSO4 có trong 100ml dung dịch CuSO4 0,5 M là', 'Số mol CuSO4: n = C_M × V = 0,5 × 0,1 = 0,05 mol. Khối lượng CuSO4: m = n × M = 0,05 × 160 = 8 gam.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho 6,48 g Al tác dụng hoàn toàn với dung dịch HCl dư, thu được muối AlCl3 và khí H2. Thể tích khí H2 ở 25 °C, 1 bar là', 'Số mol Al = 6,48 / 27 = 0,24 mol. Phương trình phản ứng: 2Al + 6HCl → 2AlCl3 + 3H2. Theo phương trình: n(H2) = 1,5 × n(Al) = 0,36 mol. Thể tích khí H2 ở 25 °C, 1 bar (điều kiện chuẩn mới): V = 0,36 × 24,79 = 8,9244 L.', 'KHTN 8 - GK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI GIỮA KÌ 1 KHTN 8 - ĐỀ SỐ 2 (12 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK1_KHTN8_02',
        'Đề thi giữa kì 1 KHTN 8 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 1 gồm 12 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ như hình vẽ dưới đây có tên là gì?', 'Dụng cụ hình ống trụ hẹp đáy tròn thường dùng trong các thí nghiệm hóa học là ống nghiệm.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong số những quá trình dưới đây, cho biết có bao nhiêu quá trình xảy ra biến đổi hóa học?' || chr(10) || '(a) thanh sắt để ngoài không khí lâu ngày tạo gỉ sắt' || chr(10) || '(b) dây tốc bóng đèn nóng và sáng lên khi có dòng điện đi qua' || chr(10) || '(c) đốt cháy rượu để nướng mực' || chr(10) || '(d) phơi quần áo ướt ngoài trời nắng thấy quần áo khô', 'Có 2 quá trình xảy ra biến đổi hóa học là (a) và (c) vì có sự biến đổi chất tạo thành chất mới. Quá trình (b) chỉ là hiện tượng vật lí phát nhiệt/phát quang, (d) là hiện tượng nước bay hơi (chuyển thể).', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Câu nào sau đây sai?', 'Trong phản ứng hóa học, chỉ có liên kết giữa các nguyên tử thay đổi (các phân tử bị phá vỡ, liên kết lại), còn các nguyên tử luôn được bảo toàn chứ không bị phân chia.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong sản xuất và đời sống, các phản ứng tỏa nhiệt không có ứng dụng nào trong các ứng dụng sau?', 'Động cơ điện hoạt động nhờ nguồn năng lượng điện (điện năng), không phải do nhiệt năng từ các phản ứng tỏa nhiệt cung cấp trực tiếp.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'a mol khí chlorine có chứa 12,04 . 10^23 phân tử Cl2. Giá trị của a là:', 'Số mol khí Cl2 là a = (12,04 . 10^23) / (6,022 . 10^23) ≈ 2 mol.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Số mol của nguyên tử Cl có trong 36,5 gam hydrochloric acid (HCl)', 'Ta có nHCl = 36,5 / 36,5 = 1 mol. Trong 1 phân tử HCl chứa 1 nguyên tử Cl nên nCl = nHCl = 1 mol.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tỉ khối của khí He so với khí O2 là:', 'Áp dụng công thức tính tỉ khối: d(He/O2) = MHe / MO2 = 4 / 32 = 0,125.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây là oxide lưỡng tính', 'Al2O3 vừa có thể tác dụng với acid vừa có thể tác dụng với base nên là oxide lưỡng tính.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây không làm đổi màu quỳ tím', 'NaCl là muối trung hòa tạo bởi base mạnh và acid mạnh nên không làm đổi màu quỳ tím. (KOH làm quỳ hóa xanh; HCl và CH3COOH làm quỳ hóa đỏ).', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Những yếu tố nào sau đây ảnh hưởng đến tốc độ của một phản ứng hóa học?' || chr(10) || '(1) diện tích bề mặt tiếp xúc' || chr(10) || '(2) nhiệt độ' || chr(10) || '(3) nồng độ' || chr(10) || '(4) chất xúc tác', 'Cả 4 yếu tố: diện tích bề mặt tiếp xúc, nhiệt độ, nồng độ các chất phản ứng và chất xúc tác đều ảnh hưởng đến tốc độ của phản ứng hóa học.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Rót 300ml nước vào bình có chứa sẵn 200ml sodium chloride 0,5M và lắc đều, thu được dung dịch sodium chloride mới. Nồng độ mol của dung dịch thu được là', 'Số mol NaCl ban đầu: n = CM . V = 0,5 . 0,2 = 0,1 mol. Tổng thể tích dung dịch sau khi pha loãng: Vsau = 200 + 300 = 500 ml = 0,5 lít. Nồng độ mol mới là: CM = 0,1 / 0,5 = 0,2 M.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho 2,9748 L khí CO2 (ở 25 °C, 1 bar) tác dụng hoàn toàn với dung dịch Ba(OH)2 dư, thu được muối BaCO3 và H2O. Khối lượng muối BaCO3 kết tủa là', 'Số mol CO2 ở 25 °C, 1 bar: nCO2 = 2,9748 / 24,79 = 0,12 mol. Phương trình phản ứng: CO2 + Ba(OH)2 -> BaCO3 + H2O. Theo phương trình, nBaCO3 = nCO2 = 0,12 mol. Khối lượng kết tủa thu được: mBaCO3 = 0,12 . 197 = 23,64 gam.', 'KHTN 8 - GK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 Giữa kì 1 KHTN Lớp 8 (24 câu hỏi và ảnh kèm theo)!';
END $$;


-- ==============================================================================
-- PHẦN 10. LỚP 8 - CUỐI HỌC KỲ 1 (Nguồn: insert code lớp 8 kì 1.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_30 DOUBLE PRECISION := ROUND((10.0 / 30.0)::numeric, 4); -- ~0.3333 điểm/câu cho đề 30 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 8
    SELECT id INTO v_class_id FROM grades WHERE grade = 8;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 8', 8, 'Chương trình Khoa học tự nhiên THCS Lớp 8', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 1
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 1;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 1', 1, 'Học kỳ 1 năm học Lớp 8', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 8 HỌC KỲ 1
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN8_HK1';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 8', 'KHTN8_HK1', 'Môn Khoa học Tự nhiên Lớp 8 - Học kỳ 1', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI HỌC KÌ 1 KHTN 8 - ĐỀ SỐ 1 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN8_01',
        'Đề thi học kì 1 KHTN 8 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trong các quá trình sau, quá trình nào xảy ra biến đổi vật lí?', 'Nước hóa rắn là sự thay đổi trạng thái từ thể lỏng sang thể rắn, không có sự tạo thành chất mới nên là hiện tượng vật lí.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Nguyên tố nào sau đây không phải là nguyên tố đa lượng trong phân bón cho cây trồng?', 'Các nguyên tố dinh dưỡng đa lượng chính trong phân bón gồm Nitrogen (N), Phosphorus (P) và Potassium (K). Sodium không phải là nguyên tố đa lượng cho cây trồng.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phản ứng đốt cháy cồn là phản ứng gì?', 'Các phản ứng đốt cháy đều là phản ứng tỏa nhiệt ra môi trường xung quanh.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khối lượng mol phân tử nước là bao nhiêu?', 'Khối lượng mol phân tử của H2O bằng: 2 × 1 + 16 = 18 g/mol.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Trộn lẫn 2 lít dung dịch urea 0,02 M (dung dịch A) với 3 lít dung dịch urea 0,1 M (dung dịch B), thu được 5 lít dung dịch C. Tính nồng độ mol của dung dịch C?', 'Số mol urea trong dung dịch A: nA = 2 × 0,02 = 0,04 mol.' || chr(10) || 'Số mol urea trong dung dịch B: nB = 3 × 0,1 = 0,3 mol.' || chr(10) || 'Tổng số mol sau khi trộn: nC = 0,04 + 0,3 = 0,34 mol.' || chr(10) || 'Nồng độ mol của dung dịch C: CM = 0,34 / 5 = 0,068 M.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn khẳng định đúng trong các khẳng định sau? Trong một phản ứng phản ứng hóa học:', 'Theo định luật bảo toàn khối lượng, trong một phản ứng hóa học, tổng khối lượng của các chất sản phẩm bằng tổng khối lượng của các chất tham gia phản ứng.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Phương trình đúng của phosphorus cháy trong không khí, biết sản phẩm tạo thành là P2O5:', 'Phosphorus cháy trong không khí tạo diphosphorus pentoxide, phương trình hóa học được cân bằng đúng là: 4P + 5O2 → 2P2O5.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Để điều chế được 12,8 gam copper (Cu) theo phương trình: H2 + CuO → H2O + Cu cần dùng bao nhiêu lít khí H2 ở điều kiện chuẩn (25 °C và 1 bar)?', 'Số mol Cu: nCu = 12,8 / 64 = 0,2 mol.' || chr(10) || 'Theo phương trình: nH2 = nCu = 0,2 mol.' || chr(10) || 'Thể tích khí H2 ở điều kiện chuẩn (25 °C, 1 bar): V = 0,2 × 24,79 = 4,958 lít.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Yếu tố nào dưới đây được sử dụng để làm tăng tốc độ phản ứng khi rắc men vào tinh bột đã được nấu chín để ủ ancol (rượu)?', 'Men rượu chứa các enzyme đóng vai trò là chất xúc tác sinh học giúp tăng tốc độ phản ứng lên men.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Dãy dung dịch/chất lỏng nào sau đây làm đổi màu quỳ tím thành đỏ?', 'Các dung dịch CH3COOH, HCl, HNO3 đều có tính acid nên làm đổi màu quỳ tím sang đỏ.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây không phản ứng với sắt?', 'Sắt không phản ứng với dung dịch muối ăn NaCl. Với các acid còn lại, sắt phản ứng giải phóng khí H2.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Có thể dùng chất nào sau đây để khử độ chua của đất?', 'Vôi tôi (Ca(OH)2) là một base có tính kiềm, được sử dụng để trung hòa acid và khử độ chua trong đất.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chất nào sau đây là oxide lưỡng tính?', 'Al2O3 là oxide lưỡng tính vì vừa có thể tác dụng với dung dịch acid, vừa có thể tác dụng với dung dịch base.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các muối nào sau đây đều tan tốt trong nước?', 'Các muối CuSO4, FeCl3, Pb(NO3)2 đều tan tốt trong nước (BaSO4, PbSO4, CaCO3 là các muối không tan).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ở thể lỏng dưới áp suất thường, khối lượng riêng của nước có giá trị lớn nhất ở nhiệt độ:', 'Ở thể lỏng dưới áp suất tiêu chuẩn, nước có khối lượng riêng lớn nhất tại nhiệt độ 4 °C (khoảng 1000 kg/m³).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu đúng trong các câu sau:', 'Khi chuyển động trên mặt phẳng nằm ngang, lực nén vuông góc với mặt tiếp xúc (áp lực) có độ lớn bằng chính trọng lượng của đoàn tàu.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Áp suất mà chất lỏng tác dụng lên một điểm phụ thuộc:', 'Công thức tính áp suất chất lỏng là p = d × h, do đó áp suất phụ thuộc vào trọng lượng riêng của chất lỏng và độ cao (độ sâu) của cột chất lỏng phía trên điểm đó.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hiện tượng nào sau đây xảy ra đối với khối lượng riêng của nước khi đun nước trong một bình thủy tinh?', 'Khi đun nóng, nước nở ra làm thể tích tăng lên, trong khi khối lượng không đổi, dẫn đến khối lượng riêng (D = m / V) giảm xuống.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Niu tơn (N) là đơn vị của:', 'Áp lực là lực tác dụng vuông góc lên mặt bị ép, đơn vị của lực là Niu tơn (N).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Công thức tính lực đẩy Archimedes là:', 'Lực đẩy Archimedes được xác định theo công thức FA = d × V (trong đó d là trọng lượng riêng của chất lỏng, V là thể tích phần chất lỏng bị vật chiếm chỗ).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Moment lực tác dụng lên vật là đại lượng:', 'Moment lực là đại lượng đặc trưng cho tác dụng làm quay của lực tác dụng lên một vật quanh một trục hoặc một điểm.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cho m, V lần lượt là khối lượng và thể tích của một vật. Biểu thức xác định khối lượng riêng của chất tạo thành vật đó có dạng nào sau đây?', 'Khối lượng riêng của một chất được tính bằng thương số giữa khối lượng và thể tích của vật: D = m / V.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Muốn tăng áp suất thì:', 'Từ công thức p = F / S, để làm tăng áp suất p, ta cần tăng áp lực F hoặc giảm diện tích bị ép S (hoặc kết hợp cả hai).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Hút bớt không khí trong một vỏ hộp đựng sữa bằng giấy, ta thấy vỏ hộp giấy bị bẹp lại vì:', 'Khi hút bớt không khí bên trong, áp suất khí bên trong hộp giảm xuống, áp suất khí quyển bên ngoài lớn hơn tác dụng lực ép làm hộp sữa bẹp lại theo mọi phía.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn phát biểu sai khi nói về tác dụng của đòn bẩy?', 'Đòn bẩy được sử dụng nhằm mục đích giảm lực kéo hoặc đẩy tác dụng lên vật, giúp thao tác dễ dàng hơn và có lợi về lực, không phải để tăng lực kéo/đẩy vật.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Dụng cụ nào sau đây không phải là ứng dụng của đòn bẩy?', 'Kéo, kìm, cái mở nắp chai đều hoạt động dựa trên nguyên lí đòn bẩy quay quanh một điểm tựa. Cái cưa hoạt động dựa trên chuyển động tịnh tiến kéo - đẩy các răng cưa để ma sát cắt vật thể.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một vật ở trong nước chịu tác dụng của những lực nào?', 'Vật ở trong lòng chất lỏng chịu tác dụng chủ yếu của hai lực: trọng lực kéo vật xuống dưới và lực đẩy Archimedes của nước hướng thẳng đứng từ dưới lên.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Khi một vật rắn quay quanh một trục thì tổng moment lực tác dụng lên vật có giá trị:', 'Khi vật rắn đang quay (có gia tốc góc biến đổi chuyển động quay), tổng các moment lực tác dụng lên vật quanh trục quay có giá trị khác 0 (khi tổng moment lực bằng 0 thì vật ở trạng thái cân bằng không quay).', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Ở 25 °C, độ tan của AgNO3 trong nước là 222 g. Nồng độ phần trăm của dung dịch AgNO3 bão hoà ở 25 °C là:', 'Độ tan S = 222 g nghĩa là trong 100 g nước hòa tan tối đa 222 g AgNO3. Khối lượng dung dịch bão hòa là 222 + 100 = 322 g. Nồng độ phần trăm: C% = (222 / 322) × 100% ≈ 68,94%.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Gió gây ra áp suất lên bất kì một bề mặt nào mà gió thổi vào. Nếu gió gây ra một áp suất 2 000 Pa lên một cánh cửa có diện tích là 3,5 m2 thì áp lực tác dụng lên cánh cửa bằng bao nhiêu?', 'Áp dụng công thức tính áp lực từ áp suất: F = p × S = 2000 × 3,5 = 7000 N.', 'KHTN 8 - HK1 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


    -- ====================================================================
    -- PHẦN II: ĐỀ THI HỌC KÌ 1 KHTN 8 - ĐỀ SỐ 2 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_CK1_KHTN8_02',
        'Đề thi học kì 1 KHTN 8 Kết nối tri thức - Đề số 2',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra học kì 1 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 2.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Oxide nào sau đây là oxide trung tính?', 'CO là oxide trung tính (không phản ứng với acid, base và không tạo muối).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Dãy các base tan trong nước gồm:', 'Base tan (kiềm) là các base tạo thành từ kim loại kiềm và kiềm thổ như: Na, K, Ca, Ba.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Base kiềm nào tan tốt nhất trong nước', 'NaOH là base kiềm có độ tan rất lớn trong nước ở điều kiện thường.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Acid là phân tử khi tan trong nước phân li ra', 'Theo thuyết Arenius, acid là những phân tử khi tan trong nước phân li tạo cation H+.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phản ứng tỏa nhiệt là:', 'Phản ứng tỏa nhiệt giải phóng năng lượng nhiệt ra môi trường, làm cho nhiệt độ hệ/hỗn hợp phản ứng tăng cao hơn môi trường xung quanh.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phản ứng hóa học là', 'Phản ứng hóa học là quá trình biến đổi chất này thành chất khác.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Quá trình biến đổi hóa học là:', 'Quá trình biến đổi hóa học là quá trình có sự tạo thành chất mới.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phép đổi nào sau đây đúng?', 'Ta có 1 kg/m³ = 0,001 g/cm³ ⇒ 1300 kg/m³ = 1,3 g/cm³.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong phòng thí nghiệm, cần điều chế 2,479 L khí hydrogen (ở 25 °C, 1 Bar). Người ta cho zinc (Zn) tác dụng với dung dịch sulfuric acid H2SO4 9,8% (hiệu suất phản ứng 100%). Khối lượng dung dịch H2SO4 cần dùng là:', 'Số mol H₂ cần điều chế: n = 2,479 / 24,79 = 0,1 mol.' || chr(10) || 'Phương trình phản ứng: Zn + H₂SO₄ → ZnSO₄ + H₂↑.' || chr(10) || 'Theo phương trình: nH₂SO₄ = nH₂ = 0,1 mol.' || chr(10) || 'Khối lượng chất tan: mH₂SO₄ = 0,1 × 98 = 9,8 g.' || chr(10) || 'Khối lượng dung dịch cần dùng: mdd = (9,8 × 100%) / 9,8% = 100 g.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đơn vị của moment lực là:', 'Moment lực được tính bằng tích của lực với cánh tay đòn (M = F · d), có đơn vị là N.m.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Hai quả cầu đặc có kích thước y như nhau, một quả bằng đồng và một quả bằng sắt được treo vào 2 đầu của đòn bẩy tại 2 điểm A và B. Biết OA = OB. Lúc này đòn bẩy sẽ...', 'Vì cùng kích thước (thể tích V bằng nhau) nhưng khối lượng riêng của đồng (8900 kg/m³) lớn hơn của sắt (7800 kg/m³), nên trọng lượng quả cầu bằng đồng lớn hơn quả cầu bằng sắt, làm đòn bẩy lệch về phía quả cầu bằng đồng.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các dụng cụ sau đây, dụng cụ nào là đòn bẩy?', 'Mái chèo hoạt động dựa trên nguyên tắc đòn bẩy quay quanh điểm tựa gắn trên mạn thuyền.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Một hòn bi ở trong nước chịu tác dụng của những lực nào?', 'Hòn bi ở trong nước chịu tác dụng của trọng lực (hướng thẳng đứng xuống dưới) và lực đẩy Archimedes của nước (hướng thẳng đứng lên trên).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Công thức nào sau đây là công thức tính áp suất?', 'Áp suất p được tính bằng áp lực F trên một đơn vị diện tích bị ép S: p = F / S.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây về khối lượng riêng là đúng?', 'Khối lượng riêng của một chất được định nghĩa là khối lượng của một đơn vị thể tích chất đó (D = m / V).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Moment của ngẫu lực phụ thuộc vào', 'Đáp án được đưa ra trong đề thi là C (vị trí trục quay của vật).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Moment của ngẫu lực phụ thuộc vào (Câu 17)', 'Câu hỏi trùng lặp trong đề gốc, đáp án tương ứng là C.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phát biểu nào sau đây đúng khi nói về lực đẩy Archimedes?', 'Lực đẩy Archimedes luôn có phương thẳng đứng, chiều hướng từ dưới lên trên.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Điều nào sau đây đúng khi nói về áp suất chất lỏng?', 'Chất lỏng gây ra áp suất theo mọi phương lên đáy bình, thành bình và các vật nằm trong lòng nó.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Người ta thường nói sắt nặng hơn nhôm. Câu giải thích nào sau đây là không đúng?', 'So sánh "nặng hơn" ở đây mang bản chất là so sánh khối lượng riêng hay trọng lượng riêng của hai chất (hoặc so sánh hai khối có cùng thể tích), chứ không thể so sánh trọng lượng của hai vật tùy ý bất kì.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Trong các hiện tượng sau đây, hiện tượng nào không do áp suất khí quyển gây ra?', 'Vật rơi từ trên cao xuống là do tác dụng của trọng lực (lực hút của Trái Đất), không phải do áp suất khí quyển gây ra.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Nhận xét nào sau đây là sai khi nói về áp suất khí quyển?', 'Công thức p = d · h (hay p = D · g · h) dùng để tính áp suất chất lỏng tĩnh, không áp dụng trực tiếp p = D · h cho áp suất khí quyển vì mật độ khí quyển giảm dần theo độ cao.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Tác dụng của áp lực phụ thuộc vào:', 'Tác dụng của áp lực (chính là áp suất p = F / S) phụ thuộc đồng thời vào độ lớn của áp lực F và diện tích mặt bị ép S.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Cho 2,9748 L khí CO2 (ở 25 °C, 1 bar) tác dụng hoàn toàn với dung dịch Ba(OH)2 dư, thu được muối BaCO3 và H2O. Khối lượng muối BaCO3 kết tủa là', 'Số mol CO₂: n = 2,9748 / 24,79 = 0,12 mol.' || chr(10) || 'Phương trình: CO₂ + Ba(OH)₂ → BaCO₃↓ + H₂O.' || chr(10) || 'Theo phản ứng: nBaCO₃ = nCO₂ = 0,12 mol.' || chr(10) || 'Khối lượng kết tủa: mBaCO₃ = 0,12 × 197 = 23,64 g.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Đốt cháy hoàn toàn 6,4 gam sulfur (S) trong khí oxygen (O2) dư, sau phản ứng thu được V lít khí sulfur dioxide (SO2) ở điều kiện chuẩn. Giá trị của V là', 'Số mol sulfur: nS = 6,4 / 32 = 0,2 mol.' || chr(10) || 'Phương trình: S + O₂ → SO₂ (t°).' || chr(10) || 'Theo phản ứng: nSO₂ = nS = 0,2 mol.' || chr(10) || 'Thể tích khí thu được ở điều kiện chuẩn (25 °C, 1 bar): V = 0,2 × 24,79 = 4,958 lít.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phân bón hóa học dư thừa sẽ:', 'Phân bón hóa học dùng dư thừa sẽ tồn dư trong môi trường, làm thoái hóa đất và gây ô nhiễm các nguồn nước ngầm, nước mặt.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phân đạm cung cấp nguyên tố gì cho cây trồng?', 'Phân đạm cung cấp nguyên tố dinh dưỡng Nitrogen (N) kích thích quá trình sinh trưởng và phát triển lá cây.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Phân bón trung lượng cung cấp những nguyên tố dinh dưỡng nào cho đất?', 'Phân bón trung lượng cung cấp các nguyên tố cần thiết ở mức vừa phải gồm Calcium (Ca), Magnesium (Mg) và Sulfur (S).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Muối không tan trong nước là:', 'BaSO4 là kết tủa trắng, không tan trong nước và acid loãng. Các muối CuSO4, Na2SO4, Ca(NO3)2 tan tốt trong nước.', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 2)
    VALUES ('SINGLE_CHOICE', 'Điền vào chỗ trống "Muối là những hợp chất được tạo ra khi thay thế ion…trong…bằng ion kim loại hoặc ion ammonium (NH4+)"', 'Định nghĩa: Muối là những hợp chất được tạo ra khi thay thế ion H+ trong acid bằng ion kim loại hoặc ion ammonium (NH₄⁺).', 'KHTN 8 - HK1 - Đề 2', NOW(), NOW()) RETURNING id INTO v_q_id;

    RAISE NOTICE 'Đã chèn thành công Đề 1 và Đề 2 Cuối kì 1 KHTN Lớp 8 (60 câu hỏi)!';
END $$;


-- ==============================================================================
-- PHẦN 11. LỚP 8 - GIỮA HỌC KỲ 2 (Nguồn: insert code lớp 8 giữa kì 2.txt)
-- ==============================================================================
DO $$
DECLARE
    v_class_id BIGINT;
    v_semester_id BIGINT;
    v_subject_id BIGINT;
    v_exam_id BIGINT;
    v_q_id BIGINT;
    v_point_30 DOUBLE PRECISION := ROUND((10.0 / 30.0)::numeric, 4); -- ~0.3333 điểm/câu cho đề 30 câu
BEGIN
    -- 1. LẤY HOẶC TẠO KHỐI LỚP 8
    SELECT id INTO v_class_id FROM grades WHERE grade = 8;
    IF v_class_id IS NULL THEN
        VALUES ('Lớp 8', 8, 'Chương trình Khoa học tự nhiên THCS Lớp 8', NOW(), NOW())
        RETURNING id INTO v_class_id;
    END IF;

    -- 2. LẤY HOẶC TẠO HỌC KỲ 2
    SELECT id INTO v_semester_id FROM semesters WHERE class_id = v_class_id AND semester_order = 2;
    IF v_semester_id IS NULL THEN
        VALUES (v_class_id, 'Học kỳ 2', 2, 'Học kỳ 2 năm học Lớp 8', NOW(), NOW())
        RETURNING id INTO v_semester_id;
    END IF;

    -- 3. LẤY HOẶC TẠO MÔN KHTN 8 HỌC KỲ 2
    SELECT id INTO v_subject_id FROM subjects WHERE semester_id = v_semester_id AND code = 'KHTN8_HK2';
    IF v_subject_id IS NULL THEN
        VALUES (v_semester_id, 'Khoa học Tự nhiên 8', 'KHTN8_HK2', 'Môn Khoa học Tự nhiên Lớp 8 - Học kỳ 2', NOW(), NOW())
        RETURNING id INTO v_subject_id;
    END IF;

    -- ====================================================================
    -- PHẦN I: ĐỀ THI GIỮA HỌC KÌ 2 KHTN 8 - ĐỀ SỐ 1 (30 CÂU)
    -- ====================================================================
    VALUES (
        v_subject_id,
        'DE_GK2_KHTN8_01',
        'Đề thi giữa học kì 2 KHTN 8 Kết nối tri thức - Đề số 1',
        'DEFAULT',
        'Khoa học Tự nhiên',
        'Đề kiểm tra giữa học kì 2 gồm 30 câu trắc nghiệm khách quan chuẩn SGK Kết nối tri thức - Đề số 1.',
        NOW(), NOW()
    ) RETURNING id INTO v_exam_id;

    -- Câu 1 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Đưa tay hai vật đã bị nhiễm điện lại gần nhau', 'Đưa hai vật đã bị nhiễm điện lại gần nhau có thể hút hoặc đẩy nhau tùy theo chúng nhiễm điện cùng dấu hay trái dấu (cùng dấu thì đẩy nhau, trái dấu thì hút nhau).', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 2 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Điền từ thích hợp vào chỗ trống. Các vật nhiễm điện ………… thì đẩy nhau, ………….. thì hút nhau', 'Hai vật nhiễm điện cùng loại (cùng dấu) thì đẩy nhau, khác loại (trái dấu) thì hút nhau.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 3 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu sai. Các vật nhiễm ……….. thì đẩy nhau.', 'Các vật nhiễm điện tích khác nhau (trái dấu) thì hút nhau chứ không đẩy nhau.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 4 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Những ngày hanh khô, khi chải tóc khô bằng lược nhựa thì nhiều sợi tóc bị lược nhựa hút kéo thẳng ra vì:', 'Khi thời tiết hanh khô, chải tóc bằng lược nhựa thì lược cọ xát với tóc nên bị nhiễm điện, do đó nó có khả năng hút và kéo làm cho sợi tóc thẳng ra.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 5 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Tại sao cánh quạt trong các quạt điện thường xuyên quay mà vẫn có rất nhiều bụi dính vào', 'Cánh quạt khi quay cọ xát mạnh với các lớp không khí xung quanh nên bị nhiễm điện do cọ xát, từ đó có khả năng hút các hạt bụi nhỏ bay lơ lửng trong không khí bám vào.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 6 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu giải thích đúng. Tại sao khi lau kính bằng các khăn vải khô ta thấy không sạch bụi', 'Khi lau kính bằng khăn vải khô, mặt kính bị cọ xát nên nhiễm điện và hút các hạt bụi, sợi tơ vải xung quanh làm kính không sạch hẳn.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 7 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Làm thế nào để biết một vật bị nhiễm điện?', 'Vật nhiễm điện có tương tác lực điện (hút hoặc đẩy) rõ ràng với một vật khác cũng đã bị nhiễm điện mang điện tích xác định.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 8 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Loại hạt nào dưới đây khi chuyển động có hướng thì không thành dòng điện?', 'Dòng điện là dòng chuyển dời có hướng của các hạt mang điện tích. Nguyên tử ở trạng thái trung hòa về điện nên khi chuyển động có hướng không tạo thành dòng điện.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 9 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một đèn pin đang sáng nếu ta tháo pin ra và đảo chiều một cục pin thì hiện tượng gì sẽ xảy ra?', 'Đảo chiều một cục pin làm triệt tiêu hiệu điện thế của bộ nguồn (hoặc không tạo mạch kín đúng chiều tiếp xúc), dẫn đến mạch không có dòng điện và đèn không sáng.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 10 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đang có dòng điện chạy trong vật nào dưới đây?', 'Đồng hồ dùng pin đang hoạt động nghĩa là có dòng điện liên tục chạy qua mạch máy đồng hồ.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 11 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Các dụng cụ nào sau đây không phải là nguồn điện:', 'Quạt điện là thiết bị tiêu thụ điện năng để biến đổi thành cơ năng, không phải là nguồn cung cấp điện.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 12 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu sai', 'Độ mạnh hay yếu, hoạt động đúng định mức của thiết bị phụ thuộc vào thông số định mức của thiết bị đó chứ không phải nguồn điện càng lớn thì thiết bị càng mạnh.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 13 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Để đèn xe máy phát sáng thì đèn phải được nối với nguồn điện. Vật trong xe máy, nguồn điện là thiết bị nào sau đây?', 'Trong xe máy, nguồn điện một chiều được lưu trữ và cung cấp bởi bình ắc-qui (hoặc máy phát khi nổ máy).', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 14 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Nguồn điện được kí hiệu bằng kí hiệu nào sau đây:', 'Trong sơ đồ mạch điện, nguồn điện (1 pin/ắc-quy) được quy ước vẽ gồm hai vạch song song, một vạch dài mảnh (cực dương) và một vạch ngắn dày (cực âm) tương ứng Hình A.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 15 (Đề 1 - Ảnh)
    VALUES ('SINGLE_CHOICE', 'Bóng đèn được kí hiệu bằng kí hiệu nào sau đây:', 'Bóng đèn được quy ước kí hiệu bằng một vòng tròn có dấu gạch chéo chữ X ở giữa tương ứng Hình C.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 16 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Sơ đồ mạch điện là:', 'Sơ đồ mạch điện là bản vẽ biểu diễn cấu tạo và đường đi của mạch điện thông qua các kí hiệu quy ước của các linh kiện/bộ phận.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 17 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Kí hiệu các bộ phận trong mạch điện mang ý nghĩa:', 'Việc sử dụng kí hiệu giúp đơn giản hóa sơ đồ biểu diễn so với hình ảnh cấu tạo phức tạp ngoài thực tế, giúp dễ đọc và thi công lắp ráp.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 18 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Một mạng điện thắp sáng gồm:', 'Một mạch điện thắp sáng đơn giản hoàn chỉnh bao gồm: nguồn điện, thiết bị tiêu thụ (bóng đèn), khóa đóng cắt (công tắc) và dây dẫn nối các bộ phận.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 19 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chiều dòng điện chạy trong mạch điện kín được quy ước như thế nào?', 'Quy ước chiều dòng điện trong mạch kín: chạy từ cực dương qua dây dẫn và các thiết bị điện tới cực âm của nguồn.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 20 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Đâu không phải thiết bị điện:', 'Ô tô là một phương tiện giao thông hoàn chỉnh tổng hợp nhiều hệ cơ khí - động cơ nhiệt/điện, không xếp vào nhóm các linh kiện/thiết bị điện cơ bản.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 21 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Thanh thủy tinh sau khi được cọ xát bằng mảnh lụa thì có khả năng:', 'Sau khi cọ xát với mảnh lụa, thanh thủy tinh bị nhiễm điện dương nên có khả năng hút các vật nhẹ cách điện như mẩu nilông vụn.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 22 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Dùng mảnh vải khô để cọ xát, thì có thể làm cho vật nào dưới đây mang điện tích:', 'Thanh nhựa là vật liệu cách điện nên điện tích sau khi cọ xát dễ tích tụ cục bộ trên bề mặt, làm cho thanh nhựa mang điện tích rõ rệt.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 23 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Điền từ thích hợp vào chỗ trống. Nhiều vật sau khi cọ xát có khả năng … bóng đèn bút thử điện', 'Điện thế tích tụ do cọ xát trên một số vật có thể đủ lớn để phóng điện làm lóe sáng bóng đèn khí neon của bút thử điện.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 24 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Một trong những nguyên nhân tạo thành các đám mây dông bị nhiễm điện là do:', 'Mây dông nhiễm điện chủ yếu do sự cọ xát đối lưu mạnh mẽ giữa các tinh thể băng, giọt nước nhỏ li ti bên trong các luồng không khí bốc lên cao.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 25 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Khi đưa một cây thước nhựa lại gần một sợi tóc', 'Thước nhựa thông thường không hút tóc, nhưng sau khi cọ xát vào mảnh vải khô sẽ bị nhiễm điện nên có khả năng hút các sợi tóc nhẹ.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 26 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Vào những ngày như thế nào thì các thí nghiệm về sự nhiễm điện do cọ xát thực hiện dễ thành công?', 'Không khí hanh khô ít độ ẩm hạn chế sự rò rỉ điện tích qua hơi nước vào môi trường, giúp các vật tích điện giữ được điện tích lâu hơn.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 27 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn câu trả lời đúng. Thước nhựa sau khi được cọ xát bằng mảnh vải khô sẽ có khả năng hút các vụn giấy nhỏ. Vậy khi đưa mảnh vải khô lại gần các mẩu giấy vụn, mảnh vải sẽ hút hay đẩy chúng? Tại sao?', 'Khi cọ xát, cả hai vật tham gia cọ xát đều bị nhiễm điện (nhiễm điện trái dấu), do đó mảnh vải khô cũng mang điện tích và có khả năng hút các mẩu giấy vụn nhẹ.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 28 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Cầu chì có tác dụng gì?', 'Khi dòng điện tăng quá mức cho phép (quá tải hoặc đoản mạch), dây chì tự nóng chảy đứt mạch để bảo vệ an toàn cho các thiết bị điện khác.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 29 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Chọn phát biểu đúng', 'Định nghĩa: Dòng điện không đổi là dòng điện có chiều và cường độ không thay đổi theo thời gian.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;

    -- Câu 30 (Đề 1)
    VALUES ('SINGLE_CHOICE', 'Thiết bị nào sau đây là nguồn điện?', 'Acquy là nguồn điện hóa học có khả năng tích trữ và phát ra dòng điện một chiều cung cấp cho mạch tiêu thụ.', 'KHTN 8 - GK2 - Đề 1', NOW(), NOW()) RETURNING id INTO v_q_id;


