    INSERT INTO answer (question_id, type, content, is_correct, created_date, updated_date) VALUES
    (v_q_id, 'TEXT', 'Khi tế bào hạt đậu trương nước, thành tế bào căng ra làm lỗ khí mở; khi tế bào hạt đậu mất nước, thành tế bào trở lại bình thường làm lỗ khí đóng lại.', true, NOW(), NOW()),
