    INSERT INTO answer (question_id, type, content, is_correct, created_date, updated_date) VALUES
    (v_q_id, 'TEXT', 'Do có những người chưa quen hoặc không kịp thích nghi với điều kiện khí hậu trên cao, sẽ dễ dẫn đến nguy cơ mắc một số bệnh lý cấp tính nguy hiểm đến tính mạng, chẳng hạn như sốc độ cao cấp tính.', false, NOW(), NOW()),
    (v_q_id, 'TEXT', 'Khi ở trên đỉnh núi cao, không khí loãng, nồng độ oxygen thấp hơn so với ở vùng đồng bằng. Để lấy đủ lượng oxygen cần thiết cho hoạt động hô hấp tế bào, con người thường phải thở nhanh hơn so với khi ở vùng đồng bằng.', true, NOW(), NOW()),
    (v_q_id, 'TEXT', 'Do một số người dân địa phương sống ở trên vùng núi cao nhưng mất khả năng thích nghi với điều kiện khí hậu, thở nhanh hơn là biểu hiện của say núi mạn tính – tình trạng thiếu oxy trong thời gian dài.', false, NOW(), NOW()),
    (v_q_id, 'TEXT', 'Do một số người có bệnh về đường hô hấp nên sẽ thở nhanh hơn khi đứng trên đỉnh núi.', false, NOW(), NOW());
